              name={collapsed.databaseMgmt ? "chevron-down" : "chevron-up"}
              size={16}
              className="ml-auto opacity-50"
            />
          </h2>
          {!collapsed.databaseMgmt && (
            <>
              <p className="text-xs text-slate-400 mb-4">
                ΓÜá∩╕Å Danger Zone: These operations permanently delete data and
                cannot be undone.
              </p>

              <div className="space-y-3">
                {/* Translation Migration Button */}
                <button
                  onClick={async () => {
                    if (
                      !confirm(
                        "≡ƒöù Link Existing Translations?\n\nThis will:\n1. Find all translated questions (Chinese, Japanese, Korean, etc.)\n2. Match them with their English originals\n3. Ensure both share the same uniqueId\n4. Enable language switching\n\nThis is SAFE and won't delete any data.\n\nProceed?"
                      )
                    )
                      return;

                    try {
                      showMessage(
                        "≡ƒöä Starting translation migration...",
                        10000
                      );

                      // Call the Cloud Function
                      const { migrateTranslationsViaCloudFunction } =
                        await import("../services/cloudFunctions.js");

                      const result =
                        await migrateTranslationsViaCloudFunction();

                      if (result.success) {
                        const { stats } = result;
                        showMessage(
                          `Γ£à Migration complete!\n\n` +
                            `≡ƒôè Statistics:\n` +
                            `- Total questions: ${stats.totalQuestions}\n` +
                            `- Total translations: ${stats.totalTranslations}\n` +
                            `- Already linked: ${stats.alreadyLinked}\n` +
                            `- Newly linked: ${stats.newlyLinked}\n` +
                            `- Orphaned: ${stats.orphaned}\n\n` +
                            `Refresh the page to see results.`,
                          10000
                        );
                      }
                    } catch (error) {
                      showMessage(
                        `Γ¥î Migration failed: ${error.message}`,
                        5000
                      );
                      console.error(error);
                    }
                  }}
                  className="w-full px-4 py-3 bg-blue-900/30 hover:bg-blue-900/50 text-blue-300 rounded font-bold transition-all flex items-center justify-center gap-2 border border-blue-700/50"
                >
                  <Icon name="link" size={16} />
                  Link Existing Translations (Enable Language Switching)
                </button>

                <button
                  onClick={async () => {
                    if (
                      !confirm(
                        "ΓÜá∩╕Å DELETE ALL QUESTIONS?\n\nThis will permanently delete ALL questions from the database for ALL users.\n\nThis action CANNOT be undone!\n\nType 'DELETE' to confirm."
                      )
                    )
                      return;

                    const confirmText = prompt("Type DELETE to confirm:");
                    if (confirmText !== "DELETE") {
                      showMessage("Γ¥î Deletion cancelled", 3000);
                      return;
                    }

                    try {
                      showMessage("≡ƒùæ∩╕Å Deleting all questions...", 10000);
                      const count = await clearAllQuestionsFromFirestore();
                      showMessage(
                        `Γ£à Deleted ${count} questions from database`,
                        5000
                      );
                    } catch (error) {
                      showMessage(`Γ¥î Delete failed: ${error.message}`, 5000);
                      console.error(error);
                    }
                  }}
                  className="w-full px-4 py-3 bg-red-900/30 hover:bg-red-900/50 text-red-300 rounded font-bold transition-all flex items-center justify-center gap-2 border border-red-700/50"
                >
                  <Icon name="trash-2" size={16} />
                  Delete All Questions (ALL USERS)
                </button>

                <button
                  onClick={async () => {
                    if (
                      !confirm(
                        "Clear all rejected questions from the database?\n\nThis will only delete questions with status='rejected'."
                      )
                    )
                      return;

                    try {
                      showMessage("≡ƒùæ∩╕Å Clearing rejected questions...", 10000);
                      // This would need a Cloud Function - for now just show message
                      showMessage(
                        "ΓÜá∩╕Å Feature not yet implemented - needs Cloud Function",
                        5000
                      );
                    } catch (error) {
                      showMessage(`Γ¥î Clear failed: ${error.message}`, 5000);
                    }
                  }}
                  className="w-full px-4 py-3 bg-orange-900/30 hover:bg-orange-900/50 text-orange-300 rounded font-bold transition-all flex items-center justify-center gap-2 border border-orange-700/50"
                >
                  <Icon name="filter" size={16} />
                  Clear Rejected Questions
                </button>

                <button
                  onClick={async () => {
                    if (
                      !confirm(
                        "≡ƒº╣ Cleanup Deleted Questions?\n\nThis will permanently remove all questions with status 'deleted' across ALL disciplines.\n\nThis is a maintenance operation to resolve count discrepancies.\n\nProceed?"
                      )
                    )
                      return;

                    try {
                      showMessage("≡ƒº╣ Cleaning up deleted questions...", 10000);
                      const count =
                        await deleteSoftDeletedQuestionsFromFirestore();
                      showMessage(
                        `Γ£à Successfully removed ${count} ghost questions.`,
                        5000
                      );
                      // Clear local cache if needed (page refresh is safest)
                      setTimeout(() => window.location.reload(), 2000);
                    } catch (error) {
                      showMessage(`Γ¥î Cleanup failed: ${error.message}`, 5000);
                      console.error(error);
                    }
                  }}
                  className="w-full px-4 py-3 bg-emerald-900/30 hover:bg-emerald-900/50 text-emerald-300 rounded font-bold transition-all flex items-center justify-center gap-2 border border-emerald-700/50"
                >
                  <Icon name="trash" size={16} />
                  Cleanup Deleted Questions (Release Quota)
                </button>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React from "react";
import Icon from "../Icon";

const ReviewerAnalytics = ({
  reviewerAnalytics,
  analyticsLoading,
  loadReviewerAnalytics,
  formatDuration,
  formatAnalyticsDate,
}) => {
  if (!reviewerAnalytics && !analyticsLoading) {
    return (
      <button
        onClick={loadReviewerAnalytics}
        disabled={analyticsLoading}
        className="w-full bg-cyan-600 hover:bg-cyan-500 disabled:bg-slate-600 disabled:cursor-not-allowed text-white px-4 py-2 rounded font-bold transition-all flex items-center justify-center gap-2"
      >
        <Icon name="bar-chart-2" size={16} />
        Load Reviewer Analytics
      </button>
    );
  }

  if (analyticsLoading) {
    return (
      <div className="flex flex-col items-center justify-center p-8 bg-slate-700/30 rounded border border-cyan-500/20">
        <Icon
          name="loader"
          className="animate-spin text-cyan-400 mb-2"
          size={24}
        />
        <p className="text-cyan-300 text-sm font-medium">
          Loading Analytics...
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Summary Stats */}
      <div className="grid grid-cols-3 gap-3 mb-4">
        <div className="bg-slate-700/50 p-3 rounded border border-cyan-500/20">
          <div className="text-xs text-slate-400 mb-1">Total Reviewers</div>
          <div className="text-2xl font-bold text-cyan-400">
            {reviewerAnalytics.metadata.totalReviewers}
          </div>
        </div>
        <div className="bg-slate-700/50 p-3 rounded border border-cyan-500/20">
          <div className="text-xs text-slate-400 mb-1">Questions Reviewed</div>
          <div className="text-2xl font-bold text-cyan-400">
            {reviewerAnalytics.metadata.totalQuestionsReviewed}
          </div>
        </div>
        <div className="bg-slate-700/50 p-3 rounded border border-cyan-500/20">
          <div className="text-xs text-slate-400 mb-1">Last Updated</div>
          <div className="text-sm font-medium text-cyan-400">
            {new Date(
              reviewerAnalytics.metadata.lastUpdated
            ).toLocaleTimeString()}
          </div>
        </div>
      </div>

      {/* Reviewer Stats Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-cyan-500/20">
              <th className="text-left p-2 text-xs text-cyan-400 font-bold">
                Reviewer
              </th>
              <th className="text-center p-2 text-xs text-cyan-400 font-bold">
                Questions
              </th>
              <th className="text-center p-2 text-xs text-cyan-400 font-bold">
                Accepted
              </th>
              <th className="text-center p-2 text-xs text-cyan-400 font-bold">
                Rejected
              </th>
              <th className="text-center p-2 text-xs text-cyan-400 font-bold">
                Avg Time
              </th>
              <th className="text-center p-2 text-xs text-cyan-400 font-bold">
                Total Time
              </th>
              <th className="text-center p-2 text-xs text-cyan-400 font-bold">
                Last Active
              </th>
            </tr>
          </thead>
          <tbody>
            {reviewerAnalytics.reviewerStats.length === 0 ? (
              <tr>
                <td colSpan="7" className="text-center p-4 text-slate-500">
                  No reviewer activity data found
                </td>
              </tr>
            ) : (
              reviewerAnalytics.reviewerStats.map((reviewer, idx) => (
                <tr
                  key={idx}
                  className="border-b border-slate-700/50 hover:bg-slate-700/30 transition-colors"
                >
                  <td className="p-2 text-white font-medium">
                    {reviewer.name}
                  </td>
                  <td className="p-2 text-center text-slate-300">
                    {reviewer.totalQuestionsReviewed}
                  </td>
                  <td className="p-2 text-center text-green-400">
                    {reviewer.acceptedCount}
                  </td>
                  <td className="p-2 text-center text-red-400">
                    {reviewer.rejectedCount}
                  </td>
                  <td className="p-2 text-center text-slate-300">
                    {formatDuration(reviewer.averageReviewTimeSeconds)}
                  </td>
                  <td className="p-2 text-center text-slate-300">
                    {formatDuration(reviewer.totalReviewTimeSeconds)}
                  </td>
                  <td className="p-2 text-center text-slate-400 text-xs">
                    {formatAnalyticsDate(reviewer.lastReviewDate)}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Refresh Button */}
      <button
        onClick={loadReviewerAnalytics}
        disabled={analyticsLoading}
        className="w-full bg-slate-700 hover:bg-slate-600 disabled:bg-slate-800 disabled:cursor-not-allowed text-white px-3 py-2 rounded text-sm transition-all flex items-center justify-center gap-2 mt-3 shadow-inner"
      >
        {analyticsLoading ? (
          <>
            <Icon name="loader" className="animate-spin" size={14} />
            Refreshing...
          </>
        ) : (
          <>
            <Icon name="refresh-cw" size={14} />
            Refresh Analytics
          </>
        )}
      </button>
    </div>
  );
};

export default ReviewerAnalytics;

import { useState } from 'react';
import { Shield, AlertCircle } from 'lucide-react';
/**
 * Age Gate - 18+ Verification
 * Required for COPPA/GDPR compliance
 */
const AgeGateModal = ({ isOpen, onConfirm, onExit }) => {
    const [birthYear, setBirthYear] = useState('');

    if (!isOpen) return null;

    const handleSubmit = (e) => {
        e.preventDefault();
        const year = parseInt(birthYear);
        const currentYear = new Date().getFullYear();
        const age = currentYear - year;

        if (age >= 18) {
            localStorage.setItem('ue5_age_verified', 'true');
            onConfirm();
        } else {
            alert('This tool is restricted to users 18 years and older. You will be redirected.');
            onExit();
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-sm p-4">
            <div className="bg-slate-900 border-2 border-orange-500 w-full max-w-md rounded-xl shadow-2xl overflow-hidden">

                {/* Header */}
                <div className="bg-gradient-to-r from-orange-600 to-red-600 p-6 text-center">
                    <Shield className="w-16 h-16 text-white mx-auto mb-3" />
                    <h2 className="text-2xl font-bold text-white">Age Verification Required</h2>
                </div>

                {/* Content */}
                <div className="p-6 space-y-4">
                    <div className="bg-yellow-900/30 border border-yellow-700 rounded-lg p-4 flex gap-3">
                        <AlertCircle className="w-6 h-6 text-yellow-400 flex-shrink-0 mt-0.5" />
                        <div className="text-sm text-yellow-200">
                            <p className="font-semibold mb-1">18+ Only</p>
                            <p>This tool is intended for professional educators and Unreal Engine Authorized Instructors only.</p>
                        </div>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div>
                            <label htmlFor="birthYear" className="block text-sm font-medium text-slate-300 mb-2">
                                What year were you born?
                            </label>
                            <input
                                type="number"
                                id="birthYear"
                                value={birthYear}
                                onChange={(e) => setBirthYear(e.target.value)}
                                min="1900"
                                max={new Date().getFullYear()}
                                required
                                className="w-full px-4 py-3 bg-slate-800 border border-slate-600 rounded-lg text-white text-lg text-center focus:border-orange-500 focus:outline-none"
                                placeholder="YYYY"
                            />
                        </div>

                        <p className="text-xs text-slate-500 text-center">
                            By continuing, you confirm you are 18+ years of age and accept the Terms of Use.
                        </p>

                        <div className="flex gap-3">
                            <button
                                type="button"
                                onClick={onExit}
                                className="flex-1 px-4 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg transition-colors"
                            >
                                Exit
                            </button>
                            <button
                                type="submit"
                                className="flex-1 px-4 py-3 bg-orange-600 hover:bg-orange-700 text-white font-semibold rounded-lg transition-colors"
                            >
                                Continue
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
};

