// Simple markdown to HTML converter
const parseMarkdown = (text) => {
  if (!text) return "";

  // Convert **bold** to <strong>
  let html = text.replace(
    /\*\*(.+?)\*\*/g,
    '<strong class="font-semibold text-white">$1</strong>'
  );

  // Convert *italic* to <em> (must be done after bold to avoid conflicts)
  html = html.replace(
    /\*([^*]+)\*/g,
    '<em class="italic text-slate-200">$1</em>'
  );

  // Convert `code` to <code>
  html = html.replace(
    /`([^`]+)`/g,
    '<code class="bg-slate-800 px-1 rounded text-orange-300">$1</code>'
  );

  return html;
};

/**
 * Renders inline word-level diff with highlighting
 */
const DiffText = ({ oldText, newText }) => {
  const diff = computeWordDiff(oldText || "", newText || "");

  if (diff.length === 0) return <span className="text-white">{newText}</span>;

  // Check if there are any actual changes
  const hasChanges = diff.some((seg) => seg.type !== "unchanged");

  if (!hasChanges) {
    return <span className="text-white">{oldText}</span>;
  }

  return (
    <span className="leading-relaxed">
      {diff.map((segment, idx) => {
        if (segment.type === "removed") {
          return (
            <span key={idx} className="text-slate-500 line-through">
              {segment.text}
            </span>
          );
        }
        if (segment.type === "added") {
          return (
            <span
              key={idx}
              className="bg-green-900/60 text-green-300 font-semibold px-0.5 rounded mx-0.5"
            >
              {segment.text}
            </span>
          );
        }
        return (
          <span key={idx} className="text-white">
            {segment.text}
          </span>
        );
      })}
    </span>
  );
};

const CritiqueDisplay = ({
  critique,
  onRewrite,
  isProcessing,
  suggestedRewrite,
  rewriteChanges,
  onApplyRewrite,
  onApplyAndAccept: _onApplyAndAccept,
  originalQuestion,
  onExplain,
  onVariate,
}) => {
  if (!critique) return null;

  // Handle both old (string) and new (object with score) formats
  const isNewFormat =
    typeof critique === "object" && critique.score !== undefined;
  const score = isNewFormat ? critique.score : null;
  const text = (isNewFormat ? critique.text : critique) || "";

  // Color coding based on score
  const getScoreColor = (score) => {
    if (score >= QUALITY_THRESHOLDS.EXCELLENT)
      return "bg-green-900/30 border-green-700/50 text-green-300";
    if (score >= QUALITY_THRESHOLDS.PASS)
      return "bg-yellow-900/30 border-yellow-700/50 text-yellow-300";
    if (score >= QUALITY_THRESHOLDS.MEDIOCRE)
      return "bg-orange-900/30 border-orange-700/50 text-orange-300";
    return "bg-red-900/30 border-red-700/50 text-red-300";
  };

  // Process text into structured sections
  const renderContent = () => {
    const lines = text.split("\n").filter((line) => line.trim());
    const elements = [];
    let currentList = [];
    let listType = null; // 'bullet' or 'number'

    const flushList = () => {
      if (currentList.length > 0) {
        const _ListTag = listType === "number" ? "ol" : "ul";
        elements.push(
          <ListTag
            key={`list-${elements.length}`}
            className={`${
              listType === "number" ? "list-decimal" : "list-disc"
            } ml-4 space-y-1`}
          >
            {currentList.map((item, i) => (
              <li
                key={i}
                className="text-current"
                dangerouslySetInnerHTML={{ __html: parseMarkdown(item) }}
              />
            ))}
          </ListTag>
        );
        currentList = [];
        listType = null;
      }
    };

    lines.forEach((line, index) => {
      const trimmed = line.trim();

      // Check for bullet points (* item or - item)
      const bulletMatch = trimmed.match(/^[*-]\s+(.+)$/);
      if (bulletMatch) {
        if (listType !== "bullet") flushList();
        listType = "bullet";
        currentList.push(bulletMatch[1]);
        return;
      }

      // Check for numbered lists (1. item)
      const numberMatch = trimmed.match(/^\d+\.\s+(.+)$/);
      if (numberMatch) {
        if (listType !== "number") flushList();
        listType = "number";
        currentList.push(numberMatch[1]);
        return;
      }

      // Regular paragraph - flush any pending list first
      flushList();

      // Check if it's a heading (ends with :)
      if (trimmed.endsWith(":") && trimmed.length < 50) {
        elements.push(
          <p
            key={index}
            className="font-semibold text-white mt-2 first:mt-0"
            dangerouslySetInnerHTML={{ __html: parseMarkdown(trimmed) }}
          />
        );
      } else {
        elements.push(
          <p
            key={index}
            className="text-current"
            dangerouslySetInnerHTML={{ __html: parseMarkdown(trimmed) }}
          />
        );
      }
    });

    // Flush any remaining list
    flushList();

    return elements;
  };

  const questionChanged =
    suggestedRewrite &&
    originalQuestion &&
    suggestedRewrite.question !== originalQuestion.question;

  return (
    <div
      className={`mb-3 p-3 border rounded-lg animate-in fade-in slide-in-from-top-2 ${
        isNewFormat ? getScoreColor(score) : "bg-red-950/30 border-red-500/30"
      }`}
    >
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2 text-xs font-bold uppercase">
          <Icon name="zap" size={12} />
          AI Critique
        </div>
        <div className="flex items-center gap-3">
          {onRewrite && !suggestedRewrite && (
            <button
              onClick={onRewrite}
              disabled={isProcessing}
              className="px-3 py-1 rounded bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold transition-all flex items-center gap-1 disabled:opacity-50 disabled:cursor-not-allowed"
              title="Auto-rewrite this question based on critique"
            >
              <Icon name="edit" size={12} />
              {isProcessing ? "Rewriting..." : "Rewrite"}
            </button>
          )}
        </div>
      </div>
      <div className="text-xs text-slate-300 leading-relaxed space-y-1.5">
        {renderContent()}
      </div>

      {/* Suggested Rewrite Section with Word-Level Diff */}
      {suggestedRewrite && (
        <div className="mt-3 pt-3 border-t border-white/10">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <span className="text-xs font-bold uppercase text-indigo-300 flex items-center gap-1">
                <Icon name="sparkles" size={12} /> Suggested Improvement
              </span>
              <span className="text-[10px] px-2 py-0.5 rounded-full bg-blue-900/30 text-blue-300 border border-blue-700/50 flex items-center gap-1">
                <Icon name="git-compare" size={10} />
                Word Diff
              </span>
            </div>
            <div className="flex items-center gap-3">
              {/* FIX IT button - applies rewrite but keeps question PENDING for human review */}
              {/* Only enabled when score < 60 (needs improvement) */}
              {onApplyRewrite && (
                <button
                  onClick={onApplyRewrite}
                  disabled={isProcessing || score >= QUALITY_PASS_THRESHOLD}
                  className={`px-5 py-2.5 rounded-lg text-white text-sm font-bold transition-all flex items-center gap-2 shadow-lg ${
                    isProcessing || score >= QUALITY_PASS_THRESHOLD
                      ? "bg-slate-700 cursor-not-allowed opacity-50"
                      : "bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-500 hover:to-emerald-500 shadow-green-900/50"
                  }`}
                  title={
                    score >= QUALITY_PASS_THRESHOLD
                      ? "Score is acceptable - no fix needed"
                      : "Apply AI improvements (question stays pending for your review)"
                  }
                >
                  <Icon name="zap" size={16} />
                  {isProcessing
                    ? "Applying..."
                    : score >= QUALITY_PASS_THRESHOLD
                    ? "NO FIX NEEDED"
                    : "APPLY FIX"}
                </button>
              )}

              {/* Secondary options */}
              <div className="flex items-center gap-2 opacity-70 hover:opacity-100 transition-opacity">
                {onExplain && (
                  <button
                    onClick={onExplain}
                    disabled={isProcessing}
                    className="px-2 py-1 rounded border border-slate-600 text-slate-400 text-xs hover:text-white hover:border-slate-400 transition-colors disabled:opacity-50"
                    title="Why is this the answer?"
                  >
                    WHY?
                  </button>
                )}
                {onVariate && (
                  <button
                    onClick={onVariate}
                    disabled={isProcessing}
                    className="px-2 py-1 rounded border border-slate-600 text-slate-400 text-xs hover:text-white hover:border-slate-400 transition-colors disabled:opacity-50"
                    title="Generate alternative question variations"
                  >
                    ALTERNATIVES
                  </button>
                )}
              </div>
            </div>
          </div>

          {rewriteChanges && (
            <div className="mb-2 text-xs text-indigo-200 bg-indigo-900/20 p-2 rounded border border-indigo-500/30 flex items-start gap-2">
              <Icon name="info" size={14} className="flex-shrink-0 mt-0.5" />
              <span>
                <span className="font-bold text-indigo-100">Why:</span>{" "}
                {rewriteChanges}
              </span>
            </div>
          )}

          <div className="text-xs space-y-3 bg-black/20 p-3 rounded border border-white/5">
            {/* Question with word-level diff */}
            <div>
              <div className="text-[10px] font-bold uppercase text-slate-500 mb-1 flex items-center gap-1">
                <Icon name="message-square" size={10} />
                Question
              </div>
              <div className="text-sm">
                {questionChanged && originalQuestion ? (
                  <DiffText
                    oldText={originalQuestion.question}
                    newText={suggestedRewrite.question}
                  />
                ) : (
                  <span className="text-white">
                    {suggestedRewrite.question}
                  </span>
                )}
              </div>
            </div>

            {/* Options with word-level diff */}
            <div>
              <div className="text-[10px] font-bold uppercase text-slate-500 mb-1 flex items-center gap-1">
                <Icon name="list" size={10} />
                Options
              </div>
              <div className="grid grid-cols-1 gap-1.5 pl-2 border-l-2 border-indigo-500/30">
                {["A", "B", "C", "D"].map((letter) => {
                  const newVal = suggestedRewrite.options?.[letter];
                  if (!newVal) return null;

                  const oldVal = originalQuestion?.options?.[letter];
                  const isChanged = oldVal && oldVal !== newVal;
                  const isCorrect = suggestedRewrite.correct === letter;

                  return (
                    <div
                      key={letter}
                      className={`flex items-start gap-2 ${
                        isCorrect ? "text-green-400 font-bold" : ""
                      }`}
                    >
                      <span
                        className={`flex-shrink-0 w-5 h-5 rounded text-center text-[10px] leading-5 font-bold ${
                          isChanged
                            ? "bg-blue-900/50 text-blue-300 border border-blue-700/50"
                            : "bg-slate-800 text-slate-400"
                        }`}
                      >
                        {letter}
                      </span>
                      <span className="flex-1">
                        {isChanged ? (
                          <DiffText oldText={oldVal} newText={newVal} />
                        ) : (
                          <span
                            className={
                              isCorrect ? "text-green-400" : "text-slate-300"
                            }
                          >
                            {newVal}
                          </span>
                        )}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Correct answer change indicator */}
            {originalQuestion &&
              suggestedRewrite.correct !== originalQuestion.correct && (
                <div className="flex items-center gap-2 text-xs text-yellow-200 bg-yellow-950/30 border border-yellow-700/50 rounded p-2">
                  <Icon name="alert-triangle" size={14} />
                  <span>
                    Correct answer changed:
                    <span className="ml-1 bg-red-900/50 text-red-300 line-through px-1.5 py-0.5 rounded">
                      {originalQuestion.correct}
                    </span>
                    <span className="mx-1">ΓåÆ</span>
                    <span className="bg-green-900/50 text-green-300 font-bold px-1.5 py-0.5 rounded">
                      {suggestedRewrite.correct}
                    </span>
                  </span>
                </div>
              )}
          </div>
        </div>
      )}
    </div>
  );
};

export default CritiqueDisplay;

import { sanitizeText } from "../utils/sanitize";
import Icon from "./Icon";
import { renderMarkdown, computeWordDiff } from "../utils/stringHelpers";
import { QUALITY_THRESHOLDS } from "../utils/constants";

/**
 * Renders inline word-level diff with highlighting
 * @param {string} oldText - Original text
 * @param {string} newText - New text
 */
const _DiffText = ({ oldText, newText }) => {
  const diff = computeWordDiff(oldText || "", newText || "");

  if (diff.length === 0) return null;

  // Check if there are any actual changes
  const hasChanges = diff.some((seg) => seg.type !== "unchanged");

  if (!hasChanges) {
    return <span className="text-slate-300">{oldText}</span>;
  }

  return (
    <span className="leading-relaxed">
      {diff.map((segment, idx) => {
        if (segment.type === "removed") {
          return (
            <span key={idx} className="text-slate-500 line-through">
              {segment.text}
            </span>
          );
        }
        if (segment.type === "added") {
          return (
            <span
              key={idx}
              className="bg-green-900/50 text-green-300 font-semibold px-0.5 rounded"
            >
              {segment.text}
            </span>
          );
        }
        return (
          <span key={idx} className="text-slate-300">
            {segment.text}
          </span>
        );
      })}
    </span>
  );
};

const CritiqueModal = ({
  isOpen,
  onClose,
  q,
  text,
  score,
  loading,
  onFix,
  isFixing,
  onAccept,
  rewrite,
  changes,
  onApplySuggestions,
}) => {
  if (!isOpen || !q) return null;

  const getSeverityStyles = (score) => {
    if (score === null || score === undefined)
      return {
        bg: "bg-slate-800",
        border: "border-slate-700",
        text: "text-slate-400",
        icon: "text-slate-500",
      };

    // STRICTER COLOR THRESHOLDS
    // 90-100: Green (Excellent/Perfect)
    if (score >= QUALITY_THRESHOLDS.EXCELLENT)
      return {
        bg: "bg-emerald-950/40",
        border: "border-emerald-500/50",
        text: "text-emerald-200",
        icon: "text-emerald-400",
        label: "Excellent",
      };

    // 70-89: Yellow (Good but flawed)
    if (score >= QUALITY_THRESHOLDS.PASS)
      return {
        bg: "bg-yellow-950/40",
        border: "border-yellow-500/50",
        text: "text-yellow-200",
        icon: "text-yellow-400",
        label: "Good",
      };

    // 50-69: Orange (Mediocre)
    if (score >= QUALITY_THRESHOLDS.MEDIOCRE)
      return {
        bg: "bg-orange-950/40",
        border: "border-orange-500/50",
        text: "text-orange-200",
        icon: "text-orange-400",
        label: "Mediocre",
      };

    // 0-49: Red (Critical)
    return {
      bg: "bg-red-950/40",
      border: "border-red-500/50",
      text: "text-red-200",
      icon: "text-red-400",
      label: "Critical",
    };
  };

  const styles = getSeverityStyles(score);
  const isFailing = score !== null && score < QUALITY_THRESHOLDS.MEDIOCRE;

  // Check if question was changed
  const questionChanged = rewrite?.question && rewrite.question !== q.question;

  // Check which options changed
  const optionChanges = ["A", "B", "C", "D"].filter((letter) => {
    const oldVal = q.options?.[letter];
    const newVal = rewrite?.options?.[letter];
    return newVal && oldVal !== newVal;
  });

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
      <div className="bg-slate-900 border border-slate-700 rounded-xl shadow-2xl max-w-3xl w-full flex flex-col max-h-[90vh]">
        <div
          className={`p-4 border-b ${styles.border} flex justify-between items-center bg-slate-950/50 rounded-t-xl`}
        >
          <div
            className={`flex items-center gap-2 ${styles.icon} font-bold uppercase tracking-wider text-sm`}
          >
            <Icon name="zap" size={18} />
            <span>AI Critique {score !== null && `ΓÇó Score: ${score}/100`}</span>
          </div>
          <button
            onClick={onClose}
            className="text-slate-500 hover:text-white transition-colors"
          >
            <Icon name="x" size={20} />
          </button>
        </div>

        <div className="p-6 overflow-y-auto space-y-6 flex-1">
          {/* Original Question */}
          <div className="space-y-2">
            <div className="text-[10px] font-bold uppercase text-slate-500">
              Original Question
            </div>
            <div
              className="p-4 bg-slate-950 border border-slate-800 rounded text-sm text-slate-300"
              dangerouslySetInnerHTML={{ __html: sanitizeText(q.question) }}
            />
          </div>

          {/* Feedback */}
          <div className="space-y-2">
            <div className="text-[10px] font-bold uppercase text-slate-500">
              Feedback
            </div>
            {loading ? (
              <div className="flex items-center gap-2 text-sm text-slate-400 animate-pulse p-4">
                <Icon name="loader" className="animate-spin" /> Analyzing Logic
                & Syntax...
              </div>
            ) : (
              <div
                className={`p-4 ${styles.bg} border ${styles.border} rounded text-sm ${styles.text} leading-relaxed`}
                dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }}
              />
            )}
          </div>

          {/* Suggested Changes with Word-Level Diff */}
          {rewrite && (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <div className="text-[10px] font-bold uppercase text-slate-500">
                  AI Improvements
                </div>
                <div className="flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-blue-900/30 text-blue-300 border border-blue-700/50">
                  <Icon name="git-compare" size={10} />
                  <span>Word-Level Diff</span>
                </div>
              </div>

              {/* Change Summary */}
              {changes && (
                <div className="p-3 bg-indigo-950/30 border border-indigo-700/50 rounded text-xs text-indigo-200 italic flex items-start gap-2">
                  <Icon
                    name="info"
                    size={14}
                    className="flex-shrink-0 mt-0.5"
                  />
                  <span>{changes}</span>
                </div>
              )}

              <div className="p-4 bg-slate-950/50 border border-slate-700 rounded space-y-4">
                {/* Question Diff */}
                {questionChanged && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase">
                      <Icon name="message-square" size={12} />
                      Question Text
                    </div>
                    <div className="p-3 bg-slate-900 border border-slate-800 rounded text-sm">
                      <DiffText
                        oldText={q.question}
                        newText={rewrite.question}
                      />
                    </div>
                  </div>
                )}

                {/* Options Diff */}
                {optionChanges.length > 0 && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase">
                      <Icon name="list" size={12} />
                      Answer Options
                    </div>
                    <div className="space-y-2">
                      {optionChanges.map((letter) => (
                        <div
                          key={letter}
                          className="flex items-start gap-3 p-3 bg-slate-900 border border-slate-800 rounded"
                        >
                          <div className="text-[10px] font-bold text-slate-500 bg-slate-800 px-2 py-1 rounded">
                            {letter}
                          </div>
                          <div className="flex-1 text-sm">
                            <DiffText
                              oldText={q.options?.[letter]}
                              newText={rewrite.options?.[letter]}
                            />
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Correct Answer Change */}
                {rewrite.correct && rewrite.correct !== q.correct && (
                  <div className="flex items-center gap-2 text-xs text-yellow-200 bg-yellow-950/30 border border-yellow-700/50 rounded p-3">
                    <Icon name="alert-triangle" size={14} />
                    <span>
                      Correct answer changed:
                      <span className="ml-1 bg-red-900/50 text-red-300 line-through px-1.5 py-0.5 rounded">
                        {q.correct}
                      </span>
                      <span className="mx-1">ΓåÆ</span>
                      <span className="bg-green-900/50 text-green-300 font-bold px-1.5 py-0.5 rounded">
                        {rewrite.correct}
                      </span>
                    </span>
                  </div>
                )}

                {/* No Changes Detected */}
                {!questionChanged &&
                  optionChanges.length === 0 &&
                  rewrite.correct === q.correct && (
                    <div className="text-xs text-slate-400 text-center py-2">
                      <Icon
                        name="check-circle"
                        size={14}
                        className="inline mr-1"
                      />
                      No structural changes suggested - question is already
                      well-formed
                    </div>
                  )}
              </div>
            </div>
          )}
        </div>

        <div className="p-4 border-t border-slate-800 bg-slate-950/50 rounded-b-xl flex justify-center gap-3 flex-wrap">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg hover:shadow-slate-900/20"
          >
            Dismiss
          </button>

          {rewrite && onApplySuggestions && (
            <button
              onClick={() => onApplySuggestions(rewrite)}
              disabled={loading}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg hover:shadow-blue-900/20"
            >
              <Icon name="check-circle" size={14} />
              Apply All Suggestions
            </button>
          )}

          <button
            onClick={onFix}
            disabled={loading || isFixing}
            className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg hover:shadow-indigo-900/20"
          >
            {isFixing ? (
              <Icon name="loader" className="animate-spin" size={14} />
            ) : (
              <Icon name="sparkles" size={14} />
            )}
            Regenerate
          </button>

          <button
            onClick={onAccept}
            disabled={isFailing || loading}
            title={isFailing ? "Score too low to accept" : "Accept Question"}
            className={`px-4 py-2 font-bold rounded flex items-center gap-2 text-xs uppercase transition-all shadow-lg ${
              isFailing || loading
                ? "bg-slate-800 text-slate-500 cursor-not-allowed opacity-50"
                : "bg-green-600 hover:bg-green-500 text-white hover:shadow-green-900/20"
            }`}
          >
            <Icon name="check" size={14} /> Accept
          </button>
        </div>
      </div>
    </div>
  );
};

