      alert(
        "Factory reset cancelled. You must type 'DELETE EVERYTHING' exactly."
      );
      setShowFactoryResetPrompt(false);
      return;
    }

    console.log("ΓÜá∩╕Å FACTORY RESET INITIATED");
    setShowFactoryResetPrompt(false);
    setIsResetting(true);

    try {
      let deletedCount = 0;

      // 1. Clear Firestore FIRST (critical)
      console.log("Clearing Firestore...");
      try {
        deletedCount = await clearAllQuestionsFromFirestore();
        console.log(`Γ£à Deleted ${deletedCount} questions from Firestore`);
      } catch (firestoreError) {
        console.error("Γ¥î Firestore deletion failed:", firestoreError);
        throw new Error(`Firestore deletion failed: ${firestoreError.message}`);
      }

      // 2. Clear Google Spreadsheet
      if (config.sheetUrl) {
        console.log("Clearing Google Spreadsheet...");
        try {
          clearQuestionsFromSheets(config.sheetUrl);
          console.log("Γ£à Spreadsheet clear request sent (check new tab)");
        } catch (sheetsError) {
          console.error("Γ¥î Sheets clearing failed:", sheetsError);
        }
      }

      // 3. Clear localStorage
      console.log("Clearing localStorage...");
      localStorage.clear();
      console.log("Γ£à Local storage cleared");

      // 4. Reload
      alert(
        `Factory Reset Complete!\n\nΓÇó Firestore: ${deletedCount} questions deleted\nΓÇó Spreadsheet: ${
          config.sheetUrl ? "Clearing in new tab" : "Skipped"
        }\nΓÇó Local Storage: Cleared\n\nPage will reload.`
      );
      window.location.reload();
    } catch (error) {
      console.error("Γ¥î Factory reset error:", error);
      alert(
        "Error during factory reset:\n\n" +
          error.message +
          "\n\nCheck console for details."
      );
      setIsResetting(false);
    }
  };

  const handleBackfillCreatorNames = async () => {
    if (
      !confirm(
        'This will add your creator name to all questions that currently show "N/A". Continue?'
      )
    ) {
      return;
    }

    setIsMigrating(true);
    setMigrationResult(null);

    try {
      const creatorName = config.creatorName || "Unknown";
      const querySnapshot = await getDocs(collection(db, "questions"));

      const questionsToUpdate = [];
      querySnapshot.forEach((docSnap) => {
        const data = docSnap.data();
        const creator = data.creatorName;
        // Catch: null, undefined, empty string, 'N/A', or whitespace-only
        if (
          !creator ||
          creator.trim() === "" ||
          creator === "N/A" ||
          creator === "Unknown"
        ) {
          questionsToUpdate.push({
            firestoreId: docSnap.id, // Use Firestore document ID
            ...data,
          });
        }
      });

      if (questionsToUpdate.length === 0) {
        setMigrationResult({
          success: 0,
          total: 0,
          message: "All questions already have creator names!",
        });
        setIsMigrating(false);
        return;
      }

      let successCount = 0;
      for (const question of questionsToUpdate) {
        try {
          console.log(
            "Updating question:",
            question.firestoreId,
            "Creator:",
            question.creatorName
          );
          const questionRef = doc(db, "questions", question.firestoreId);
          await updateDoc(questionRef, {
            creatorName: creatorName,
            backfilledAt: new Date().toISOString(),
          });
          successCount++;
          console.log("Γ£ô Successfully updated:", question.firestoreId);
        } catch (err) {
          console.error(
            `Failed to update question ${question.firestoreId}:`,
            err.message,
            err
          );
        }
      }

      setMigrationResult({
        success: successCount,
        total: questionsToUpdate.length,
        message: `Successfully updated ${successCount} of ${questionsToUpdate.length} questions!`,
      });
    } catch (error) {
      console.error("Migration failed:", error);
      alert("Migration failed: " + error.message);
    } finally {
      setIsMigrating(false);
    }
  };

  // Admin-only: Nuke ALL questions from Firestore (any user's questions)
  const handleNukeAllQuestions = async () => {
    if (!auth.currentUser) {
      alert("You must be signed in to use this feature.");
      return;
    }

    if (
      !confirm(
        "ΓÜá∩╕Å ADMIN NUKE: This will delete ALL questions from ALL users. Are you sure?"
      )
    ) {
      return;
    }
    if (!confirm("ΓÜá∩╕Å FINAL WARNING: This is IRREVERSIBLE. Continue?")) {
      return;
    }

    setIsNuking(true);
    setNukeProgress({ current: 0, total: 0 });

    try {
      console.log("≡ƒöÑ Admin nuke initiated by:", auth.currentUser.email);

      // Fetch ALL questions without filter
      const snapshot = await getDocs(collection(db, "questions"));
      const allQuestions = snapshot.docs.map((doc) => ({
        uniqueId: doc.id,
        ...doc.data(),
      }));

      if (allQuestions.length === 0) {
        alert("No questions found in the database.");
        setIsNuking(false);
        return;
      }

      setNukeProgress({ current: 0, total: allQuestions.length });

      let deletedCount = 0;
      let errorCount = 0;
      const BATCH_SIZE = 10;

      for (let i = 0; i < allQuestions.length; i += BATCH_SIZE) {
        const batch = allQuestions.slice(i, i + BATCH_SIZE);

        await Promise.all(
          batch.map(async (q) => {
            try {
              await deleteQuestionFromFirestore(q.uniqueId);
              deletedCount++;
            } catch (e) {
              console.error("Delete failed for", q.uniqueId, e);
              errorCount++;
            }
          })
        );

        setNukeProgress({
          current: Math.min(i + BATCH_SIZE, allQuestions.length),
          total: allQuestions.length,
        });
      }

      alert(
        `Nuke complete!\n\nDeleted: ${deletedCount}\nFailed: ${errorCount}`
      );

      // Clear local storage and reload
      localStorage.clear();
      window.location.reload();
    } catch (error) {
      console.error("Nuke failed:", error);
      alert("Nuke failed: " + error.message);
    } finally {
      setIsNuking(false);
    }
  };

  if (!isOpen) return null;

  return (
    <>
      <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
        <div className="bg-red-950/50 border-2 border-red-500 rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-200">
          <div className="p-4 border-b border-red-900 flex justify-between items-center bg-red-900/50">
            <h2 className="text-lg font-bold text-red-300 flex items-center gap-2">
              <Icon name="alert-triangle" className="text-red-500" /> DANGER
              ZONE
            </h2>
            <button
              onClick={onClose}
              className="text-red-400 hover:text-white transition-colors"
              aria-label="Close Danger Zone"
            >
              <Icon name="x" />
            </button>
          </div>

          <div className="p-6 space-y-6">
            <div className="bg-red-900/20 p-4 rounded-lg border border-red-900/50">
              <p className="text-sm text-red-300 mb-4">
                ΓÜá∩╕Å <strong>WARNING:</strong> These operations are{" "}
                <strong>PERMANENT</strong> and cannot be undone. Your data will
                be lost forever.
              </p>

              <div className="space-y-3">
                {/* Migration Tools */}
                <div className="bg-blue-900/20 p-3 rounded border border-blue-900/50 mb-3">
                  <p className="text-xs text-blue-300 mb-2 font-semibold">
                    ≡ƒöº Data Migration
                  </p>
                  <button
                    onClick={handleBackfillCreatorNames}
                    disabled={isMigrating}
                    className="w-full px-4 py-2 bg-blue-900/20 hover:bg-blue-900/40 text-blue-400 text-xs font-bold rounded border border-blue-900/50 transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
                  >
                    {isMigrating ? (
                      <>
                        <Icon
                          name="loader"
                          size={14}
                          className="animate-spin"
                        />{" "}
                        Migrating...
                      </>
                    ) : (
                      <>
                        <Icon name="user-check" size={14} /> Backfill Creator
                        Names
                      </>
                    )}
                  </button>
                  {migrationResult && (
                    <p className="text-xs text-green-400 mt-2 text-center">
                      Γ£ô {migrationResult.message}
                    </p>
                  )}
                  <p className="text-[9px] text-blue-400/60 mt-1">
                    Adds your name to questions showing "N/A"
                  </p>
                </div>

                {/* Destructive Operations */}
                <button
                  onClick={onClearData}
                  className="w-full px-4 py-3 bg-red-900/20 hover:bg-red-900/40 text-red-400 text-sm font-bold rounded border border-red-900/50 transition-colors flex items-center justify-center gap-2"
                >
                  <Icon name="trash-2" size={16} />
                  Clear Local Data (Keep Cloud Backup)
                </button>

                <button
                  onClick={handleFactoryResetClick}
                  disabled={isResetting}
                  className="w-full px-4 py-3 bg-red-950 hover:bg-red-900 text-red-500 text-sm font-bold rounded border-2 border-red-900 transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isResetting ? (
                    <>
                      <Icon name="loader" size={16} className="animate-spin" />{" "}
                      Resetting...
                    </>
                  ) : (
                    <>
                      <Icon name="bomb" size={16} /> FACTORY RESET (Delete
                      Everything)
                    </>
                  )}
                </button>

                {/* Admin-only: Nuke All Questions */}
                {isAdmin && (
                  <div className="mt-4 pt-4 border-t border-red-900/50">
                    <p className="text-[10px] text-orange-400 mb-2 font-semibold">
                      ≡ƒöÉ ADMIN ONLY
                    </p>
                    <button
                      onClick={handleNukeAllQuestions}
                      disabled={isNuking}
                      className="w-full px-4 py-3 bg-orange-950 hover:bg-orange-900 text-orange-400 text-sm font-bold rounded border-2 border-orange-700 transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
                    >
                      {isNuking ? (
                        <>
                          <Icon
                            name="loader"
                            size={16}
                            className="animate-spin"
                          />
                          Nuking... ({nukeProgress.current}/{nukeProgress.total}
                          )
                        </>
                      ) : (
                        <>
                          <Icon name="zap" size={16} /> NUKE ALL QUESTIONS (All
                          Users)
                        </>
                      )}
                    </button>
                    <p className="text-[9px] text-orange-400/60 mt-1 text-center">
                      Deletes ALL questions from ALL users in the database
                    </p>
                  </div>
                )}
              </div>

              <p className="text-[10px] text-red-400/70 mt-3 text-center">
                Factory Reset deletes ALL data: Spreadsheet + Firestore + Local
                Storage
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Confirmation Dialogs */}
      <ConfirmDialog
        isOpen={showFactoryResetConfirm}
        title="ΓÜá∩╕Å FACTORY RESET WARNING ΓÜá∩╕Å"
        message={`This will PERMANENTLY DELETE ALL data from:

ΓÇó Google Spreadsheet (all Master_ sheets)
ΓÇó Firestore Database (cloud)  
ΓÇó Local storage (questions, settings, analytics)

This action CANNOT be undone. Are you ABSOLUTELY SURE?`}
        confirmText="Yes, I Understand"
        cancelText="Cancel"
        onConfirm={handleFirstConfirm}
        onCancel={() => setShowFactoryResetConfirm(false)}
        isDanger={true}
      />

      <PromptDialog
        isOpen={showFactoryResetPrompt}
        title="≡ƒö┤ FINAL CONFIRMATION ≡ƒö┤"
        message="Type 'DELETE EVERYTHING' (all caps, no quotes) to confirm permanent deletion of ALL data:"
        placeholder="Type DELETE EVERYTHING here"
        expectedValue="DELETE EVERYTHING"
        confirmText="Delete Everything Forever"
        cancelText="Cancel"
        onConfirm={handlePromptConfirm}
        onCancel={() => setShowFactoryResetPrompt(false)}
        isDanger={true}
      />
    </>
  );
};

export default DangerZoneModal;

import { useState, useMemo, useRef, useEffect, useCallback } from "react";
import Icon from "./Icon";
import MetricsDashboard from "./MetricsDashboard";
import QuestionItem from "./QuestionItem.jsx";
import { exportQuestionsForCritique } from "../utils/externalCritique";

// PERFORMANCE: Number of items to render initially and load per batch
const INITIAL_RENDER_COUNT = 50;
const LOAD_MORE_COUNT = 50;

const DatabaseView = ({
  questions,
  _sheetUrl,
  _onLoad,
  _onLoadFirestore,
  _onClearView,
  _onHardReset,
  onUpdateQuestion,
  onKickBack,
  _isProcessing,
  showMessage,
  filterMode = "all", // Default to 'all' if not provided
  sortBy = "default", // Default to 'default' if not provided
  searchTerm = "", // Search filter from toolbar
  onStartTutorial, // Callback to trigger database tutorial
  isAdmin = false, // Whether current user is admin
  userRole = "user", // NEW
}) => {
  const [_isSyncing, _setIsSyncing] = useState(false);
  const [_syncProgress, _setSyncProgress] = useState(0);
  const [_loadMenuOpen, setLoadMenuOpen] = useState(false);
  const loadMenuRef = useRef(null);

  // PERFORMANCE: Track how many items to render (windowed rendering)
  const [visibleCount, setVisibleCount] = useState(INITIAL_RENDER_COUNT);
  const loaderRef = useRef(null);

  // Export for external critique (Admin only)
  const handleExport = () => {
    console.log("≡ƒôñ Exporting questions for external critique...");
    const result = exportQuestionsForCritique(questions);
    showMessage(
      `Γ£à Exported ${result.count} questions! Prompt copied to clipboard.`,
      5000
    );
  };

  // OLD Batch Critique handler (disabled)
  /*
  const _handleBatchCritique = async () => {
    if (!window.confirm('ΓÜá∩╕Å WARNING: This will critique ALL uncritiqued questions (~1700 API calls).\n\nThis will:\n- Take 1-2 hours\n- Use significant API quota\n- Cost money on paid plans\n\nContinue?')) {
      return;
    }
    
    // Get API key
    const config = JSON.parse(localStorage.getItem('ue5_gen_config') || '{}');
    const apiKey = config.geminiApiKey;
    
    if (!apiKey) {
      showMessage('Γ¥î No API key configured. Please set your Gemini API key in settings.', 5000);
      return;
    }
    
    setIsBatchCritiquing(true);
    setBatchProgress({ processed: 0, total: 0, percent: 0 });
    
    try {
      await batchCritiqueAllQuestions(
        apiKey,
        // Progress callback
        (progress) => {
          setBatchProgress(progress);
          console.log(`≡ƒôè Progress: ${progress.processed}/${progress.total} (${progress.percent}%)`);
        },
        // Complete callback
        (result) => {
          if (result.success) {
            showMessage(`Γ£à Batch critique complete! Processed ${result.processed} questions`, 5000);
            setTimeout(() => window.location.reload(), 2000);
          } else {
            showMessage(`Γ¥î Batch critique failed: ${result.error}`, 5000);
          }
        }
      );
    } catch (error) {
      showMessage(`Γ¥î Batch critique error: ${error.message}`, 5000);
    } finally {
      setIsBatchCritiquing(false);
      setBatchProgress(null);
    }
  };
  */

  // Auto-start tutorial if not completed (and compliance modals are done)
  useEffect(() => {
    const isCompleted = localStorage.getItem("ue5_tutorial_database_completed");
    const ageVerified = localStorage.getItem("ue5_age_verified");
    const termsAccepted = localStorage.getItem("ue5_terms_accepted");

    // Only start tutorial if compliance modals are complete
    if (!isCompleted && onStartTutorial && ageVerified && termsAccepted) {
      // Small delay to ensure view is rendered
      setTimeout(() => onStartTutorial("database"), 500);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Reset visible count when questions change
  useEffect(() => {
    setVisibleCount(INITIAL_RENDER_COUNT);
  }, [questions]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (loadMenuRef.current && !loadMenuRef.current.contains(event.target)) {
        setLoadMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Calculate unique question count (by uniqueId)
  const uniqueQuestionCount = useMemo(() => {
    if (!questions) return 0;
    const uniqueIds = new Set(questions.map((q) => q.uniqueId).filter(Boolean));
    return uniqueIds.size;
  }, [questions]);

  const sortedQuestions = useMemo(() => {
    if (!questions) return [];

    // FIRST: Filter to only show ACCEPTED questions in Database view
    // Pending and rejected questions should only appear in Review mode
    let filtered = questions.filter((q) => q.status === "accepted");

    // Then filter by search term if provided
    if (searchTerm && searchTerm.trim()) {
      const term = searchTerm.toLowerCase().trim();
      filtered = filtered.filter((q) => {
        const searchableText = [
          q.question,
          q.discipline,
          q.difficulty,
          q.type,
          q.language,
          q.creatorName,
          q.sourceUrl,
          q.sourceExcerpt,
          ...(q.tags || []),
          q.options?.A,
          q.options?.B,
          q.options?.C,
          q.options?.D,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();
        return searchableText.includes(term);
      });
    }

    // Then Sort
    const sorted = [...filtered];
    switch (sortBy) {
      case "newest":
        return sorted.sort((a, b) => {
          const dateA = a.createdAt || a.id || 0;
          const dateB = b.createdAt || b.id || 0;
          return dateB - dateA; // Descending (newest first)
        });
      case "oldest":
        return sorted.sort((a, b) => {
          const dateA = a.createdAt || a.id || 0;
          const dateB = b.createdAt || b.id || 0;
          return dateA - dateB; // Ascending (oldest first)
        });
      case "language":
        return sorted.sort((a, b) =>
          (a.language || "English").localeCompare(b.language || "English")
        );
      case "discipline":
        return sorted.sort((a, b) =>
          (a.discipline || "").localeCompare(b.discipline || "")
        );
      case "difficulty": {
        const diffOrder = { Easy: 1, Medium: 2, Hard: 3 };
        return sorted.sort(
          (a, b) =>
            (diffOrder[a.difficulty] || 0) - (diffOrder[b.difficulty] || 0)
        );
      }
      case "default":
      default:
        return sorted; // Keep original sheet order
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [questions, sortBy, filterMode, searchTerm]);

  // PERFORMANCE: Only render visible items
  const visibleQuestions = useMemo(() => {
    return sortedQuestions.slice(0, visibleCount);
  }, [sortedQuestions, visibleCount]);

  const hasMore = visibleCount < sortedQuestions.length;

  // Load more items when scrolling near bottom
  const loadMore = useCallback(() => {
    if (hasMore) {
      setVisibleCount((prev) =>
        Math.min(prev + LOAD_MORE_COUNT, sortedQuestions.length)
      );
    }
  }, [hasMore, sortedQuestions.length]);

  // Intersection Observer for infinite scroll
  useEffect(() => {
    const loader = loaderRef.current;
    if (!loader) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore) {
          loadMore();
        }
      },
      { threshold: 0.1 }
    );

    observer.observe(loader);
    return () => observer.disconnect();
  }, [hasMore, loadMore]);

  // Calculate available languages for each uniqueId
  const translationMap = useMemo(() => {
    if (!questions) return new Map();
    const map = new Map();
    questions.forEach((q) => {
      if (!q.uniqueId) return;
      if (!map.has(q.uniqueId)) {
        map.set(q.uniqueId, new Set());
      }
      map.get(q.uniqueId).add(q.language || "English");
    });
    return map;
  }, [questions]);

  // Map uniqueId+language -> question for quick lookup
  const questionsByIdAndLang = useMemo(() => {
    if (!questions) return new Map();
    const map = new Map();
    questions.forEach((q) => {
      if (!q.uniqueId) return;
      const key = `${q.uniqueId}::${q.language || "English"}`;
      map.set(key, q);
    });
    return map;
  }, [questions]);

  // Handle language switch - find and scroll to the matching translation
  const handleSwitchLanguage = (currentQuestion, targetLang) => {
    if (!currentQuestion.uniqueId) {
      showMessage(
        `Cannot switch: Question has no unique ID for linking translations.`
      );
      return;
    }

    const key = `${currentQuestion.uniqueId}::${targetLang}`;
    const targetQuestion = questionsByIdAndLang.get(key);

    if (targetQuestion) {
      // Find the question in the DOM and scroll to it
      const index = sortedQuestions.findIndex(
        (q) => q.id === targetQuestion.id
      );
      if (index !== -1) {
        // Ensure the question is rendered by expanding visible count if needed
        if (index >= visibleCount) {
          setVisibleCount(index + 10); // Load up to that question plus a few more
        }

        // Wait for render then scroll
        setTimeout(() => {
          const element = document.querySelector(
            `[data-question-index="${index}"]`
          );
          if (element) {
            element.scrollIntoView({ behavior: "smooth", block: "center" });
            element.classList.add("ring-2", "ring-green-500");
            setTimeout(
              () => element.classList.remove("ring-2", "ring-green-500"),
              2000
            );
          }
        }, 100);
        showMessage(`Scrolled to ${targetLang} version.`);
      }
    } else {
      showMessage(
        `${targetLang} version not found in current view. Try using "Sort by Language" to find it.`
      );
    }
  };

  return (
    <div className="space-y-4">
      <div
        className="flex justify-between items-center bg-blue-900/20 p-4 rounded border border-blue-800/50"
        data-tour="database-search"
      >
        <div
          className="flex items-center gap-4 w-full justify-between"
          data-tour="database-actions"
        >
          <div>
            <h2 className="text-lg font-bold text-blue-400 flex items-center gap-2">
              <Icon name="database" /> Database View
            </h2>
            <p className="text-xs text-blue-300/70">
              Showing {visibleQuestions.length} of {uniqueQuestionCount}{" "}
              questions
              {hasMore && ` ΓÇó scroll for more`}
            </p>
          </div>

          {/* Admin-only actions */}
          {isAdmin && (
            <div className="flex items-center gap-2">
              <button
                onClick={handleExport}
                className="px-4 py-2 bg-green-600 hover:bg-green-500 text-white text-xs font-bold rounded-lg transition-all flex items-center gap-2"
                title="Export questions for ChatGPT/Gemini Business critique (FREE!)"
              >
                <Icon name="download" size={14} />
                Export for AI
              </button>
            </div>
          )}
        </div>
      </div>

      <MetricsDashboard questions={questions} />

      <div data-tour="database-grid">
        {sortedQuestions.length === 0 ? (
          <div className="text-center py-10 text-slate-500">
            No questions loaded from database. Click Refresh.
          </div>
        ) : (
          <>
            {visibleQuestions.map((q, i) => (
              <div
                key={q.uniqueId || q.id || i}
                data-question-index={i}
                className="opacity-75 hover:opacity-100 transition-all"
              >
                <QuestionItem
                  q={q}
                  onUpdateStatus={() => {}}
                  onExplain={() => {}}
                  onVariate={() => {}}
                  onCritique={() => {}}
                  onTranslateSingle={() => {}}
                  onSwitchLanguage={(targetLang) =>
                    handleSwitchLanguage(q, targetLang)
                  }
                  onDelete={() => {}}
                  onUpdateQuestion={onUpdateQuestion}
                  onKickBack={onKickBack}
                  availableLanguages={translationMap.get(q.uniqueId)}
                  isProcessing={false}
                  appMode="database"
                  showMessage={showMessage}
                  userRole={userRole} // NEW
                />
              </div>
            ))}

            {/* Infinite scroll trigger */}
            {hasMore && (
              <div
                ref={loaderRef}
                className="flex items-center justify-center py-8 text-slate-500"
              >
                <Icon name="loader" className="animate-spin mr-2" size={16} />
                <span className="text-sm">Loading more questions...</span>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default DatabaseView;

import Icon from './Icon';

const DraftRestorationBanner = ({ timestamp, onClear }) => {
    const formatTimestamp = (ts) => {
        const date = new Date(ts);
        const now = new Date();
        const diffMinutes = Math.floor((now - date) / 60000);
        
        if (diffMinutes < 1) return 'just now';
        if (diffMinutes < 60) return `${diffMinutes} minute${diffMinutes > 1 ? 's' : ''} ago`;
        
        return date.toLocaleString();
    };

    return (
        <div className="bg-blue-900/20 border border-blue-700 rounded-lg p-4 mb-4 animate-in slide-in-from-top">
            <div className="flex items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                    <Icon name="info" size={20} className="text-blue-400" />
                    <div>
                        <p className="text-white font-medium">
                            Draft Restored
                        </p>
                        <p className="text-sm text-slate-400">
                            Your work from {formatTimestamp(timestamp)} has been restored
                        </p>
                    </div>
                </div>
                <button
                    onClick={onClear}
                    className="px-3 py-1 text-sm bg-blue-700 hover:bg-blue-600 text-white rounded transition-colors"
                >
                    Clear Draft
                </button>
            </div>
        </div>
    );
};

export default DraftRestorationBanner;

import Icon from "./Icon";

const FilterButton = ({ mode, current, setFilter, label, count }) => {
  const isActive = mode === current;
  const baseClasses =
    "px-3 py-1 text-xs font-medium rounded transition-all flex items-center gap-1";
  const activeClasses =
    "bg-orange-600 text-white shadow-md shadow-orange-900/50";
  let inactiveClasses = "bg-slate-800 text-slate-400 hover:bg-slate-700/50";
  if (mode === "accepted" && !isActive)
    inactiveClasses = "bg-green-900/20 text-green-400 hover:bg-green-900/30";
  if (mode === "rejected" && !isActive)
    inactiveClasses = "bg-red-900/20 text-red-400 hover:bg-red-900/30";
  if (mode === "pending" && !isActive)
    inactiveClasses = "bg-yellow-900/20 text-yellow-400 hover:bg-yellow-900/30";
  if (mode === "other" && !isActive)
    inactiveClasses = "bg-indigo-900/20 text-indigo-400 hover:bg-indigo-900/30";
  return (
    <button
      onClick={() => setFilter(mode)}
      className={`${baseClasses} ${isActive ? activeClasses : inactiveClasses}`}
    >
      <Icon
        name={
          mode === "accepted"
            ? "check"
            : mode === "rejected"
            ? "x"
            : mode === "pending"
            ? "clock"
            : mode === "other"
            ? "help-circle"
            : "list"
        }
        size={12}
      />
      {label}{" "}
      <span className="text-[10px] bg-slate-950/50 px-1.5 rounded-full">
        {count}
      </span>
    </button>
  );
};

export default FilterButton;

