import React from "react";
import NameEntryModal from "./NameEntryModal";
import ClearConfirmationModal from "./ClearConfirmationModal";
import BlockingProcessModal from "./BlockingProcessModal";
import ApiKeyModal from "./ApiKeyModal";
import TermsOfUseModal from "./TermsOfUseModal";
import CookieConsentBanner from "./CookieConsentBanner";
import AgeGateModal from "./AgeGateModal";
import DeleteConfirmationModal from "./DeleteConfirmationModal";
import TutorialOverlay from "./TutorialOverlay";

import BulkExportModal from "./BulkExportModal";
import AnalyticsDashboard from "./AnalyticsDashboard";
import DangerZoneModal from "./DangerZoneModal";
import { Suspense } from "react";

// Standard Modals
// Lazy Modals
// Standard Modals
// Lazy Modals

const GlobalModals = ({ visibility, state, handlers }) => {
  const {
    showNameModal,
    showClearModal,
    showBulkExportModal,
    showAnalytics,
    showDangerZone,
    showApiKeyModal,
    showTerms,
    showAgeGate,
    tutorialActive,
    deleteConfirmId,
  } = visibility;

  const {
    config,
    isProcessing,
    status,
    translationProgress,
    allQuestionsMap,
    currentStep,
    tutorialSteps,
    activeScenario,

    isAdmin, // passed for SettingsModal
  } = state;

  const {
    handleNameSave,
    handleDeleteAllQuestions,
    handleBulkExport,
    confirmDelete,
    setDeleteConfirmId,
    onCloseBulkExport,
    onCloseAnalytics,
    onCloseDangerZone,
    onCloseApiKey,
    handleSaveApiKey,
    setShowTerms,
    setTermsAccepted,
    setShowAgeGate,
    handleTutorialNext,
    handleTutorialPrev,
    handleTutorialSkip,
    handleTutorialComplete,
    onHardReset,
    window, // needed for reloads/redirects?
  } = handlers;

  return (
    <>
      {/* Blocking Process - Highest Priority */}
      {isProcessing && (
        <BlockingProcessModal
          isProcessing={isProcessing}
          status={status}
          translationProgress={translationProgress}
        />
      )}

      {/* Critical Entry/Exit Modals */}
      {config.creatorName === "" && showNameModal && (
        <NameEntryModal onSave={handleNameSave} />
      )}

      {showClearModal && (
        <ClearConfirmationModal
          onConfirm={handleDeleteAllQuestions}
          onCancel={() => handlers.setShowClearModal(false)}
        />
      )}

      <DeleteConfirmationModal
        deleteConfirmId={deleteConfirmId}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteConfirmId(null)}
      />

      <ApiKeyModal
        isOpen={showApiKeyModal}
        onClose={onCloseApiKey}
        onSave={handleSaveApiKey}
        currentKey={config.apiKey}
      />

      <AgeGateModal
        isOpen={showAgeGate}
        onConfirm={() => {
          setShowAgeGate(false);
          setShowTerms(true);
        }}
        onExit={() => {
          window.location.href = "about:blank";
        }}
      />

      <TermsOfUseModal
        isOpen={showTerms}
        onAccept={() => {
          localStorage.setItem("ue5_terms_accepted", "true");
          setShowTerms(false);
          setTermsAccepted(true);
        }}
        onDecline={() => {
          window.location.href = "about:blank";
        }}
      />

      <CookieConsentBanner />

      {/* Lazy Loaded Modals */}
      <Suspense fallback={null}>
        {showBulkExportModal && (
          <BulkExportModal
            onClose={onCloseBulkExport}
            onExport={handleBulkExport}
            questionCount={allQuestionsMap?.size || 0}
          />
        )}

        <AnalyticsDashboard isOpen={showAnalytics} onClose={onCloseAnalytics} />

        {showDangerZone && (
          <DangerZoneModal
            isOpen={showDangerZone}
            onClose={onCloseDangerZone}
            onClearData={handleDeleteAllQuestions}
            onHardReset={onHardReset}
            config={config}
            isAdmin={isAdmin}
          />
        )}
      </Suspense>

      {/* Tutorial Overlay */}
      {tutorialActive && (
        <TutorialOverlay
          steps={tutorialSteps}
          currentStepIndex={currentStep}
          onNext={handleTutorialNext}
          onPrev={handleTutorialPrev}
          onSkip={handleTutorialSkip}
          onComplete={handleTutorialComplete}
          activeScenario={activeScenario}
        />
      )}
    </>
  );
};

export default GlobalModals;

import { useState, useEffect, useRef } from "react";
import Icon from "./Icon";
import useConnectionStatus from "../hooks/useConnectionStatus";
import { signOutUser } from "../services/firebase";
import { APP_VERSION } from "../utils/constants";

const getVersionDisplay = () => {
  const projectId = import.meta.env.VITE_FIREBASE_PROJECT_ID || "";
  console.log(
    "≡ƒöì [Header] Project ID:",
    projectId,
    "| isProd:",
    projectId.includes("prod")
  );
  const isProd = projectId.includes("prod");
  // Get git commit hash from build-time define (set in vite.config.js)
  const gitCommit = typeof __GIT_COMMIT__ !== "undefined" ? __GIT_COMMIT__ : "";
  const commitSuffix = gitCommit ? `-${gitCommit}` : "";
  return {
    version: `${APP_VERSION}${commitSuffix}-${isProd ? "PROD" : "DEV"}`,
    isProd,
  };
};

const Header = ({
  apiKeyStatus,
  isCloudReady,
  onHome,
  creatorName,
  appMode,
  tokenUsage = { inputTokens: 0, outputTokens: 0, totalCost: 0 },
  _onRestartTutorial,
  onStartTutorial,
  isAdmin,
  onSignOut,
  user, // Add user prop for super admin check
}) => {
  const _showTutorialCenter = useState(false);

  // Super Admin check - case-insensitive with trim
  const userEmail = user?.email?.toLowerCase();
  const envSuperAdmin =
    import.meta.env.VITE_SUPER_ADMIN_EMAIL?.trim()?.toLowerCase();
  const isSuperAdmin = userEmail === envSuperAdmin && envSuperAdmin;
  const connectionStatus = useConnectionStatus();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const menuRef = useRef(null);

  // Close mobile menu on ESC key or click outside
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === "Escape") setMobileMenuOpen(false);
    };
    const handleClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setMobileMenuOpen(false);
      }
    };
    if (mobileMenuOpen) {
      document.addEventListener("keydown", handleEsc);
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("keydown", handleEsc);
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [mobileMenuOpen]);
  const isReview = appMode === "review";
  const isAnalytics = appMode === "analytics";
  const borderColor = isReview
    ? "border-indigo-600"
    : isAnalytics
    ? "border-emerald-600"
    : "border-orange-600";
  const titleColor = isReview
    ? "text-indigo-50"
    : isAnalytics
    ? "text-emerald-50"
    : "text-orange-50";
  const headerBg = isReview
    ? "bg-slate-950 bg-gradient-to-r from-indigo-950/30 to-slate-950"
    : isAnalytics
    ? "bg-slate-950 bg-gradient-to-r from-emerald-950/30 to-slate-950"
    : "bg-slate-950";

  const totalTokens =
    (tokenUsage.inputTokens || 0) + (tokenUsage.outputTokens || 0);
  const formattedTokens =
    totalTokens >= 1000 ? `${(totalTokens / 1000).toFixed(1)}k` : totalTokens;
  const formattedCost = (tokenUsage.totalCost || 0).toFixed(4);

  const getTitle = () => {
    if (isReview) return "Review & Audit Console";
    if (isAnalytics) return "Analytics Dashboard";
    return "UE5 Question Generator";
  };

  const getSubtitle = () => {
    if (isReview) return "Quality Assurance ΓÇó Translation ΓÇó Verification";
    if (isAnalytics)
      return "Generation Metrics ΓÇó Quality Trends ΓÇó URL Validation";
    return "Universal Scenario-Based Generator ΓÇó Official Docs Only";
  };

  const getBadgeStyle = () => {
    if (isReview)
      return "bg-indigo-500/20 text-indigo-300 border-indigo-500/50";
    if (isAnalytics)
      return "bg-emerald-500/20 text-emerald-300 border-emerald-500/50";
    if (appMode === "database")
      return "bg-blue-500/20 text-blue-300 border-blue-500/50";
    return "bg-orange-500/20 text-orange-300 border-orange-500/50";
  };

  const getBadgeText = () => {
    if (isReview) return "REVIEW MODE";
    if (isAnalytics) return "ANALYTICS";
    if (appMode === "database") return "DATABASE VIEW";
    return "CREATE MODE";
  };

  return (
    <header
      className={`${headerBg} text-white p-6 shadow-xl border-b ${borderColor} relative z-20 transition-all duration-500`}
      role="banner"
      aria-label="Application header"
    >
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div
          className="flex items-center gap-3 cursor-pointer"
          onClick={onHome}
          title="Back to Home"
        >
          <div className="p-2 transition-colors duration-500">
            <img
              src="/UE5QuestionGenerator/logos/UE-Icon-2023-White.svg"
              alt="UE5 Logo"
              className="w-10 h-10 object-contain"
            />
          </div>
          <div>
            <h1
              className={`text-xl font-bold tracking-tight uppercase ${titleColor} transition-colors duration-500`}
            >
              {getTitle()}
            </h1>
            <p className="text-slate-400 text-xs mt-0.5">{getSubtitle()}</p>
          </div>
        </div>
        <div className="hidden lg:flex items-center gap-2 text-xs font-mono">
          {/* Mode Badge */}
          <span
            className={`flex items-center h-7 px-2 rounded text-[10px] font-semibold uppercase tracking-wider border whitespace-nowrap ${getBadgeStyle()}`}
          >
            {getBadgeText()}
          </span>
          {/* Tutorial Button - First */}
          {onStartTutorial &&
            ["create", "review", "database", "analytics"].includes(appMode) && (
              <button
                onClick={() => onStartTutorial(appMode)}
                className="flex items-center h-7 gap-1 px-2 text-[10px] font-bold bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all shadow-lg shadow-indigo-900/50 whitespace-nowrap"
                title={`Start ${appMode} tutorial`}
              >
                <Icon name="help-circle" size={12} />
                Tutorial
              </button>
            )}
          {/* User Info */}
          {creatorName && (
            <div className="flex items-center h-7 gap-1.5 font-medium text-slate-300 px-2 bg-slate-800/50 rounded-lg whitespace-nowrap text-[10px]">
              <Icon
                name={isAdmin ? "shield-check" : "user"}
                size={12}
                className={isAdmin ? "text-orange-500" : "text-green-500"}
              />
              <span>{creatorName}</span>
              {isAdmin && (
                <span
                  className={`text-[9px] font-semibold px-1 py-0.5 rounded border ml-0.5 ${
