import { useState } from "react";
import Icon from "./Icon";
import { sanitizeText } from "../utils/sanitize";

/**
 * Comprehensive Critique Modal - Shows critique + side-by-side improvements
 * Combines AI feedback with visual comparison in one view
 */
const ImprovementModal = ({
  originalQuestion,
  improvedQuestion,
  changesExplanation,
  critiqueText,
  critiqueScore,
  improvedScore, // Score the question would get AFTER applying improvements
  onApply,
  onDismiss,
}) => {
  const [isApplying, setIsApplying] = useState(false);

  const handleApply = async () => {
    setIsApplying(true);
    try {
      await onApply(improvedQuestion);
    } catch (err) {
      console.error("[ImprovementModal] onApply error:", err);
    }
    setIsApplying(false);
  };

  const scoreDelta =
    improvedScore && critiqueScore ? improvedScore - critiqueScore : 0;

  const originalTags = originalQuestion?.tags || [];
  const improvedTags = improvedQuestion?.tags || [];
  const newTags = improvedQuestion
    ? improvedTags.filter((tag) => !originalTags.includes(tag))
    : [];

  return (
    <div className="fixed inset-0 bg-black/80 z-[10000] flex items-start justify-center pt-4 p-4 overflow-y-auto pointer-events-auto">
      <div
        className="bg-slate-900 rounded-xl border-2 border-green-500/50 shadow-2xl max-w-6xl w-full max-h-[90vh] overflow-hidden flex flex-col pointer-events-auto relative"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-green-900/30 to-blue-900/30 border-b border-green-600/30 px-4 py-2">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Icon name="sparkles" size={20} className="text-green-400" />
              <h2 className="text-lg font-bold text-white">AI Critique</h2>
              <span
                className={`px-3 py-1 rounded text-sm font-bold ${
                  critiqueScore >= 90
                    ? "bg-green-600/20 border border-green-500/50 text-green-300"
                    : critiqueScore >= 70
                    ? "bg-yellow-600/20 border border-yellow-500/50 text-yellow-300"
                    : "bg-red-600/20 border border-red-500/50 text-red-300"
                }`}
              >
                Score: {critiqueScore}/100
              </span>
              {scoreDelta > 0 && (
                <span className="px-2 py-1 bg-green-600/20 border border-green-500/50 rounded text-xs font-bold text-green-300">
                  +{scoreDelta} pts improvement
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 scrollbar-thin scrollbar-thumb-slate-600 scrollbar-track-transparent hover:scrollbar-thumb-slate-500">
          {/* AI Critique Feedback */}
          <div className="bg-orange-900/20 border border-orange-700/30 rounded-lg p-3">
            <div className="flex items-start gap-2 mb-2">
              <Icon
                name="message-square"
                size={16}
                className="text-orange-400 mt-0.5 flex-shrink-0"
              />
              <div className="text-xs font-bold text-orange-400 uppercase tracking-wide">
                AI Critique
              </div>
            </div>
            <div className="text-sm text-slate-200 leading-relaxed">
              {critiqueText}
            </div>
          </div>

          {/* Suggested Improvement Section */}
          {changesExplanation && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Icon name="zap" size={16} className="text-green-400" />
                <div className="text-sm font-bold text-green-400 uppercase tracking-wide">
                  Suggested Improvement
                </div>
              </div>

              {/* Why Explanation */}
              <div className="bg-blue-900/15 border border-blue-700/30 rounded-lg p-2.5 mb-3">
                <div className="flex items-start gap-2">
                  <Icon
                    name="lightbulb"
                    size={14}
                    className="text-blue-400 mt-0.5 flex-shrink-0"
                  />
                  <div className="text-xs text-slate-200 leading-relaxed">
                    <strong className="text-blue-400">Why:</strong>{" "}
                    {changesExplanation}
                  </div>
                </div>
              </div>

              {/* Column Headers with Scores */}
              <div className="grid grid-cols-2 gap-4 mb-3">
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-xs font-bold text-slate-400 flex items-center gap-1.5 uppercase tracking-wide">
                    <Icon name="file-text" size={14} />
                    Original
                  </h3>
                  <span
                    className={`px-2 py-0.5 rounded text-xs font-bold border ${
                      critiqueScore >= 90
                        ? "bg-green-900/50 border-green-500 text-green-300"
                        : critiqueScore >= 70
                        ? "bg-yellow-900/50 border-yellow-500 text-yellow-300"
                        : "bg-red-900/50 border-red-500 text-red-300"
                    }`}
                  >
                    {critiqueScore}/100
                  </span>
                </div>
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-xs font-bold text-green-400 flex items-center gap-1.5 uppercase tracking-wide">
                    <Icon name="check-circle" size={14} />
                    Improved
                  </h3>
                  {improvedScore ? (
                    <span
                      className={`px-2 py-0.5 rounded text-xs font-bold border ${
                        improvedScore >= 90
                          ? "bg-green-900/50 border-green-500 text-green-300"
                          : improvedScore >= 70
                          ? "bg-yellow-900/50 border-yellow-500 text-yellow-300"
                          : "bg-orange-900/50 border-orange-500 text-orange-300"
                      }`}
                    >
                      {improvedScore}/100
                      {scoreDelta > 0 && (
                        <span className="ml-1 text-green-400">
                          (+{scoreDelta})
                        </span>
                      )}
                    </span>
                  ) : (
                    <span className="px-2 py-0.5 bg-slate-700/50 rounded text-xs text-slate-500 italic">
                      Not scored
                    </span>
                  )}
                </div>
              </div>

              {/* Question Text */}
              <div className="grid grid-cols-2 gap-4 mb-4">
                <div className="bg-slate-800/40 p-3 rounded">
                  <div
                    className="text-sm text-white leading-relaxed"
                    dangerouslySetInnerHTML={sanitizeText(
                      originalQuestion.question
                    )}
                  />
                </div>
                <div className="bg-green-900/20 p-3 rounded border border-green-700/30">
                  <div
                    className="text-sm text-white leading-relaxed"
                    dangerouslySetInnerHTML={sanitizeText(
                      improvedQuestion?.question || originalQuestion.question
                    )}
                  />
                </div>
              </div>

              {/* Answer Options */}
              <div className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">
                Answer Options
              </div>
              <div className="space-y-1.5 mb-4">
                {["A", "B", "C", "D"].map((letter) => {
                  const originalOpt =
                    originalQuestion.options?.[letter] ||
                    originalQuestion[`option${letter}`] ||
                    "";
                  const improvedOpt = improvedQuestion
                    ? improvedQuestion.options?.[letter] ||
                      improvedQuestion[`option${letter}`] ||
                      ""
                    : originalOpt; // Fall back to original if no improvement
                  const originalCorrect =
                    originalQuestion.correctLetter === letter ||
                    originalQuestion.correct === letter;
                  const improvedCorrect = improvedQuestion
                    ? improvedQuestion.correctLetter === letter ||
                      improvedQuestion.correct === letter
                    : originalCorrect; // Fall back to original if no improvement

                  return (
                    <div key={letter} className="grid grid-cols-2 gap-4">
                      {/* Original Option */}
                      <div
                        className={`p-2 rounded text-xs border ${
                          originalCorrect
                            ? "bg-green-600/10 border-green-500/40"
                            : "bg-slate-800/40 border-slate-700/40"
                        }`}
                      >
                        <span className="font-bold text-slate-400 mr-1.5">
                          {letter})
                        </span>
                        <span className="text-white">
                          {originalOpt || "(empty)"}
                        </span>
                      </div>

                      {/* Improved Option */}
                      <div
                        className={`p-2 rounded text-xs border ${
                          improvedCorrect
                            ? "bg-green-600/10 border-green-500/40"
                            : "bg-slate-800/40 border-slate-700/40"
                        }`}
                      >
                        <span className="font-bold text-slate-400 mr-1.5">
                          {letter})
                        </span>
                        <span className="text-white">
                          {improvedOpt || "(empty)"}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Tags */}
              {(originalTags.length > 0 || improvedTags.length > 0) && (
                <div>
                  <div className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">
                    Tags
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    {/* Original Tags */}
                    <div className="flex flex-wrap gap-1.5">
                      {originalTags.length > 0 ? (
                        originalTags.map((tag, idx) => (
                          <span
                            key={idx}
                            className="px-2 py-1 bg-slate-700/50 border border-slate-600/50 rounded text-xs text-slate-300"
                          >
                            #{tag}
                          </span>
                        ))
                      ) : (
                        <span className="text-xs text-slate-500 italic">
                          No tags
                        </span>
                      )}
                    </div>

                    {/* Improved Tags */}
                    <div className="flex flex-wrap gap-1.5">
                      {improvedTags.length > 0 ? (
                        improvedTags.map((tag, idx) => {
                          const isNew = newTags.includes(tag);
                          return (
                            <span
                              key={idx}
                              className={`px-2 py-1 rounded text-xs ${
                                isNew
                                  ? "bg-green-600/30 border border-green-500/50 text-green-200"
                                  : "bg-slate-700/50 border border-slate-600/50 text-slate-300"
                              }`}
                            >
                              #{tag}
                            </span>
                          );
                        })
                      ) : (
                        <span className="text-xs text-slate-500 italic">
                          No tags
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="border-t border-slate-700 bg-slate-900/90 px-4 py-2 flex items-center justify-center gap-2.5 relative z-10 pointer-events-auto">
          <div className="flex gap-2.5">
            <button
              onClick={(e) => {
                e.stopPropagation();
                onDismiss();
              }}
              className="px-4 py-1.5 rounded-lg font-bold text-xs bg-slate-800 text-slate-300 hover:bg-slate-700 border border-slate-600 transition-all pointer-events-auto cursor-pointer"
            >
              {changesExplanation ? "Keep Original" : "Close"}
            </button>
            {changesExplanation && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  handleApply();
                }}
                disabled={isApplying}
                className="px-4 py-1.5 rounded-lg font-bold text-xs bg-green-600 text-white hover:bg-green-500 shadow-lg shadow-green-900/50 transition-all disabled:opacity-50 pointer-events-auto cursor-pointer"
              >
                {isApplying ? "Applying..." : "Apply Improvements"}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImprovementModal;

import { useState, useEffect, useCallback } from "react";
import {
  validateInvite,
  consumeInvite,
  getInviteFromUrl,
  clearInviteFromUrl,
} from "../services/inviteService";
import {
  signInWithGoogle,
  signUpWithEmail,
  signInWithEmail,
} from "../services/firebase";
import Icon from "./Icon";

/**
 * InviteSignUp - Registration with invite code validation
 *
 * @param {Object} props
 * @param {Function} props.onSuccess - Called when registration completes
 * @param {Function} props.onCancel - Called when user cancels
 */
const InviteSignUp = ({ onSuccess, onCancel }) => {
  const [inviteCode, setInviteCode] = useState("");
  const [validationStatus, setValidationStatus] = useState(null);
  const [validationError, setValidationError] = useState("");
  const [inviteRole, setInviteRole] = useState("user");
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [authError, setAuthError] = useState("");

  // Email auth state
  const [showEmailAuth, setShowEmailAuth] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isNewUser, setIsNewUser] = useState(true);

  const handleValidate = useCallback(
    async (code) => {
      const codeToValidate = code || inviteCode;
      if (!codeToValidate.trim()) {
        setValidationError("Please enter an invite code");
        return;
      }

      setValidationStatus("validating");
      setValidationError("");

      try {
        const result = await validateInvite(codeToValidate.trim());
        if (result.valid) {
          setValidationStatus("valid");
          setInviteRole(result.role);
        }
      } catch (error) {
        setValidationStatus("invalid");
        setValidationError(error.message || "Invalid invite code");
      }
    },
    [inviteCode]
  );

  useEffect(() => {
    const urlInvite = getInviteFromUrl();
    if (urlInvite) {
      setInviteCode(urlInvite);
      handleValidate(urlInvite);
    }
  }, [handleValidate]);

  const handleGoogleSignIn = async () => {
    setIsAuthenticating(true);
    setAuthError("");
    try {
      await signInWithGoogle();
      const result = await consumeInvite(inviteCode.trim());
      clearInviteFromUrl();
      onSuccess?.(result.role);
    } catch (error) {
      let message = error.message || "Authentication failed";
      if (error.code === "auth/user-disabled") {
        message =
          "Your account has been disabled by an administrator. Please contact support if you believe this is an error.";
      }
      setAuthError(message);
      setIsAuthenticating(false);
    }
  };

  const handleEmailAuth = async (e) => {
    e.preventDefault();
    setIsAuthenticating(true);
    setAuthError("");
    try {
      if (isNewUser) {
        await signUpWithEmail(email, password);
      } else {
        await signInWithEmail(email, password);
      }
      const result = await consumeInvite(inviteCode.trim());
      clearInviteFromUrl();
      onSuccess?.(result.role);
    } catch (error) {
      let message = error.message || "Authentication failed";
      if (error.code === "auth/email-already-in-use") {
        message = "Email already registered. Try signing in instead.";
        setIsNewUser(false);
      } else if (error.code === "auth/weak-password") {
        message = "Password should be at least 6 characters.";
      } else if (error.code === "auth/wrong-password") {
        message = "Incorrect password. Try again.";
      } else if (error.code === "auth/user-disabled") {
        message =
          "Your account has been disabled by an administrator. Please contact support if you believe this is an error.";
      }
      setAuthError(message);
      setIsAuthenticating(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-8 max-w-md w-full shadow-2xl">
        {/* Header */}
        <div className="text-center mb-6">
          <div className="w-16 h-16 bg-orange-600/20 rounded-full flex items-center justify-center mx-auto mb-4">
            <Icon name="key" size={32} className="text-orange-500" />
          </div>
          <h1 className="text-2xl font-bold text-white">
            Join UE5 Question Generator
          </h1>
          <p className="text-slate-400 text-sm mt-2">
            Enter your invite code to get started
          </p>
        </div>

        <div className="space-y-4">
          {/* Invite Code Input */}
          <div>
            <label
              htmlFor="invite-code"
              className="block text-sm font-medium text-slate-300 mb-2"
            >
              Invite Code
            </label>
            <input
              id="invite-code"
              type="text"
              value={inviteCode}
              onChange={(e) => setInviteCode(e.target.value.toUpperCase())}
              placeholder="Enter your invite code"
              className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-orange-500 font-mono tracking-wider"
              disabled={validationStatus === "valid"}
            />
          </div>

          {/* Status Messages */}
          {validationStatus === "validating" && (
            <div className="flex items-center gap-2 text-blue-400">
              <Icon name="loader" size={16} className="animate-spin" />
              <span>Validating invite code...</span>
            </div>
          )}
          {validationStatus === "valid" && (
            <div className="flex items-center gap-2 text-green-400 bg-green-900/20 p-3 rounded-lg">
              <Icon name="check-circle" size={16} />
              <span>
                Valid invite! Role: <strong>{inviteRole}</strong>
              </span>
            </div>
          )}
          {validationError && (
            <div className="flex items-center gap-2 text-red-400 bg-red-900/20 p-3 rounded-lg">
              <Icon name="x-circle" size={16} />
              <span>{validationError}</span>
            </div>
          )}
          {authError && (
            <div className="flex items-center gap-2 text-red-400 bg-red-900/20 p-3 rounded-lg">
              <Icon name="alert-triangle" size={16} />
              <span>{authError}</span>
            </div>
          )}

          {/* Actions */}
          {validationStatus !== "valid" ? (
            <button
              onClick={() => handleValidate()}
              disabled={validationStatus === "validating" || !inviteCode.trim()}
              className="w-full py-3 bg-orange-600 hover:bg-orange-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white font-bold rounded-lg transition-colors"
            >
              Validate Invite Code
            </button>
          ) : showEmailAuth ? (
            /* Email/Password Form */
            <form onSubmit={handleEmailAuth} className="space-y-3">
              <input
                type="email"
                placeholder="Email address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-orange-500"
                required
              />
              <input
                type="password"
                placeholder="Password (6+ characters)"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-orange-500"
                required
                minLength={6}
              />
              <button
                type="submit"
                disabled={isAuthenticating}
                className="w-full py-3 bg-orange-600 hover:bg-orange-500 disabled:opacity-50 text-white font-bold rounded-lg transition-colors"
              >
                {isAuthenticating
                  ? "Please wait..."
                  : isNewUser
                  ? "Create Account"
                  : "Sign In"}
              </button>
              <button
                type="button"
                onClick={() => setIsNewUser(!isNewUser)}
                className="w-full text-sm text-slate-400 hover:text-white"
              >
                {isNewUser
                  ? "Already have an account? Sign in"
                  : "New user? Create account"}
              </button>
              <button
                type="button"
                onClick={() => setShowEmailAuth(false)}
                className="w-full text-sm text-slate-500 hover:text-slate-300"
              >
                ΓåÉ Back to sign-in options
              </button>
            </form>
          ) : (
            /* Auth Options */
            <div className="space-y-3">
              <button
                onClick={handleGoogleSignIn}
                disabled={isAuthenticating}
                className="w-full flex items-center justify-center gap-3 py-3 bg-white hover:bg-slate-100 text-slate-900 font-bold rounded-lg transition-colors disabled:opacity-50"
              >
                {isAuthenticating ? (
                  <Icon name="loader" size={20} className="animate-spin" />
                ) : (
                  <GoogleIcon />
                )}
                {isAuthenticating ? "Signing in..." : "Continue with Google"}
              </button>
              <div className="flex items-center gap-3 text-slate-500 text-sm">
                <div className="flex-1 h-px bg-slate-700" />
                <span>or</span>
                <div className="flex-1 h-px bg-slate-700" />
              </div>
              <button
                onClick={() => setShowEmailAuth(true)}
                className="w-full flex items-center justify-center gap-3 py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-lg transition-colors border border-slate-700"
              >
                <Icon name="mail" size={20} />
                Continue with Email
              </button>
              <p className="text-xs text-slate-500 text-center">
                Any Google or email account works. No Epic Games login required.
              </p>
            </div>
          )}

          {onCancel && !showEmailAuth && (
            <button
              onClick={onCancel}
              className="w-full py-2 text-slate-400 hover:text-white transition-colors"
            >
              Cancel
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

