          <button
            onClick={() => setActiveTab("overview")}
            className={`px-3 py-1 text-[10px] font-bold uppercase rounded transition-colors ${
              activeTab === "overview"
                ? "bg-indigo-600 text-white"
                : "text-slate-400 hover:text-slate-200"
