          }
        >
          <Icon
            name={hasLock ? "lock" : isLocked ? "lock" : "loader"}
            size={14}
            className={
              hasLock
                ? "text-green-400"
                : isLocked
                ? "text-red-400"
                : "text-amber-400 animate-spin"
            }
          />
          <span>
            {hasLock ? "Reviewing" : isLocked ? "Locked" : "Connecting..."}
