              onOpenCritiqueModal={() => setShowImprovementModal(true)}
            />
          </div>

          <div className="flex items-center gap-2">
            <QuestionActions
              q={q}
              isLocked={isLocked}
              lockedBy={lockedBy}
              onUpdateStatus={onUpdateStatus}
              onCritique={onCritique}
              onExplain={onExplain}
              onVariate={onVariate}
              onDelete={onDelete}
              onUpdateQuestion={onUpdateQuestion}
