import { useState } from "react";
import { sanitizeText } from "../../utils/stringHelpers";
import Icon from "../Icon";

const QuestionContent = ({
  q,
  isEditing,
  editedText,
  setEditedText,
  setIsEditing,
  onUpdateQuestion,
  showMessage,
  appMode,
  isAdmin = false,
