            } rounded px-1 -mx-1 transition-colors ${
              q.status === "rejected"
                ? "text-slate-600 line-through decoration-slate-700"
                : "text-slate-200"
            }`}
            dangerouslySetInnerHTML={{
              __html: sanitizeText(displayedQ.question),
            }}
            onClick={() =>
              isAdmin && appMode !== "database" && setIsEditing(true)
