import React, { useEffect } from "react";
import Icon from "./Icon";
import QuestionItem from "./QuestionItem";

const ReviewMode = ({
  questions,
  currentIndex,
  setCurrentIndex,
  onUpdateStatus,
  onExplain,
  onVariate,
  onCritique,
  onApplyRewrite,
  onTranslateSingle,
  onSwitchLanguage,
  onDelete,
  onUpdateQuestion,
  translationMap,
  isProcessing,
  showMessage,
  onStartTutorial,
  onKickBack, // For restoring rejected questions
  userRole, // NEW
}) => {
  // Auto-start tutorial if not completed (and compliance modals are done)
  useEffect(() => {
    const isCompleted = localStorage.getItem("ue5_tutorial_review_completed");
    const ageVerified = localStorage.getItem("ue5_age_verified");
    const termsAccepted = localStorage.getItem("ue5_terms_accepted");

    // Only start tutorial if compliance modals are complete
    if (
      !isCompleted &&
      onStartTutorial &&
      questions.length > 0 &&
      ageVerified &&
      termsAccepted
    ) {
      // Small delay to ensure view is rendered
      setTimeout(() => onStartTutorial("review"), 500);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // Auto-adjust index if out of bounds (e.g. after accepting an item and list shrinks)
  React.useEffect(() => {
    if (questions && questions.length > 0 && currentIndex >= questions.length) {
      setCurrentIndex(questions.length - 1);
    }
  }, [questions, currentIndex, setCurrentIndex]);

  // Create a wrapper that handles navigation after language switch
  // This finds the translated variant by uniqueId and navigates to its index
  const handleLanguageSwitchWithNavigation = React.useCallback(
    (targetLang, uniqueId) => {
      console.log("≡ƒöä [ReviewMode] Language switch with navigation:", {
        targetLang,
        uniqueId,
      });

      // First, call the global language switch to re-filter questions
      onSwitchLanguage(targetLang, uniqueId);

      // Schedule navigation after the re-render with new language filter
      // We use setTimeout to ensure the questions array is updated
      if (uniqueId) {
        setTimeout(() => {
          // Find the question with this uniqueId in the new filtered list
          // Note: questions prop will be updated after re-render, so we need to query the DOM or use a ref
          // For now, we'll trust the filter and just stay at the same position
          // The parent needs to handle the navigation after filter update
          console.log(
            "≡ƒöä [ReviewMode] Navigation scheduled - parent should handle index update via pendingNavigationUniqueId"
          );
        }, 100);
      }
    },
    [onSwitchLanguage]
  );

  if (!questions || questions.length === 0) return null;

  const currentQuestion = questions[currentIndex];

  if (!currentQuestion) {
    return (
      <div className="text-center p-10 text-slate-500">
        No question selected.
      </div>
    );
  }
  const canGoPrev = currentIndex > 0;
  const canGoNext = currentIndex < questions.length - 1;

  return (
    <div className="flex flex-col items-center justify-start h-full max-w-4xl mx-auto w-full pt-4">
      <div
        className="w-full mb-6 flex justify-between items-center text-slate-400 text-xs font-mono bg-slate-900/50 p-2 rounded-lg border border-slate-800"
        data-tour="review-nav"
      >
        <button
          onClick={() => setCurrentIndex((prev) => Math.max(prev - 1, 0))}
          disabled={!canGoPrev}
          className="flex items-center gap-2 px-4 py-2 rounded hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors font-bold"
          data-tour="prev-button"
        >
          <Icon name="arrow-left" size={16} /> PREV
        </button>
        <div className="flex flex-col items-center">
          <span className="text-slate-500 uppercase text-[10px] tracking-widest">
            Review Progress
          </span>
          <span className="text-lg">
            <span className="text-white font-bold">{currentIndex + 1}</span>{" "}
            <span className="text-slate-600">/</span>{" "}
            <span className="text-slate-400 font-bold">{questions.length}</span>
          </span>
        </div>
        <button
          onClick={() =>
            setCurrentIndex((prev) => Math.min(prev + 1, questions.length - 1))
          }
          disabled={!canGoNext}
          className="flex items-center gap-2 px-4 py-2 rounded hover:bg-slate-800 disabled:opacity-30 disabled:hover:bg-transparent transition-colors font-bold"
          data-tour="next-button"
        >
          NEXT <Icon name="arrow-right" size={16} />
        </button>
      </div>

      <div
        className="w-full transform transition-all duration-300"
        data-tour="review-card"
      >
        <QuestionItem
          key={currentQuestion.uniqueId}
          q={currentQuestion}
          onUpdateStatus={onUpdateStatus}
          onExplain={onExplain}
          onVariate={onVariate}
          onCritique={onCritique}
          onApplyRewrite={onApplyRewrite}
          onTranslateSingle={onTranslateSingle}
          onSwitchLanguage={handleLanguageSwitchWithNavigation}
          onDelete={onDelete}
          onUpdateQuestion={onUpdateQuestion}
          availableLanguages={translationMap.get(currentQuestion.uniqueId)}
          isProcessing={isProcessing}
          appMode="review"
          showMessage={showMessage}
          onKickBack={onKickBack}
          userRole={userRole} // NEW
        />
      </div>
    </div>
  );
};

export default ReviewMode;

import Icon from "./Icon";
import { QUALITY_PASS_THRESHOLD } from "../utils/constants";

/**
 * ReviewProgressBar - Visual stepper workflow for the review process
 * Shows 3 steps: CRITIQUE ΓåÆ VERIFY ΓåÆ ACCEPT with connecting lines
 */
const ReviewProgressBar = ({
  question,
  isLocked = false,
  lockedBy = null,
  onCritique,
  onVerify,
  onAccept,
  onFix,
  isProcessing,
}) => {
  const q = question;

  // Determine step states
  // Check if critique was done (either score exists OR improvements were applied)
  const hasCritique =
    (q.critiqueScore !== undefined && q.critiqueScore !== null) ||
    q.improvementsApplied === true;
  // Pass if score >= threshold OR if improvements were applied (which means they passed review)
  const critiquePass =
    (hasCritique && q.critiqueScore >= QUALITY_PASS_THRESHOLD) ||
    q.improvementsApplied === true;
  const critiqueFail =
    q.critiqueScore !== null &&
    q.critiqueScore !== undefined &&
    q.critiqueScore < QUALITY_PASS_THRESHOLD &&
    !q.improvementsApplied;
  const isVerified = q.humanVerified === true;
  const isAccepted = q.status === "accepted";
  const isRejected = q.status === "rejected";

  if (isRejected) {
    const reasons = {
      low_score_after_retries:
        "Could not reach quality threshold after multiple attempts",
      factually_incorrect: "Contains factual errors",
      unclear: "Question or answers are unclear",
      duplicate: "Duplicate of another question",
      off_topic: "Not relevant to the topic",
      other: "Rejected by reviewer",
    };
    const reasonText =
      reasons[q.rejectionReason] ||
      q.rejectionReason?.replace(/_/g, " ") ||
      "Rejected";

    return (
      <div className="py-5 px-6 bg-red-950/50 border-2 border-red-600/50 rounded-lg">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-full bg-red-600 flex items-center justify-center flex-shrink-0 animate-pulse">
            <Icon name="x" size={24} className="text-white" />
          </div>
          <div className="flex-1">
            <div className="text-lg font-bold text-red-400 mb-1">
              Γ¥î QUESTION REJECTED
            </div>
            <div className="text-sm text-red-300/80">{reasonText}</div>
            <div className="text-xs text-red-400/60 mt-2">
              This question will not be exported. You can delete it or move on
              to the next question.
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isAccepted) {
    return (
      <div className="flex items-center justify-center gap-3 py-3 px-4 bg-green-950/30 border border-green-900/50 rounded-lg">
        <div className="w-8 h-8 rounded-full bg-green-600 flex items-center justify-center">
          <Icon name="check" size={18} className="text-white" />
        </div>
        <div>
          <span className="text-sm font-bold text-green-400">ACCEPTED</span>
          <span className="text-xs text-green-400/70 ml-2">
            Ready for export
          </span>
        </div>
      </div>
    );
  }

  const steps = [
    {
      num: 1,
      label: "Critique",
      sublabel: hasCritique
        ? `Score: ${q.critiqueScore}/100`
        : "Run AI analysis",
      completed: hasCritique && critiquePass,
      failed: critiqueFail,
      active: !hasCritique,
      ready: false,
      icon: "zap",
      onClick: onCritique,
    },
    {
      num: 2,
      label: "Verify",
      sublabel: isVerified ? "Source confirmed" : "Check source & answer",
      completed: isVerified,
      // For high scores, Verify is the next step (flash it)
      active: critiquePass && !isVerified,
      ready: false,
      locked: !critiquePass, // Locked until score >= threshold
      icon: "eye",
      onClick: onVerify,
    },
    {
      num: 3,
      label: "Accept",
      sublabel: "Approve for export",
      completed: false,
      // Accept becomes active AFTER verification
      active: isVerified && !isAccepted,
      ready: false,
      locked: !isVerified, // Must verify first
      icon: "check-circle",
      onClick: onAccept,
    },
  ];

  return (
    <div className="py-4 px-6 bg-slate-900/70 border border-slate-700/50 rounded-lg">
      <div className="flex items-center justify-between">
        {steps.map((step, index) => (
          <div key={step.num} className="flex items-center flex-1">
            {/* Step Circle + Content */}
            <button
              onClick={() =>
                !isLocked &&
                !step.locked &&
                !step.completed &&
                !isProcessing &&
                step.onClick?.()
              }
              disabled={
                isLocked || step.locked || step.completed || isProcessing
              }
              className={`
                                flex items-center gap-3 transition-all
                                ${
                                  step.active && !isProcessing && !isLocked
                                    ? "cursor-pointer group"
                                    : ""
                                }
                                ${
                                  step.locked || isLocked
                                    ? "opacity-40 cursor-not-allowed"
                                    : ""
                                }
                            `}
              title={
                isLocked
                  ? `Locked by ${lockedBy?.userEmail || "another user"}`
                  : step.locked
                  ? "Complete previous step first"
                  : step.sublabel
              }
              data-tour={step.num === 1 ? "critique-button" : undefined}
            >
              {/* Circle */}
              <div
                className={`
                                w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm transition-all
                                ${
                                  step.completed
                                    ? "bg-green-600 text-white"
                                    : step.failed
                                    ? "bg-red-600 text-white"
                                    : step.active
                                    ? "bg-orange-500 text-white animate-pulse shadow-lg shadow-orange-500/50 group-hover:bg-orange-400"
                                    : step.ready
                                    ? "bg-blue-600/70 text-white cursor-pointer hover:bg-blue-500"
                                    : "bg-slate-700 text-slate-400 border-2 border-slate-600"
                                }
                            `}
              >
                {step.completed ? (
                  <Icon name="check" size={18} />
                ) : step.failed ? (
                  <span>{q.critiqueScore}</span>
                ) : (
                  <span>{step.num}</span>
                )}
              </div>

              {/* Label */}
              <div className="flex flex-col">
                <span
                  className={`text-sm font-bold ${
                    step.completed
                      ? "text-green-400"
                      : step.failed
                      ? "text-red-400"
                      : step.active
                      ? "text-orange-400"
                      : step.ready
                      ? "text-blue-400"
                      : "text-slate-500"
                  }`}
                >
                  {step.label}
                </span>
                <span
                  className={`text-xs ${
                    step.completed
                      ? "text-green-400/70"
                      : step.failed
                      ? "text-red-400/70"
                      : step.active
                      ? "text-orange-400/70"
                      : step.ready
                      ? "text-blue-400/70"
                      : "text-slate-600"
                  }`}
                >
                  {step.sublabel}
                </span>
              </div>
            </button>

            {/* Connecting Line */}
            {index < steps.length - 1 && (
              <div
                className={`flex-1 h-0.5 mx-4 rounded ${
                  step.completed
                    ? "bg-green-600"
                    : step.failed
                    ? "bg-red-600/50"
                    : "bg-slate-700"
                }`}
              />
            )}
          </div>
        ))}
      </div>

      {/* Help Text */}
      {critiqueFail && (
        <div className="mt-3 text-center text-xs text-red-400/80 bg-red-950/30 py-2 rounded flex items-center justify-center gap-2">
          <Icon name="alert-triangle" size={12} />
          <span>Score below {QUALITY_PASS_THRESHOLD}.</span>
          {onFix && q.suggestedRewrite ? (
            <button
              onClick={onFix}
              disabled={isProcessing}
              className="px-2 py-0.5 bg-red-800 hover:bg-red-700 text-white text-[10px] font-bold rounded shadow-sm border border-red-600 transition-colors uppercase"
            >
              Fix & Re-run
            </button>
          ) : (
            <span>Check critique below.</span>
          )}
        </div>
      )}
      {critiquePass && !isVerified && (
        <div className="mt-3 text-center text-xs text-green-400/80 bg-green-950/30 py-2 rounded">
          <Icon name="check-circle" size={12} className="inline mr-1" />
          <strong>Good score!</strong> Click <strong>Verify</strong> to check
          the source and answer before accepting.
        </div>
      )}
      {isVerified && !isAccepted && (
        <div className="mt-3 text-center text-xs text-blue-400/80 bg-blue-950/30 py-2 rounded animate-pulse">
          <Icon name="check-circle" size={12} className="inline mr-1" />
          <strong>Verified!</strong> Click <strong>Accept</strong> to approve
          this question for export.
        </div>
      )}
    </div>
  );
};

export default ReviewProgressBar;

import React from "react";

/**
 * ScoreBadge - Color-coded badge for AI quality scores
 * Based on SCORING_RUBRIC.md tiers
 */
const ScoreBadge = ({ score }) => {
  if (score === null || score === undefined) {
    return null;
  }

  // Determine tier and styling based on score
  const getTierInfo = (score) => {
    if (score >= 90) {
      return {
        label: "Exceptional",
        color: "bg-green-500/20 text-green-400 border-green-500/50",
        icon: "Γ¡É",
      };
    } else if (score >= 80) {
      return {
        label: "Very Good",
        color: "bg-blue-500/20 text-blue-400 border-blue-500/50",
        icon: "Γ£¿",
      };
    } else if (score >= 70) {
      return {
        label: "Good",
        color: "bg-yellow-500/20 text-yellow-400 border-yellow-500/50",
        icon: "≡ƒæì",
      };
    } else if (score >= 60) {
      return {
        label: "Adequate",
        color: "bg-orange-500/20 text-orange-400 border-orange-500/50",
        icon: "ΓÜá∩╕Å",
      };
    } else {
      return {
        label: "Needs Work",
        color: "bg-red-500/20 text-red-400 border-red-500/50",
        icon: "Γ¥î",
      };
    }
  };

  const tier = getTierInfo(score);

  return (
    <div
      className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-md border text-xs font-bold ${tier.color}`}
      title={`AI Score: ${score}/100 - ${tier.label}`}
    >
      <span className="text-sm">{tier.icon}</span>
      <span>{score}</span>
    </div>
  );
};

export default ScoreBadge;

import { useState } from "react";
import Icon from "./Icon";
import {
  exportToScorm,
  validateQuestionsForExport,
} from "../services/scormExporter";

/**
 * SCORM Export Modal
 * Allows users to configure and export selected questions as SCORM 1.2 package
 */
const ScormExportModal = ({ questions, onClose }) => {
  const [config, setConfig] = useState({
    title: "UE5 Knowledge Assessment",
    description: "Test your Unreal Engine 5 knowledge",
    passingScore: 80,
    timeLimit: 30, // minutes
  });

  const [isExporting, setIsExporting] = useState(false);
  const [error, setError] = useState(null);

  const handleExport = async () => {
    setError(null);

    // Validate questions
    const validation = validateQuestionsForExport(questions);

    if (!validation.valid) {
      setError(validation.errors.join(", "));
      return;
    }

    // Show warnings if any
    if (validation.warnings.length > 0) {
      console.warn("SCORM Export Warnings:", validation.warnings);
    }

    setIsExporting(true);

    try {
      const result = await exportToScorm(questions, config);
      console.log("SCORM export successful:", result);

      // Close modal after successful export
      setTimeout(() => {
        onClose();
      }, 1000);
    } catch (err) {
      setError(err.message);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-slate-900 rounded-lg shadow-2xl max-w-md w-full border border-slate-700">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-700">
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            <Icon name="download" size={20} />
            Export to SCORM 1.2
          </h2>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-white transition-colors"
            disabled={isExporting}
          >
            <Icon name="x" size={20} />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-4">
          {/* Quiz Title */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Quiz Title
            </label>
            <input
              type="text"
              value={config.title}
              onChange={(e) => setConfig({ ...config, title: e.target.value })}
              className="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded text-white focus:border-blue-500 outline-none"
              placeholder="UE5 Knowledge Assessment"
              disabled={isExporting}
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Description (Optional)
            </label>
            <textarea
              value={config.description}
              onChange={(e) =>
                setConfig({ ...config, description: e.target.value })
              }
              className="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded text-white focus:border-blue-500 outline-none resize-none"
              rows={2}
              placeholder="Brief description of the assessment"
              disabled={isExporting}
            />
          </div>

          {/* Passing Score */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Passing Score: {config.passingScore}%
            </label>
            <input
              type="range"
              min="50"
              max="100"
              step="5"
              value={config.passingScore}
              onChange={(e) =>
                setConfig({ ...config, passingScore: parseInt(e.target.value) })
              }
              className="w-full"
              disabled={isExporting}
            />
            <div className="flex justify-between text-xs text-slate-500 mt-1">
              <span>50%</span>
              <span>100%</span>
            </div>
          </div>

          {/* Time Limit */}
          <div>
            <label className="block text-sm font-bold text-slate-300 mb-2">
              Time Limit
            </label>
            <select
              value={config.timeLimit}
              onChange={(e) =>
                setConfig({ ...config, timeLimit: parseInt(e.target.value) })
              }
              className="w-full px-3 py-2 bg-slate-800 border border-slate-700 rounded text-white focus:border-blue-500 outline-none"
              disabled={isExporting}
            >
              <option value={15}>15 minutes</option>
              <option value={30}>30 minutes</option>
              <option value={45}>45 minutes</option>
              <option value={60}>60 minutes</option>
              <option value={90}>90 minutes</option>
            </select>
          </div>

          {/* Question Count */}
          <div className="bg-slate-800 rounded p-3 border border-slate-700">
            <div className="flex items-center justify-between text-sm">
              <span className="text-slate-400">Selected Questions:</span>
              <span className="font-bold text-blue-400">
                {questions.length}
              </span>
            </div>
          </div>

          {/* Error Display */}
          {error && (
            <div className="bg-red-900/20 border border-red-500 rounded p-3">
              <p className="text-sm text-red-400">{error}</p>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-3 p-6 border-t border-slate-700">
          <button
            onClick={onClose}
            className="px-4 py-2 text-slate-400 hover:text-white transition-colors"
            disabled={isExporting}
          >
            Cancel
          </button>
          <button
            onClick={handleExport}
            disabled={isExporting || questions.length === 0}
            className="px-6 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-700 disabled:text-slate-500 text-white rounded font-semibold transition-colors flex items-center gap-2"
          >
            {isExporting ? (
              <>
                <Icon name="loader" size={16} className="animate-spin" />
                Generating...
              </>
            ) : (
              <>
                <Icon name="download" size={16} />
                Generate Package
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ScormExportModal;

import { useState } from "react";
import {
  signInWithGoogle,
  signUpWithEmail,
  signInWithEmail,
  resetPassword,
} from "../services/firebase";
import Icon from "./Icon";

const SignIn = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showEmailAuth, setShowEmailAuth] = useState(false);
  const [showPasswordReset, setShowPasswordReset] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isNewUser, setIsNewUser] = useState(true);
  const [resetSuccess, setResetSuccess] = useState(false);

  const handleGoogleSignIn = async () => {
    setIsLoading(true);
    setError(null);
    try {
      await signInWithGoogle();
    } catch (err) {
      console.error(err);
      if (err.code === "auth/configuration-not-found") {
        setError(
          "Google Sign-In is not enabled. Please enable it in the Firebase Console > Authentication > Sign-in method."
        );
      } else if (err.code === "auth/popup-closed-by-user") {
        setError("Sign-in cancelled.");
      } else if (err.code === "auth/user-disabled") {
        setError(
          "Your account has been disabled by an administrator. Please contact support if you believe this is an error."
        );
      } else {
        setError("Failed to sign in. Please try again.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleEmailAuth = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    try {
      if (isNewUser) {
        await signUpWithEmail(email, password);
      } else {
        await signInWithEmail(email, password);
      }
    } catch (err) {
      console.error(err);
      let message = err.message || "Authentication failed";
      if (err.code === "auth/email-already-in-use") {
        message = "Email already registered. Try signing in instead.";
        setIsNewUser(false);
      } else if (err.code === "auth/weak-password") {
        message = "Password should be at least 6 characters.";
      } else if (
        err.code === "auth/wrong-password" ||
        err.code === "auth/invalid-credential"
      ) {
        message = "Incorrect email or password.";
      } else if (err.code === "auth/user-not-found") {
        message = "No account found with this email. Try creating an account.";
        setIsNewUser(true);
      } else if (err.code === "auth/invalid-email") {
        message = "Invalid email address format.";
      } else if (err.code === "auth/user-disabled") {
        message =
          "Your account has been disabled by an administrator. Please contact support if you believe this is an error.";
      }
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const handlePasswordReset = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    setResetSuccess(false);

    try {
      await resetPassword(email);
      setResetSuccess(true);
    } catch (err) {
      console.error(err);
      let message = err.message || "Failed to send reset email";
      if (err.code === "auth/user-not-found") {
        message = "No account found with this email address.";
      } else if (err.code === "auth/invalid-email") {
        message = "Invalid email address format.";
      } else if (err.code === "auth/too-many-requests") {
        message = "Too many requests. Please try again later.";
      }
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-8 max-w-md w-full shadow-2xl text-center space-y-6">
        <div className="flex justify-center mb-4">
          <div className="w-20 h-20 bg-blue-600/20 rounded-full flex items-center justify-center">
            <Icon name="database" size={40} className="text-blue-500" />
          </div>
        </div>

        <div className="space-y-2">
          <h1 className="text-3xl font-bold text-white tracking-tight">
            UE5 Question Generator
          </h1>
          <p className="text-slate-400">
            Sign in to generate, manage, and export your question bank.
          </p>
        </div>

        {error && (
          <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-lg text-sm">
            {error}
          </div>
        )}

        {resetSuccess && (
          <div className="bg-green-500/10 border border-green-500/20 text-green-400 p-3 rounded-lg text-sm">
            Password reset email sent! Check your inbox and spam folder.
          </div>
        )}

        {showPasswordReset ? (
          // Password Reset Form
          <form onSubmit={handlePasswordReset} className="space-y-3 text-left">
            <div>
              <label
                htmlFor="reset-email"
                className="block text-sm font-medium text-slate-300 mb-2"
              >
                Email Address
              </label>
              <input
                id="reset-email"
                type="email"
                placeholder="your.email@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-blue-500"
                required
              />
            </div>
            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-colors"
            >
              {isLoading ? "Sending..." : "Send Reset Email"}
            </button>
            <button
              type="button"
              onClick={() => {
                setShowPasswordReset(false);
                setResetSuccess(false);
                setError(null);
              }}
              className="w-full text-sm text-slate-500 hover:text-slate-300 transition-colors"
            >
              ΓåÉ Back to sign in
            </button>
          </form>
        ) : !showEmailAuth ? (
          // Auth Options
          <div className="space-y-3">
            <button
              onClick={handleGoogleSignIn}
              disabled={isLoading}
              className="w-full flex items-center justify-center gap-3 bg-white hover:bg-slate-100 text-slate-900 font-bold py-3 px-6 rounded-xl transition-all transform hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isLoading ? (
                <Icon name="loader" className="animate-spin" />
              ) : (
                <GoogleIcon />
              )}
              {isLoading ? "Signing in..." : "Sign in with Google"}
            </button>

            <div className="flex items-center gap-3 text-slate-500 text-sm">
              <div className="flex-1 h-px bg-slate-700" />
              <span>or</span>
              <div className="flex-1 h-px bg-slate-700" />
            </div>

            <button
              onClick={() => setShowEmailAuth(true)}
              className="w-full flex items-center justify-center gap-3 py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-xl transition-all border border-slate-700"
            >
              <Icon name="mail" size={20} />
              Continue with Email
            </button>

            <p className="text-xs text-slate-600">
              Sign in with any Google or email account.
            </p>
          </div>
        ) : (
          // Email/Password Form
          <form onSubmit={handleEmailAuth} className="space-y-3 text-left">
            <div>
              <label
                htmlFor="email"
                className="block text-sm font-medium text-slate-300 mb-2"
              >
                Email Address
              </label>
              <input
                id="email"
                type="email"
                placeholder="your.email@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-blue-500"
                required
              />
            </div>
            <div>
              <label
                htmlFor="password"
                className="block text-sm font-medium text-slate-300 mb-2"
              >
                Password
              </label>
              <input
                id="password"
                type="password"
                placeholder="6+ characters"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-slate-800 border border-slate-700 rounded-lg text-white placeholder-slate-500 focus:outline-none focus:border-blue-500"
                required
                minLength={6}
              />
            </div>
            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-colors"
            >
              {isLoading
                ? "Please wait..."
                : isNewUser
                ? "Create Account"
                : "Sign In"}
            </button>
            <button
              type="button"
              onClick={() => setIsNewUser(!isNewUser)}
              className="w-full text-sm text-slate-400 hover:text-white transition-colors"
            >
              {isNewUser
                ? "Already have an account? Sign in"
                : "New user? Create account"}
            </button>
            {!isNewUser && (
              <button
                type="button"
                onClick={() => {
                  setShowPasswordReset(true);
                  setShowEmailAuth(false);
                }}
                className="w-full text-sm text-blue-400 hover:text-blue-300 transition-colors"
              >
                Forgot password?
              </button>
            )}
            <button
              type="button"
              onClick={() => setShowEmailAuth(false)}
              className="w-full text-sm text-slate-500 hover:text-slate-300 transition-colors"
            >
              ΓåÉ Back to sign-in options
            </button>
          </form>
        )}
      </div>
    </div>
  );
};

