import { useState } from 'react';
import Icon from './Icon';
import { TAGS_BY_DISCIPLINE } from '../utils/tagTaxonomy';

/**
 * TagManager Component
 * Allows users to create, edit, and delete custom tags for each discipline
 */
const TagManager = ({ discipline, customTags, onSaveCustomTags }) => {
    const [isExpanded, setIsExpanded] = useState(false);
    const [newTag, setNewTag] = useState('');
    const [editingTag, setEditingTag] = useState(null);
    const [editValue, setEditValue] = useState('');

    const predefinedTags = TAGS_BY_DISCIPLINE[discipline] || [];
    const userTags = customTags[discipline] || [];

    const handleAddTag = () => {
        if (!newTag.trim()) return;
        
        // Ensure tag starts with #
        const formattedTag = newTag.startsWith('#') ? newTag : `#${newTag}`;
        
        // Check for duplicates
        if (predefinedTags.includes(formattedTag) || userTags.includes(formattedTag)) {
            alert('This tag already exists!');
            return;
        }

        const updatedTags = {
            ...customTags,
            [discipline]: [...userTags, formattedTag]
        };
        
        onSaveCustomTags(updatedTags);
        setNewTag('');
    };

    const handleDeleteTag = (tag) => {
        if (!confirm(`Delete tag "${tag}"?`)) return;

        const updatedTags = {
            ...customTags,
            [discipline]: userTags.filter(t => t !== tag)
        };
        
        onSaveCustomTags(updatedTags);
    };

    const handleEditTag = (tag) => {
        setEditingTag(tag);
        setEditValue(tag);
    };

    const handleSaveEdit = () => {
        if (!editValue.trim()) return;
        
        const formattedTag = editValue.startsWith('#') ? editValue : `#${editValue}`;
        
        // Check for duplicates (excluding the tag being edited)
        if (formattedTag !== editingTag && 
            (predefinedTags.includes(formattedTag) || userTags.includes(formattedTag))) {
            alert('This tag already exists!');
            return;
        }

        const updatedTags = {
            ...customTags,
            [discipline]: userTags.map(t => t === editingTag ? formattedTag : t)
        };
        
        onSaveCustomTags(updatedTags);
        setEditingTag(null);
        setEditValue('');
    };

    const handleCancelEdit = () => {
        setEditingTag(null);
        setEditValue('');
    };

    return (
        <div className="border border-slate-700 rounded-lg bg-slate-900/50 overflow-hidden">
            {/* Header */}
            <button
                onClick={() => setIsExpanded(!isExpanded)}
                className="w-full px-4 py-3 flex items-center justify-between hover:bg-slate-800/50 transition-colors"
            >
                <div className="flex items-center gap-2">
                    <Icon name="tag" size={16} />
                    <span className="text-sm font-semibold text-slate-200">
                        Custom Tags for {discipline}
                    </span>
                    {userTags.length > 0 && (
                        <span className="text-xs bg-orange-500/20 text-orange-300 px-2 py-0.5 rounded-full">
                            {userTags.length} custom
                        </span>
                    )}
                </div>
                <Icon name={isExpanded ? "chevron-up" : "chevron-down"} size={16} />
            </button>

            {/* Body */}
            {isExpanded && (
                <div className="px-4 py-3 space-y-4 border-t border-slate-700">
                    {/* Add New Tag */}
                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase text-slate-400">
                            Add New Tag
                        </label>
                        <div className="flex gap-2">
                            <input
                                type="text"
                                value={newTag}
                                onChange={(e) => setNewTag(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') handleAddTag();
                                    if (e.key === 'Escape') setNewTag('');
                                }}
                                placeholder="e.g., CustomFeature or #CustomFeature"
                                className="flex-1 px-3 py-2 bg-slate-800 border border-slate-700 rounded text-sm outline-none focus:border-orange-500"
                            />
                            <button
                                onClick={handleAddTag}
                                disabled={!newTag.trim()}
                                className="px-4 py-2 bg-orange-600 hover:bg-orange-700 disabled:bg-slate-700 disabled:text-slate-500 text-white rounded text-sm font-medium transition-colors flex items-center gap-2"
                            >
                                <Icon name="plus" size={14} />
                                Add
                            </button>
                        </div>
                        <p className="text-xs text-slate-500">
                            Create custom tags to focus question generation on specific topics
                        </p>
                    </div>

                    {/* User Tags List */}
                    {userTags.length > 0 && (
                        <div className="space-y-2">
                            <label className="text-xs font-bold uppercase text-slate-400">
                                Your Custom Tags ({userTags.length})
                            </label>
                            <div className="space-y-1 max-h-48 overflow-y-auto custom-scrollbar">
                                {userTags.map(tag => (
                                    <div
                                        key={tag}
                                        className="flex items-center gap-2 p-2 bg-slate-800 rounded border border-slate-700 hover:border-slate-600 transition-colors"
                                    >
                                        {editingTag === tag ? (
                                            <>
                                                <input
                                                    type="text"
                                                    value={editValue}
                                                    onChange={(e) => setEditValue(e.target.value)}
                                                    onKeyDown={(e) => {
                                                        if (e.key === 'Enter') handleSaveEdit();
                                                        if (e.key === 'Escape') handleCancelEdit();
                                                    }}
                                                    className="flex-1 px-2 py-1 bg-slate-900 border border-orange-500 rounded text-sm outline-none"
                                                    autoFocus
                                                />
                                                <button
                                                    onClick={handleSaveEdit}
                                                    className="p-1 text-green-400 hover:text-green-300"
                                                    title="Save"
                                                >
                                                    <Icon name="check" size={14} />
                                                </button>
                                                <button
                                                    onClick={handleCancelEdit}
                                                    className="p-1 text-red-400 hover:text-red-300"
                                                    title="Cancel"
                                                >
                                                    <Icon name="x" size={14} />
                                                </button>
                                            </>
                                        ) : (
                                            <>
                                                <span className="flex-1 text-sm text-orange-300">
                                                    {tag}
                                                </span>
                                                <button
                                                    onClick={() => handleEditTag(tag)}
                                                    className="p-1 text-slate-400 hover:text-blue-400"
                                                    title="Edit"
                                                >
                                                    <Icon name="edit" size={14} />
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteTag(tag)}
                                                    className="p-1 text-slate-400 hover:text-red-400"
                                                    title="Delete"
                                                >
                                                    <Icon name="trash-2" size={14} />
                                                </button>
                                            </>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Predefined Tags Info */}
                    <div className="pt-3 border-t border-slate-700">
                        <div className="flex items-center justify-between mb-2">
                            <label className="text-xs font-bold uppercase text-slate-400">
                                Predefined Tags ({predefinedTags.length})
                            </label>
                            <span className="text-xs text-slate-500">Read-only</span>
                        </div>
                        <div className="flex flex-wrap gap-1.5 max-h-32 overflow-y-auto custom-scrollbar">
                            {predefinedTags.map(tag => (
                                <span
                                    key={tag}
                                    className="text-xs px-2 py-1 bg-slate-800/50 border border-slate-700 text-slate-400 rounded"
                                >
                                    {tag}
                                </span>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default TagManager;

import { useState, useMemo } from "react";
import Icon from "./Icon";
import QuizPreview from "./QuizPreview";
import ScormExportModal from "./ScormExportModal";
import { generateMockQuestions } from "../utils/mockQuestionGenerator";

/**
 * TestView - Admin view for configuring, previewing, and exporting quizzes
 * Allows admins to select approved questions and create assessments
 */
const TestView = ({
  questions = [],
  config: _appConfig,
  isAdmin,
  showMessage,
}) => {
  // Quiz configuration state
  const [quizConfig, setQuizConfig] = useState({
    title: "UE5 Knowledge Assessment",
    description: "Test your Unreal Engine 5 knowledge",
    passingScore: 80,
    timeLimit: 30, // minutes
    questionCount: 10,
    shuffleQuestions: true,
    showFeedback: "end", // "immediate" or "end"
    adaptiveDifficulty: true, // Adjust difficulty based on performance
  });

  // Filter state
  const [filters, setFilters] = useState({
    discipline: "",
  });

  // UI state
  const [showPreview, setShowPreview] = useState(false);
  const [showExport, setShowExport] = useState(false);
  const [selectedQuestionIds, setSelectedQuestionIds] = useState(new Set());
  const [mockQuestions, setMockQuestions] = useState([]);
  const [activeQuizQuestions, setActiveQuizQuestions] = useState([]); // Stabilized questions for preview

  const handleGenerateMockData = () => {
    const mocks = generateMockQuestions();
    setMockQuestions(mocks);
    if (showMessage)
      showMessage(`Generated ${mocks.length} mock questions`, 3000);
  };

  const handleClearMockData = () => {
    setMockQuestions([]);
    setSelectedQuestionIds(new Set());
    if (showMessage) showMessage("Mock data cleared", 2000);
  };

  // Get only approved questions (real + mock)
  const approvedQuestions = useMemo(() => {
    const realApproved = questions.filter((q) => q.status === "accepted");
    return [...realApproved, ...mockQuestions];
  }, [questions, mockQuestions]);

  // Filter approved questions based on criteria
  const filteredQuestions = useMemo(() => {
    return approvedQuestions.filter((q) => {
      if (filters.discipline && q.discipline !== filters.discipline)
        return false;
      return true;
    });
  }, [approvedQuestions, filters]);

  // Get unique disciplines for filter dropdown
  const disciplines = useMemo(() => {
    const set = new Set(approvedQuestions.map((q) => q.discipline));
    return [...set].filter(Boolean).sort();
  }, [approvedQuestions]);

  // Get selected questions for preview/export
  const selectedQuestions = useMemo(() => {
    if (selectedQuestionIds.size === 0) {
      // If none selected, use filtered questions up to questionCount
      const shuffled = quizConfig.shuffleQuestions
        ? [...filteredQuestions].sort(() => Math.random() - 0.5)
        : filteredQuestions;
      return shuffled.slice(0, quizConfig.questionCount);
    }
    return filteredQuestions.filter((q) =>
      selectedQuestionIds.has(q.id || q.uniqueId)
    );
  }, [filteredQuestions, selectedQuestionIds, quizConfig]);

  // Toggle question selection
  const toggleQuestion = (q) => {
    const id = q.id || q.uniqueId;
    setSelectedQuestionIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  // Select all / deselect all
  const toggleSelectAll = () => {
    if (selectedQuestionIds.size === filteredQuestions.length) {
      setSelectedQuestionIds(new Set());
    } else {
      setSelectedQuestionIds(
        new Set(filteredQuestions.map((q) => q.id || q.uniqueId))
      );
    }
  };

  // Snapshot questions when starting preview to prevent re-shuffling during quiz
  const handleStartPreview = () => {
    setActiveQuizQuestions([...selectedQuestions]);
    setShowPreview(true);
  };

  if (!isAdmin) {
    return (
      <div className="flex items-center justify-center h-64 text-slate-400">
        <div className="text-center">
          <Icon name="lock" size={48} className="mx-auto mb-4 opacity-50" />
          <p>Admin access required</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-6xl mx-auto">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-white flex items-center gap-3">
          <Icon name="clipboard-list" size={28} />
          Test Configuration
        </h1>
        <div className="flex justify-between items-center mt-2">
          <p className="text-slate-400">
            Configure and preview quizzes from approved questions
          </p>
          <div className="flex gap-2">
            {mockQuestions.length === 0 && (
              <button
                onClick={handleGenerateMockData}
                className="text-xs text-indigo-400 hover:text-indigo-300 border border-indigo-900/50 bg-indigo-900/20 px-3 py-1 rounded flex items-center gap-1"
              >
                <Icon name="wand" size={12} />
                Generate Mock Data
              </button>
            )}
            {mockQuestions.length > 0 && (
              <button
                onClick={handleClearMockData}
                className="text-xs text-red-400 hover:text-red-300 border border-red-900/50 bg-red-900/20 px-3 py-1 rounded"
              >
                Clear Mock Data ({mockQuestions.length})
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left: Quiz Settings */}
        <div className="lg:col-span-1 space-y-6">
          {/* Quiz Config Card */}
          <div className="bg-slate-800 rounded-lg border border-slate-700 p-5">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <Icon name="settings" size={18} />
              Quiz Settings
            </h2>

            {/* Title */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Quiz Title
              </label>
              <input
                type="text"
                value={quizConfig.title}
                onChange={(e) =>
                  setQuizConfig({ ...quizConfig, title: e.target.value })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white focus:border-blue-500 outline-none"
              />
            </div>

            {/* Passing Score */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Passing Score: {quizConfig.passingScore}%
              </label>
              <input
                type="range"
                min="50"
                max="100"
                step="5"
                value={quizConfig.passingScore}
                onChange={(e) =>
                  setQuizConfig({
                    ...quizConfig,
                    passingScore: parseInt(e.target.value),
                  })
                }
                className="w-full"
              />
            </div>

            {/* Time Limit */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Time Limit
              </label>
              <select
                value={quizConfig.timeLimit}
                onChange={(e) =>
                  setQuizConfig({
                    ...quizConfig,
                    timeLimit: parseInt(e.target.value),
                  })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white"
              >
                <option value={10}>10 minutes</option>
                <option value={15}>15 minutes</option>
                <option value={30}>30 minutes</option>
                <option value={45}>45 minutes</option>
                <option value={60}>60 minutes</option>
                <option value={90}>90 minutes</option>
              </select>
            </div>

            {/* Question Count */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Questions: {quizConfig.questionCount}
              </label>
              <input
                type="range"
                min="5"
                max={Math.min(50, filteredQuestions.length || 50)}
                value={Math.min(
                  quizConfig.questionCount,
                  filteredQuestions.length
                )}
                onChange={(e) =>
                  setQuizConfig({
                    ...quizConfig,
                    questionCount: parseInt(e.target.value),
                  })
                }
                className="w-full"
              />
            </div>

            {/* Shuffle */}
            <div className="mb-4">
              <label className="flex items-center gap-2 text-sm text-slate-300 cursor-pointer">
                <input
                  type="checkbox"
                  checked={quizConfig.shuffleQuestions}
                  onChange={(e) =>
                    setQuizConfig({
                      ...quizConfig,
                      shuffleQuestions: e.target.checked,
                    })
                  }
                  className="rounded border-slate-600"
                />
                Shuffle question order
              </label>
            </div>

            {/* Feedback Mode */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Show Feedback
              </label>
              <select
                value={quizConfig.showFeedback}
                onChange={(e) =>
                  setQuizConfig({ ...quizConfig, showFeedback: e.target.value })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white"
              >
                <option value="immediate">After each question</option>
                <option value="end">At quiz end</option>
              </select>
            </div>

            {/* Adaptive Difficulty */}
            <div className="mb-4">
              <label className="flex items-center gap-2 text-sm text-slate-300 cursor-pointer">
                <input
                  type="checkbox"
                  checked={quizConfig.adaptiveDifficulty}
                  onChange={(e) =>
                    setQuizConfig({
                      ...quizConfig,
                      adaptiveDifficulty: e.target.checked,
                    })
                  }
                  className="rounded border-slate-600"
                />
                Adaptive difficulty
              </label>
              <p className="text-xs text-slate-500 mt-1 ml-6">
                Adjusts question difficulty based on performance
              </p>
            </div>
          </div>

          {/* Filter Card */}
          <div className="bg-slate-800 rounded-lg border border-slate-700 p-5">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <Icon name="filter" size={18} />
              Question Filters
            </h2>

            {/* Discipline */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Discipline
              </label>
              <select
                value={filters.discipline}
                onChange={(e) =>
                  setFilters({ ...filters, discipline: e.target.value })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white"
              >
                <option value="">All Disciplines</option>
                {disciplines.map((d) => (
                  <option key={d} value={d}>
                    {d}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="space-y-3">
            <button
