      inviteService.getInviteFromUrl.mockReturnValue("ABC123XYZ789");
      inviteService.validateInvite.mockResolvedValue({
        valid: true,
        role: "admin",
      });

      render(<InviteSignUp onSuccess={mockOnSuccess} />);

