      );
      await userEvent.click(screen.getByRole("button", { name: /validate/i }));

      await waitFor(() => {
        expect(screen.getByText(/valid invite/i)).toBeInTheDocument();
        expect(screen.getByText(/admin/i)).toBeInTheDocument();
