import { useCallback } from "react";
import {
  generateCritiqueSecure as generateCritique,
  generateTagsSecure,
} from "../../services/geminiSecure";
import { QUALITY_THRESHOLDS, TOAST_DURATION } from "../../utils/constants";

/**
 * Hook for handling question critique and feedback loop logic.
 * Extracted from useGeneration to reduce complexity.
 */
export const useQuestionCritique = ({
  effectiveApiKey,
  isApiReady,
  showMessage,
  setStatus,
  setIsProcessing,
  updateQuestionInState,
  updateAllVariantsInState,
}) => {
  /**
   * Generates a critique and suggested rewrite for a question.
   */
  const handleCritique = useCallback(
    async (q) => {
      if (!isApiReady) {
        showMessage(
          "API key is required for critique. Please enter it in the settings panel.",
          TOAST_DURATION.LONG
        );
        return;
      }

      setIsProcessing(true);
      setStatus("Critiquing...");

      try {
        const { score, text, rewrite, improvedScore, changes } =
          await generateCritique(effectiveApiKey, q);

        // Generate tags if question has fewer than 3
        let suggestedTags = Array.isArray(q.tags) ? q.tags : [];
        if (suggestedTags.length < 3) {
          try {
            const questionForTags = rewrite
              ? {
                  question: rewrite.question || q.question,
                  optionA: rewrite.optionA || q.options?.A,
                  optionB: rewrite.optionB || q.options?.B,
                  optionC: rewrite.optionC || q.options?.C,
                  optionD: rewrite.optionD || q.options?.D,
                }
              : {
                  question: q.question,
                  optionA: q.options?.A,
                  optionB: q.options?.B,
                  optionC: q.options?.C,
                  optionD: q.options?.D,
                };

            const newTags = await generateTagsSecure(
              effectiveApiKey,
              questionForTags
            );
            if (newTags && newTags.length > 0) {
              suggestedTags = [
                ...new Set([
                  ...suggestedTags,
                  ...newTags.map((t) => t.replace(/^#/, "")),
                ]),
              ].slice(0, 5);
            }
          } catch (error) {
            console.error("Tag generation failed during critique:", error);
          }
        }

        const updatedRewrite = rewrite
          ? {
              question: rewrite.question || q.question,
              options: {
                A: rewrite.optionA || q.options?.A || "",
                B: rewrite.optionB || q.options?.B || "",
                C: rewrite.optionC || q.options?.C || "",
                D: rewrite.optionD || q.options?.D || "",
              },
              correct: rewrite.correctLetter || q.correct || "A",
              improvements: Array.isArray(changes)
                ? changes
                : changes
                ? [changes]
                : [],
              critiqueScore: improvedScore,
              critiqueText: text,
              tags: suggestedTags,
              changesExplanation:
                rewrite.explanation ||
                "AI-suggested improvements to enhance question quality",
            }
          : null;

        const previousAttempts = q.critiqueAttempts || 0;
        const newAttemptCount = previousAttempts + 1;
        const PASSING_SCORE = QUALITY_THRESHOLDS.PASS;
        const MAX_ATTEMPTS = 3;

        const critiqueUpdate = (item) => ({
          ...item,
          critique: text,
          critiqueScore: score,
          improvedScore: improvedScore,
          suggestedRewrite: updatedRewrite,
          rewriteChanges: changes,
          critiqueAttempts: newAttemptCount,
          ...(score < PASSING_SCORE && newAttemptCount >= MAX_ATTEMPTS
            ? {
                status: "rejected",
                rejectionReason: "low_score_after_retries",
                rejectedAt: new Date().toISOString(),
              }
            : {}),
        });

        if (q.uniqueId) {
          updateAllVariantsInState(q.uniqueId, critiqueUpdate);
          updateQuestionInState(q.id, critiqueUpdate);
        } else {
          updateQuestionInState(q.id, critiqueUpdate);
        }

        if (score < PASSING_SCORE && newAttemptCount >= MAX_ATTEMPTS) {
          showMessage(
            `\u26D4 Auto-rejected: Score ${score}/100 after ${newAttemptCount} attempts. Quality too low.`,
            TOAST_DURATION.EXTENDED
          );
        } else {
          showMessage(
            `Critique Ready! Score: ${score}/100`,
            TOAST_DURATION.MEDIUM
          );
        }
      } catch (e) {
        console.error("Critique failed:", e);
        setStatus("Fail");
        showMessage(`Critique Failed: ${e.message}`, TOAST_DURATION.LONG);
      } finally {
        setIsProcessing(false);
      }
    },
    [
      isApiReady,
      showMessage,
      effectiveApiKey,
      updateQuestionInState,
      updateAllVariantsInState,
      setStatus,
      setIsProcessing,
    ]
  );

  /**
   * Applies the suggested rewrite to the question.
   */
  const handleApplyRewrite = useCallback(
    (q) => {
      if (!q.suggestedRewrite) return;

      const updatedQ = {
        ...q,
        question: q.suggestedRewrite.question,
        options: q.suggestedRewrite.options,
        correct: q.suggestedRewrite.correct,
        suggestedRewrite: null,
        rewriteChanges: null,
        critique: null,
        critiqueScore: null,
        humanVerified: false,
        status: "pending",
        rejectionReason: null,
      };

      updateQuestionInState(q.id, () => updatedQ);
      showMessage("Γ£ô Applied! Re-critiquing...", TOAST_DURATION.SHORT);

      // Re-trigger critique after a short delay
      setTimeout(() => {
        handleCritique({ ...updatedQ, id: q.id });
      }, 300);
    },
    [updateQuestionInState, showMessage, handleCritique]
  );

  return {
    handleCritique,
    handleApplyRewrite,
  };
};

import { useState, useCallback } from "react";
import {
  generateContentSecure as generateContent,
  generateCritiqueSecure as generateCritique,
  generateTagsSecure,
} from "../../services/geminiSecure";
import { constructSystemPrompt } from "../../services/promptBuilder";
import { parseQuestions, convertMCtoTF } from "../../utils/parserUtils";
import { validateQuestion } from "../../utils/questionValidator";
import { analyzeRequest, estimateTokens } from "../../utils/tokenCounter";
import { logGeneration, logQuestion } from "../../utils/analyticsStore";
import { validateGeneration } from "../../utils/quotaEnforcement";
import {
  TOAST_DURATION,
  GENERATION_LIMITS,
  CONTEXT_LIMITS,
  QUALITY_THRESHOLDS,
} from "../../utils/constants";
import {
  calculateCoverageGaps,
  enrichGeneratedQuestions,
  filterForbiddenSources,
  verifyAndProcessQuestions,
} from "../../utils/generationUtils";

/**
 * Hook to handle question generation, explanation, and variation.
 */
export const useQuestionGenerator = ({
  config,
  effectiveApiKey,
  isApiReady,
  isTargetMet,
  allQuestionsMap,
  showMessage,
  setStatus,
  setShowNameModal,
  setShowApiError,
  setShowHistory,
  getFileContext,
  checkAndStoreQuestions,
  addQuestionsToState,
  updateQuestionInState,
  setIsProcessing,
}) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAutoCritique = useCallback(
    async (questions) => {
      setStatus("Auto-critiquing...");
      showMessage(
        `Running AI critique on ${questions.length} questions...`,
        TOAST_DURATION.MEDIUM
      );

      const critiqueQuestion = async (question) => {
        try {
          const { score, text, rewrite, changes } = await generateCritique(
            effectiveApiKey,
            question
          );

          let suggestedTags = question.tags || [];
          if (
            suggestedTags.length < GENERATION_LIMITS.MIN_TAGS_PER_QUESTION &&
            rewrite
          ) {
            const improvedQuestion = {
              question: rewrite.question || question.question,
              optionA: rewrite.optionA || question.options?.A,
              optionB: rewrite.optionB || question.options?.B,
              optionC: rewrite.optionC || question.options?.C,
              optionD: rewrite.optionD || question.options?.D,
            };
            const newTags = await generateTagsSecure(
              effectiveApiKey,
              improvedQuestion
            );
            if (newTags) {
              suggestedTags = [
                ...new Set([
                  ...suggestedTags,
                  ...newTags.map((t) => t.replace(/^#/, "")),
                ]),
              ];
            }
          }

          updateQuestionInState(question.id, (item) => ({
            ...item,
            critique: text,
            critiqueScore: score,
            suggestedRewrite: rewrite
              ? { ...rewrite, tags: suggestedTags }
              : null,
            rewriteChanges: changes,
          }));
          return score;
        } catch {
          return null;
        }
      };

      const batchSize = GENERATION_LIMITS.BATCH_SIZE_PARALLEL_CRITIQUE;
      const scores = [];
      for (let i = 0; i < questions.length; i += batchSize) {
        const batch = questions.slice(i, i + batchSize);
        const batchScores = await Promise.all(batch.map(critiqueQuestion));
        scores.push(...batchScores.filter((s) => s !== null));
      }

      const avgScore =
        scores.length > 0
          ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length)
          : 0;

      const highScoreCount = scores.filter(
        (s) => s >= QUALITY_THRESHOLDS.PASS
      ).length;
      const lowScoreCount = scores.filter(
        (s) => s < QUALITY_THRESHOLDS.MEDIOCRE
      ).length;

      if (lowScoreCount > 0) {
        showMessage(
          `Critique complete! Avg: ${avgScore}/100. ΓÜá∩╕Å ${lowScoreCount} need improvement.`,
          TOAST_DURATION.EXTENDED
        );
      } else {
        showMessage(
          `Critique complete! Avg: ${avgScore}/100. ${highScoreCount} ready to accept!`,
          TOAST_DURATION.LONG
        );
      }
      setStatus("");
    },
    [effectiveApiKey, setStatus, showMessage, updateQuestionInState]
  );

  const handlePerformGeneration = useCallback(
    async ({
      effectiveApiKey,
      systemPrompt,
      userPrompt,
      effectiveType,
      startTime,
      tokenAnalysis,
    }) => {
      const text = await generateContent(
        effectiveApiKey,
        systemPrompt,
        userPrompt,
        setStatus,
        config.temperature,
        config.model
      );
      const duration = Date.now() - startTime;

      const groundingSources = window.__lastGroundingSources || [];
      const groundedUrls = new Set(
        groundingSources.map((s) => s.url.toLowerCase())
      );

      let genQuestions = parseQuestions(text);
      if (genQuestions.length === 0) {
        throw new Error("Failed to parse questions.");
      }

      genQuestions = filterForbiddenSources(genQuestions);

      const expectedType =
        effectiveType === "T/F" || effectiveType === "True/False"
          ? "True/False"
          : "Multiple Choice";

      genQuestions = verifyAndProcessQuestions(
        genQuestions,
        { groundedUrls, expectedType, config },
        convertMCtoTF
      );

      window.__lastGroundingSources = [];

      const valQuestions = [];
      let rejCount = 0;

      genQuestions.forEach((q) => {
        const validation = validateQuestion(q);
        if (validation.isCriticalFailure) {
          rejCount++;
        } else {
          valQuestions.push({ ...q, _validation: validation });
        }
      });

      if (rejCount > 0) {
        showMessage(
          `Auto-rejected ${rejCount} questions with invalid metadata.`,
          TOAST_DURATION.EXTENDED
        );
      }

      const enriched = enrichGeneratedQuestions(valQuestions, {
        config,
        duration,
        costPerQuestion:
          valQuestions.length > 0
            ? tokenAnalysis.cost.estimated / valQuestions.length
            : 0,
        groundingSources,
        expectedType,
        requestedDifficulty: config.difficulty,
      });

      const uniqueQs = await checkAndStoreQuestions(enriched);

      const avgQual =
        uniqueQs.reduce((sum, q) => sum + (q.qualityScore || 0), 0) /
        (uniqueQs.length || 1);

      const genId = logGeneration({
        discipline: config.discipline,
        difficulty: config.difficulty,
        batchSize: config.batchSize,
        tokensUsed: {
          input: tokenAnalysis.input.total,
          output: estimateTokens(text),
        },
        duration,
        questionsGenerated: uniqueQs.length,
        averageQuality: Math.round(avgQual),
        success: true,
        model: config.model || "gemini-2.0-flash",
        estimatedCost: tokenAnalysis.cost.estimated,
      });

      uniqueQs.forEach((q) => {
        logQuestion({
          id: q.id,
          generationId: genId,
          created: q.dateAdded,
          status: "pending",
          qualityScore: q.qualityScore,
          discipline: q.discipline,
          difficulty: q.difficulty,
          type: q.type,
          questionText: q.question,
        });
      });

      addQuestionsToState(uniqueQs, false);
      return uniqueQs;
    },
    [
      config,
      setStatus,
      checkAndStoreQuestions,
      addQuestionsToState,
      showMessage,
    ]
  );

  const prepareGenerationContext = useCallback(async () => {
    // QUOTA ENFORCEMENT
    const allQuestions = Array.from(allQuestionsMap.values()).flat();
    const quotaCheck = validateGeneration(
      config.discipline,
      config.difficulty,
      config.batchSize,
      allQuestions,
      config.type || "Multiple Choice"
    );

    if (!quotaCheck.allowed) {
      showMessage(quotaCheck.reason, TOAST_DURATION.EXTENDED);
      return null;
    }

    let effectiveBatchSize = config.batchSize;
    if (quotaCheck.warning && quotaCheck.maxAllowed < config.batchSize) {
      effectiveBatchSize = quotaCheck.maxAllowed;
      showMessage(
        `Batch size reduced to ${quotaCheck.maxAllowed} (quota limit). ${quotaCheck.reason}`,
        TOAST_DURATION.EXTENDED
      );
    }

    const effectiveType =
      quotaCheck.forceType || config.type || "Multiple Choice";

    setIsGenerating(true);
    setShowHistory(false);
    setStatus("Drafting Scenarios...");
    const startTime = Date.now();

    // Collect rejected examples
    const rejectedExamples = Array.from(allQuestionsMap.values())
      .flat()
      .filter(
        (q) =>
          q.status === "rejected" &&
          q.rejectionReason &&
          q.discipline === config.discipline
      )
      .slice(-GENERATION_LIMITS.REJECTED_EXAMPLES_COUNT);

    // AUTO-DETECT COVERAGE GAPS
    const { TAGS_BY_DISCIPLINE } = await import("../../utils/tagTaxonomy");
    const availableTags = TAGS_BY_DISCIPLINE[config.discipline] || [];
    const coverageGaps = calculateCoverageGaps(
      config.discipline,
      availableTags,
      allQuestions
    );

    const adjustedConfig = {
      ...config,
      type: effectiveType,
      batchSize: effectiveBatchSize,
    };
    const systemPrompt = constructSystemPrompt(
      adjustedConfig,
      getFileContext(),
      rejectedExamples,
      coverageGaps
    );

    let typeInstruction = "";
    if (effectiveType === "True/False" || effectiveType === "T/F") {
      typeInstruction =
        " Generate ONLY True/False questions (no Multiple Choice).";
    } else if (effectiveType === "Multiple Choice" || effectiveType === "MC") {
      typeInstruction =
        " Generate ONLY Multiple Choice questions (no True/False).";
    }
    const userPrompt = `Generate ${effectiveBatchSize} scenario-based questions for ${config.discipline} in ${config.language}. Focus: ${config.difficulty}.${typeInstruction} Ensure links work for UE 5.7 or latest available.`;

    const tokenAnalysis = analyzeRequest(
      systemPrompt,
      userPrompt,
      CONTEXT_LIMITS.MAX_TOKENS,
      config.model || "gemini-2.0-flash"
    );

    return {
      systemPrompt,
      userPrompt,
      effectiveType,
      startTime,
      tokenAnalysis,
    };
  }, [
    config,
    allQuestionsMap,
    getFileContext,
    showMessage,
    setStatus,
    setIsGenerating,
    setShowHistory,
  ]);

  const handleGenerate = useCallback(async () => {
    if (!config.creatorName) {
      showMessage(
        "Please enter your Creator Name to start generating.",
        TOAST_DURATION.LONG
      );
      setShowNameModal(true);
      return;
    }
    if (!isApiReady) {
      setShowApiError(true);
      showMessage(
        "API key is required. Please enter it in Settings.",
        TOAST_DURATION.LONG
      );
      return;
    }

