    },
    [
      config,
      effectiveApiKey,
      isApiReady,
      setStatus,
      showMessage,
      addQuestionsToState,
      checkAndStoreQuestions,
      setIsProcessing,
      getFileContext,
    ]
  );

  return {
    isGenerating,
    handleGenerate,
    handleExplain,
    handleVariate,
    handlePerformGeneration,
    handleAutoCritique,
  };
};

import { useState, useCallback } from "react";
import { generateContentSecure as generateContent } from "../../services/geminiSecure";
import { parseQuestions } from "../../utils/questionHelpers";
import { TOAST_DURATION } from "../../utils/constants";
import {
  getTranslationSystemPrompt,
  getTranslationUserPrompt,
} from "../../services/prompts/translationPrompts";

/**
 * Hook for handling question translation logic.
 * Extracted from useGeneration to reduce complexity.
 */
export const useQuestionTranslation = ({
  effectiveApiKey,
  isApiReady,
  showMessage,
  setStatus,
  setIsProcessing,
  checkAndStoreQuestions,
  addQuestionsToState,
  updateQuestionInState,
  handleLanguageSwitch,
  translationMap,
  allQuestionsMap,
  setShowHistory,
}) => {
  const [translationProgress, setTranslationProgress] = useState(0);

  /**
   * Translates a single question to a target language.
   */
  const handleTranslateSingle = useCallback(
    async (q, targetLang) => {
      if (!isApiReady) {
        showMessage(
          "API key is required for translation. Please enter it in the settings panel.",
          TOAST_DURATION.LONG
        );
        return;
      }

      setIsProcessing(true);
      setStatus(`Translating question to ${targetLang}...`);

      const systemPrompt = getTranslationSystemPrompt(q.language, targetLang);
      const userPrompt = getTranslationUserPrompt(q);

      try {
        const text = await generateContent(
          effectiveApiKey,
          systemPrompt,
          userPrompt,
          setStatus
        );

        // Attempt to parse JSON response
        let translatedData = null;
        try {
          const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
          translatedData = JSON.parse(cleanText);
        } catch (e) {
          console.warn("JSON parse failed, trying parseQuestions fallback", e);
        }

        const translatedQs = translatedData
          ? parseQuestions(JSON.stringify(translatedData))
          : parseQuestions(text);

        if (translatedQs.length > 0) {
          const tq = translatedQs[0];

          // Ensure original has uniqueId
          if (!q.uniqueId) {
            const newUniqueId = crypto.randomUUID();
            const updatedOriginal = {
              ...q,
              uniqueId: newUniqueId,
              language: q.language || "English",
            };

            updateQuestionInState(q.id, () => updatedOriginal);
            await checkAndStoreQuestions([updatedOriginal]);
            q = updatedOriginal;
          }

          const translatedVariant = {
            ...tq,
            id: Date.now(),
            uniqueId: q.uniqueId,
            discipline: q.discipline,
            type: q.type,
            difficulty: q.difficulty,
            language: targetLang,
            status: q.status,
            dateAdded: new Date().toISOString(),
            tags: q.tags,
            critiqueScore: q.critiqueScore,
            sourceUrl: q.sourceUrl,
            translatedAt: new Date().toISOString(),
            translatedFrom: q.language || "English",
          };

          addQuestionsToState([translatedVariant], false);
          await checkAndStoreQuestions([translatedVariant]);
          handleLanguageSwitch(targetLang);

          showMessage(`Γ£à Translated to ${targetLang}`, TOAST_DURATION.MEDIUM);
        } else {
          throw new Error("Parser returned no questions from translation.");
        }
      } catch (e) {
        console.error("Translation error:", e);
        setStatus("Translation Failed");
        showMessage(`Translation Failed: ${e.message}`, TOAST_DURATION.LONG);
      } finally {
        setIsProcessing(false);
      }
    },
    [
      isApiReady,
      showMessage,
      effectiveApiKey,
      setStatus,
      setIsProcessing,
      checkAndStoreQuestions,
      addQuestionsToState,
      updateQuestionInState,
      handleLanguageSwitch,
    ]
  );

  /**
   * Translates all accepted English questions to common target languages.
   */
  const handleBulkTranslateMissing = useCallback(async () => {
    if (!isApiReady) {
      showMessage(
        "API key is required for bulk translation. Please enter it in the settings panel.",
        TOAST_DURATION.LONG
      );
      return;
    }

    setIsProcessing(true);
    setShowHistory(false);

    const targetLangs = ["Chinese (Simplified)", "Japanese", "Korean"];
    const translationQueue = [];

    const baseQuestions = Array.from(allQuestionsMap.values()).map(
      (variants) => {
        const list = Array.isArray(variants) ? variants : [variants];
        return (
          list.find((v) => (v.language || "English") === "English") || list[0]
        );
      }
    );

    baseQuestions.forEach((q) => {
      const existingLangs = translationMap.get(q.uniqueId) || new Set();

      targetLangs.forEach((targetLang) => {
        if (
          q.status === "accepted" &&
          (q.language || "English") === "English" &&
          q.sourceUrl &&
          !q.invalidUrl &&
          !existingLangs.has(targetLang)
        ) {
          translationQueue.push({ question: q, targetLang });
        }
      });
    });

    if (translationQueue.length === 0) {
      showMessage(
        "All CN, JP, and KR translations already exist for all accepted questions.",
        TOAST_DURATION.LONG
      );
      setIsProcessing(false);
      return;
    }

    showMessage(
      `Found ${translationQueue.length} missing translations. Starting bulk generation...`
    );
    let generatedCount = 0;
    const totalQueueSize = translationQueue.length;

    const ID_SUBSTRING_LENGTH = 4;
    for (const { question: q, targetLang } of translationQueue) {
      const systemPrompt = getTranslationSystemPrompt(q.language, targetLang);
      const userPrompt = getTranslationUserPrompt(q);

      try {
        setStatus(
          `Translating: ${q.uniqueId.substring(
            0,
            ID_SUBSTRING_LENGTH
          )} -> ${targetLang}...`
        );
        const text = await generateContent(
          effectiveApiKey,
          systemPrompt,
          userPrompt,
          setStatus
        );

        let translatedData = null;
        try {
          const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
          translatedData = JSON.parse(cleanText);
        } catch {
          // ignore
        }

        const translatedQs = translatedData
          ? parseQuestions(JSON.stringify(translatedData))
          : parseQuestions(text);

        if (translatedQs.length > 0) {
          const tq = translatedQs[0];
          const newQuestion = {
            ...tq,
            id: Date.now() + generatedCount,
            uniqueId: q.uniqueId,
            discipline: q.discipline,
            type: q.type,
            difficulty: q.difficulty,
            language: targetLang,
            status: "pending",
            dateAdded: new Date().toISOString(),
          };

          await checkAndStoreQuestions([newQuestion]);
          addQuestionsToState([newQuestion], false);
          generatedCount++;
        }
      } catch (e) {
        console.error(
          `Failed to generate translation for ${q.uniqueId} to ${targetLang}:`,
          e
        );
      }

      const PERCENT_CONVERSION = 100;
      setTranslationProgress(
        Math.floor((generatedCount / totalQueueSize) * PERCENT_CONVERSION)
      );
    }

    showMessage(
      `Bulk translation complete! Generated ${generatedCount} new translations.`,
      TOAST_DURATION.EXTENDED
    );
    setIsProcessing(false);
  }, [
    isApiReady,
    showMessage,
    allQuestionsMap,
    translationMap,
    effectiveApiKey,
    checkAndStoreQuestions,
    addQuestionsToState,
    setStatus,
    setShowHistory,
    setIsProcessing,
  ]);

  return {
    handleTranslateSingle,
    handleBulkTranslateMissing,
    translationProgress,
    setTranslationProgress,
  };
};

/**
 * Intelligently converts a Multiple Choice question to True/False format.
 * Creates a statement from the question + correct answer, randomly makes it TRUE or FALSE.
 * 
 * @param {Object} mcQuestion - The multiple choice question object
 * @param {string} mcQuestion.question - The question text
 * @param {Object} mcQuestion.options - The answer options (A, B, C, D)
 * @param {string} mcQuestion.correct - The correct answer letter
 * @param {string} difficulty - The difficulty level to assign
 * @returns {Object} The converted True/False question
 */
export const convertMCtoTF = (mcQuestion, difficulty) => {
    const correctAnswerText = mcQuestion.options[mcQuestion.correct];
    const wrongAnswers = Object.entries(mcQuestion.options)
        .filter(([key, val]) => key !== mcQuestion.correct && val && val.trim())
        .map(([, val]) => val);

    // Check if the original question is already effectively True/False
    const lowerCorrect = correctAnswerText.trim().toLowerCase().replace(/[.,!]$/, '');
    const isBooleanAnswer = ['true', 'false', 'yes', 'no'].includes(lowerCorrect);

    let newStatement = mcQuestion.question.trim().replace(/\?$/, '');
    let makeItTrue = true; // Default
    let targetAnswer = correctAnswerText;

    if (isBooleanAnswer) {
        // PRESERVE MODE: If original answer is True/False, we keep the statement as is.
        // We cannot easily flip the truthiness of a statement without complex NLP (e.g. adding "not").
        // So we force the new question to match the original truthiness.

        // If original correct was "TRUE" or "YES" -> New Correct is A (TRUE)
        if (['true', 'yes'].includes(lowerCorrect)) {
            makeItTrue = true;
        }
        // If original correct was "FALSE" or "NO" -> New Correct is B (FALSE)
        else {
            makeItTrue = false;
        }

        // Statement is just the original question text (which is likely a statement)
        // newStatement remains the same
    } else {
        // STANDARD MODE: Randomly decide if this will be a TRUE or FALSE question (50/50)
        makeItTrue = Math.random() > 0.5;
        targetAnswer = makeItTrue ? correctAnswerText : wrongAnswers[Math.floor(Math.random() * wrongAnswers.length)] || 'incorrect';

        // 1. Handle "Can you..." -> "You can [stem] [answer]"
        if (/^Can you/i.test(newStatement)) {
            const stem = newStatement.replace(/^Can you\s+/i, '');
            newStatement = `You can ${stem} ${targetAnswer}`;
        }
        // 2. Handle "Is..." -> "[Subject] is [Answer]"
        else if (/^Is\s+/i.test(newStatement)) {
            const stem = newStatement.replace(/^Is\s+/i, '');
            newStatement = `${stem} is ${targetAnswer}`;
        }
        // 3. Handle "What/Which..." -> "[Stem] is [Answer]"
        else {
            // Check for WH- words
            const isWhQuestion = /^(What|Which|How|Where|When|Why)\s+/i.test(newStatement);

            if (isWhQuestion) {
                const stem = newStatement
                    .replace(/^(What|Which|How|Where|When|Why)\s+(is|are|does|do|can|should|would)\s+/i, '')
                    .trim();
                newStatement = `${stem} is ${targetAnswer}`;
            } else {
                // Fallback for other structures: append answer
                newStatement = `${newStatement} is ${targetAnswer}`;
            }
        }
    }

    // Cleanup: Remove double spaces, capitalize, add period
    newStatement = newStatement.replace(/\s+/g, ' ').trim();
    newStatement = newStatement.charAt(0).toUpperCase() + newStatement.slice(1);
    if (!newStatement.endsWith('.')) newStatement += '.';

    return {
        ...mcQuestion,
        type: 'True/False',
        difficulty: difficulty,
        question: newStatement,
        options: { A: 'TRUE', B: 'FALSE', C: '', D: '' },
        correct: makeItTrue ? 'A' : 'B',
        originalMC: mcQuestion.question // Keep original for reference
    };
};

import { useState, useEffect, useRef } from "react";
import { getSecureItem, setSecureItem } from "../utils/secureStorage";

export const useAppConfig = () => {
  // Application mode: 'landing' (home screen), 'create' (generation mode), 'review' (review mode), 'database' (view all)
  // Application mode: 'landing' (home screen), 'create' (generation mode), 'review' (review mode), 'database' (view all)
  const [appMode, setAppMode] = useState(() => {
    // SECURITY: Get mode from localStorage if available to prevent flash-resets on hydrate
    if (typeof window === "undefined") return "landing";
    return localStorage.getItem("ue5_app_mode") || "landing";
  });

  // Check if running in internal Canvas environment (has auto-injected API key)
  const isInternalEnvironment =
    typeof window !== "undefined" && typeof window.__app_id !== "undefined";

  // Authentication status - always ready for local/Sheets operations
  const isAuthReady = true;

  // SECURITY WARNING: Storing API keys in localStorage is insecure!
  // This is a temporary solution. For production:
  // 1. Move API calls to a backend proxy server
  // 2. Never expose API keys in client-side code
  // 3. Use server-side authentication with the Gemini API

  // Main application configuration (persisted to localStorage)
  const [config, setConfig] = useState(() => {
    const saved = getSecureItem("ue5_gen_config");
    const defaults = {
      discipline: "Tech Art",
      batchSize: "6",
      difficulty: "Beginner",
      type: "Multiple Choice", // Explicit type selection (no Balanced mode)
      language: "English",
      creatorName: "",
      reviewerName: "",
      apiKey: "",
      sheetUrl:
        "https://script.google.com/a/macros/epicgames.com/s/AKfycbxssaKhw3pOWkC9sPJE_6oMZuG66JYCgeEQFEHh010Q90wlHqH64oiVhFjE1JQkSTV6/exec",
      model: "gemini-2.0-flash",
      tags: [], // Selected sub-topic tags
    };

    const initialConfig = saved ? { ...defaults, ...saved } : defaults;

    // Ensure all required fields have default values
    initialConfig.creatorName = initialConfig.creatorName || "";
    initialConfig.reviewerName = initialConfig.reviewerName || "";
    initialConfig.apiKey = initialConfig.apiKey || "";
    initialConfig.sheetUrl = initialConfig.sheetUrl || defaults.sheetUrl;

    return initialConfig;
  });

  // API key status computed values
  // Cloud Functions are available when user is authenticated (checked via Firebase Auth in App.jsx)
  // We'll accept auth status as a prop to determine if Cloud Functions are available
  const hasClientKey = config.apiKey && config.apiKey.length > 5;
  const isApiReady = isInternalEnvironment || hasClientKey || isAuthReady; // Cloud Functions count as "ready"
  const effectiveApiKey = isInternalEnvironment ? "" : config.apiKey;

  // Status priority: Internal > Cloud Functions > Client Key > Not Set
  let apiKeyStatus;
  if (isInternalEnvironment) {
    apiKeyStatus = "Auto-Injected";
  } else if (hasClientKey) {
    apiKeyStatus = "Loaded";
  } else if (isAuthReady) {
    apiKeyStatus = "Cloud Functions"; // User is authenticated, can use server-side API
  } else {
    apiKeyStatus = "Not Set";
  }

  // DEBUG: Uncomment to debug API status (removed to reduce console spam)
  // console.log("≡ƒöì [useAppConfig] API Status Debug:", {
  //   isInternalEnvironment,
  //   hasClientKey,
  //   isAuthReady,
  //   isApiReady,
  //   apiKeyStatus,
  // });

  // UI States
  const [showNameModal, setShowNameModal] = useState(false);
  const [showGenSettings, setShowGenSettings] = useState(true);
  const [showApiError, setShowApiError] = useState(false);
  const [batchSizeWarning, setBatchSizeWarning] = useState("");
  const [showSettings, setShowSettings] = useState(false);
  const [showApiKey, setShowApiKey] = useState(false);

  // Track if this is the initial mount
  const hasInitialized = useRef(false);

  // Effects
  useEffect(() => {
    // Skip the first render to allow localStorage to hydrate
    if (!hasInitialized.current) {
      hasInitialized.current = true;
      // Only show modal if name is truly empty after initial load
      const savedConfig = getSecureItem("ue5_gen_config");
      if (!savedConfig?.creatorName && !config.creatorName) {
        setShowNameModal(true);
      }
      return;
    }
    // After initial mount, show modal if name becomes empty
    if (!config.creatorName) setShowNameModal(true);
  }, [config.creatorName]);
  useEffect(() => {
    setSecureItem("ue5_gen_config", config);
  }, [config]);

  // Persist appMode to localStorage independently for faster restoration
  useEffect(() => {
    if (typeof window !== "undefined") {
      localStorage.setItem("ue5_app_mode", appMode);
    }
  }, [appMode]);

  // Handlers
  // pendingNavigationUniqueId tracks the uniqueId to navigate to after language switch
  const [pendingNavigationUniqueId, setPendingNavigationUniqueId] =
    useState(null);

  const handleLanguageSwitch = (lang, uniqueId = null) => {
    console.log(
      "≡ƒîì [handleLanguageSwitch] Switching global language filter to:",
