    pendingNavigationUniqueId,
    setPendingNavigationUniqueId,
  };
};

/**
 * useAuth Hook
 *
 * Manages authentication state, registration, custom tags, and compliance modals:
 * - Firebase authentication state
 * - User registration status (invite system)
 * - Admin status from Firestore (server-side only - security fix V-002)
 * - Custom tags from Firestore
 * - Token usage tracking
 * - Age verification and terms acceptance modals
 */
import { useState, useEffect } from "react";
import { onAuthStateChanged } from "firebase/auth";
import { auth, getCustomTags, saveCustomTags } from "../services/firebase";
import { getTokenUsage } from "../utils/analyticsStore";
import {
  checkUserRegistration,
  setupInitialAdmin,
} from "../services/inviteService";

// SECURITY FIX V-002: Removed client-side FALLBACK_ADMIN_EMAILS
// Admin detection now happens entirely server-side via checkUserRegistration()
// and setupInitialAdmin() Cloud Functions

/**
 * Custom hook for managing authentication and compliance state.
 *
 * @param {Function} showMessage - Function to display toast messages
 * @returns {Object} Auth state, custom tags, compliance state and handlers
 */
export function useAuth(showMessage) {
  // ========================================================================
  // STATE
  // ========================================================================
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [userRole, setUserRole] = useState("user");
  const [isRegistered, setIsRegistered] = useState(false);
  const [registrationLoading, setRegistrationLoading] = useState(true);
  const [customTags, setCustomTags] = useState({});
  const [tokenUsage, setTokenUsage] = useState(() => getTokenUsage());

  // Compliance modals
  const [showTerms, setShowTerms] = useState(false);
  const [showAgeGate, setShowAgeGate] = useState(false);
  const [termsAccepted, setTermsAccepted] = useState(false);

  // ========================================================================
  // EFFECTS
  // ========================================================================

  // Listen for auth state changes and check registration
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);

      if (currentUser) {
        // Check registration status via Cloud Function (server-side admin detection)
        setRegistrationLoading(true);
        try {
          let regStatus = await checkUserRegistration();

          // If not registered, attempt server-side admin setup
          // Server validates email whitelist - client never sees the whitelist
          if (!regStatus.registered) {
            try {
              const adminResult = await setupInitialAdmin();
              if (adminResult.success) {
                console.log("Γ£à Server-side admin setup successful");
                regStatus = {
                  registered: true,
                  role: adminResult.role || "admin",
                };
              }
            } catch (setupError) {
              // setupInitialAdmin throws if email not whitelisted - this is expected
              console.log("Γä╣∩╕Å Not a whitelisted admin email");
            }
          }

          setIsRegistered(regStatus.registered);
          setUserRole(regStatus.role || "user");
          setIsAdmin(regStatus.role === "admin");
        } catch (error) {
          console.error("Failed to check registration:", error);
          // SECURITY: On error, default to no access (fail closed)
          setIsAdmin(false);
          setIsRegistered(false);
          setUserRole("user");
        } finally {
          setRegistrationLoading(false);
        }

        // Load custom tags from Firestore
        try {
          const tags = await getCustomTags();
          setCustomTags(tags);
        } catch (error) {
          console.error("Failed to load custom tags:", error);
        }
      } else {
        setIsAdmin(false);
        setIsRegistered(false);
        setUserRole("user");
        setRegistrationLoading(false);
      }
    });
    return () => unsubscribe();
  }, []);

  // Refresh token usage periodically
  useEffect(() => {
    const interval = setInterval(() => setTokenUsage(getTokenUsage()), 5000);
    return () => clearInterval(interval);
  }, []);

  // Check compliance status on app load
  useEffect(() => {
    const ageVerified = localStorage.getItem("ue5_age_verified");
    const termsAcceptedStorage = localStorage.getItem("ue5_terms_accepted");

    if (!ageVerified) {
      setShowAgeGate(true);
    } else if (!termsAcceptedStorage) {
      setShowTerms(true);
    } else {
      setTermsAccepted(true);
    }
  }, []);

  // ========================================================================
  // HANDLERS
  // ========================================================================

  /**
   * Save custom tags to Firestore.
   *
   * @param {Object} newCustomTags - New custom tags object
   */
  const handleSaveCustomTags = async (newCustomTags) => {
    try {
      await saveCustomTags(newCustomTags);
      setCustomTags(newCustomTags);
      showMessage("Custom tags saved!", 2000);
    } catch (error) {
      console.error("Failed to save custom tags:", error);
      showMessage("Failed to save tags", 3000);
    }
  };

  /**
   * Mark user as registered (called after successful invite consumption)
   */
  const markAsRegistered = (role = "user") => {
    setIsRegistered(true);
    setUserRole(role);
    if (role === "admin") {
      setIsAdmin(true);
    }
  };

  // ========================================================================
  // RETURN
  // ========================================================================
  return {
    // Auth state
    user,
    authLoading,
    isAdmin,
    userRole,

    // Registration state (invite system)
    isRegistered,
    registrationLoading,
    markAsRegistered,

    // Custom tags
    customTags,
    setCustomTags,
    handleSaveCustomTags,

    // Token usage
    tokenUsage,

    // Compliance
    showTerms,
    setShowTerms,
    showAgeGate,
    setShowAgeGate,
    termsAccepted,
    setTermsAccepted,
  };
}

import { useEffect, useCallback, useRef } from 'react';

/**
 * Hook for auto-saving data to localStorage
 * @param {string} key - localStorage key
 * @param {any} data - Data to save
 * @param {number} interval - Save interval in milliseconds (default: 10000)
 * @param {boolean} enabled - Whether auto-save is enabled
 */
export const useAutoSave = (key, data, interval = 10000, enabled = true) => {
    const intervalRef = useRef(null);
    const lastSaveRef = useRef(null);

    const saveData = useCallback(() => {
        if (!enabled || !data) return;

        try {
            const savePayload = {
                data,
                timestamp: Date.now(),
                version: '1.0'
            };
            localStorage.setItem(key, JSON.stringify(savePayload));
            lastSaveRef.current = Date.now();
            console.log(`Auto-saved: ${key}`);
        } catch (error) {
            console.error('Auto-save failed:', error);
        }
    }, [key, data, enabled]);

    const loadData = useCallback(() => {
        try {
            const saved = localStorage.getItem(key);
            if (saved) {
                const { data: savedData, timestamp } = JSON.parse(saved);
                return { data: savedData, timestamp };
            }
        } catch (error) {
            console.error('Failed to load saved data:', error);
        }
        return null;
    }, [key]);

    const clearSaved = useCallback(() => {
        localStorage.removeItem(key);
        lastSaveRef.current = null;
        console.log(`Cleared saved data: ${key}`);
    }, [key]);

    const hasSavedData = useCallback(() => {
        return localStorage.getItem(key) !== null;
    }, [key]);

    // Auto-save effect
    useEffect(() => {
        if (enabled && data) {
            // Initial save
            saveData();

            // Set up interval
            intervalRef.current = setInterval(saveData, interval);

            return () => {
                if (intervalRef.current) {
                    clearInterval(intervalRef.current);
                }
            };
        }
    }, [enabled, data, interval, saveData]);

    return {
        saveData,
        loadData,
        clearSaved,
        hasSavedData,
        lastSaveTime: lastSaveRef.current
    };
};

export default useAutoSave;

import { useState, useEffect, useCallback } from "react";
import { getQuestionsFromFirestore } from "../services/firebase";

/**
 * useCrashRecovery - Detects potential data loss from crashes and offers to restore from Firestore
 *
 * Detection heuristics:
 * 1. LocalStorage has fewer questions than expected from last session
 * 2. Firestore has questions but localStorage is empty
 * 3. Session flag indicates unexpected termination
 */
export const useCrashRecovery = (
  localQuestions,
  addQuestionsToState,
  showMessage
) => {
  const [showRecoveryPrompt, setShowRecoveryPrompt] = useState(false);
  const [recoveryData, setRecoveryData] = useState(null);
  const [isRecovering, setIsRecovering] = useState(false);

  // Check for crash on mount
  useEffect(() => {
    const checkForCrash = async () => {
      try {
        // Skip if user already dismissed or recovered this session
        const alreadyHandled = sessionStorage.getItem("ue5_recovery_handled");
        const permanentlyDismissed = localStorage.getItem(
          "ue5_recovery_dismissed"
        );

        if (alreadyHandled === "true" || permanentlyDismissed === "true") {
          console.log(
            "≡ƒöç Skipping recovery check (already handled this session)"
          );
          return;
        }

        // Get session info
        const lastSessionCount = parseInt(
          localStorage.getItem("ue5_last_session_count") || "0"
        );
        const sessionActive = localStorage.getItem("ue5_session_active");
        const currentLocalCount = localQuestions.length;

        // If session was marked active but we have fewer questions, might be a crash
        const possibleCrash =
          sessionActive === "true" && currentLocalCount < lastSessionCount;
        const localEmpty = currentLocalCount === 0;

        if (possibleCrash || localEmpty) {
          // Check Firestore for backup data
          console.log("≡ƒöì Checking Firestore for recoverable data...");
          const firestoreQuestions = await getQuestionsFromFirestore();

          if (firestoreQuestions.length > currentLocalCount) {
            console.log(
              `≡ƒôª Found ${firestoreQuestions.length} questions in Firestore (local has ${currentLocalCount})`
            );
            setRecoveryData({
              firestoreCount: firestoreQuestions.length,
              localCount: currentLocalCount,
              questions: firestoreQuestions,
            });
            setShowRecoveryPrompt(true);
          } else {
            // No recovery needed, mark as handled
            sessionStorage.setItem("ue5_recovery_handled", "true");
          }
        } else {
          // No recovery needed, mark as handled
          sessionStorage.setItem("ue5_recovery_handled", "true");
        }

        // Mark session as active
        localStorage.setItem("ue5_session_active", "true");
      } catch (error) {
        console.warn("Crash recovery check failed:", error);
      }
    };

    // Delay check to allow auth to settle
    const timer = setTimeout(checkForCrash, 2000);
    return () => clearTimeout(timer);
  }, [localQuestions.length]);

  // Update session count periodically
  useEffect(() => {
    const interval = setInterval(() => {
      localStorage.setItem(
        "ue5_last_session_count",
        localQuestions.length.toString()
      );
    }, 10000); // Every 10 seconds

    return () => clearInterval(interval);
  }, [localQuestions.length]);

  // Clean up session flag on proper unload
  useEffect(() => {
    const handleBeforeUnload = () => {
      localStorage.setItem("ue5_session_active", "false");
      localStorage.setItem(
        "ue5_last_session_count",
        localQuestions.length.toString()
      );
    };

    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => window.removeEventListener("beforeunload", handleBeforeUnload);
  }, [localQuestions.length]);

  // Recovery action
  const handleRecover = useCallback(async () => {
    if (!recoveryData) return;

    setIsRecovering(true);

    // Start time for minimum display duration
    const startTime = Date.now();
    const MIN_DISPLAY_MS = 1500; // Show progress for at least 1.5 seconds

    try {
      // Merge Firestore questions into local state
      const existingIds = new Set(localQuestions.map((q) => q.uniqueId));
      const newQuestions = recoveryData.questions.filter(
        (q) => !existingIds.has(q.uniqueId)
      );

      if (newQuestions.length > 0) {
        // Add questions to state IMMEDIATELY (fast path)
        addQuestionsToState(newQuestions, true);
        showMessage(
          `Γ£à Recovered ${newQuestions.length} questions from cloud backup!`,
          5000
        );

        // Log to analytics in background (non-blocking)
        // Use requestIdleCallback or setTimeout to not block the UI
        const logInBackground = async () => {
          try {
            const { logQuestion } = await import("../utils/analyticsStore");
            // Batch log - just log a summary instead of each question
            console.log(
              `≡ƒôè Logging ${newQuestions.length} recovered questions to analytics...`
            );
            // Only log first 50 to analytics to avoid performance issues
            const samplesToLog = newQuestions.slice(0, 50);
            samplesToLog.forEach((q) => {
              logQuestion({
                id: q.uniqueId,
                created: q.createdAt || new Date().toISOString(),
                status: q.status || "pending",
                discipline: q.discipline,
                difficulty: q.difficulty,
                type: q.type,
                questionText: q.question,
                qualityScore: q.qualityScore || null,
              });
            });
          } catch (err) {
            console.warn("Background analytics logging failed:", err);
          }
        };

        // Run in background after UI updates
        if ("requestIdleCallback" in window) {
          window.requestIdleCallback(logInBackground);
        } else {
          setTimeout(logInBackground, 100);
        }
      }

      // Ensure progress bar is visible for at least MIN_DISPLAY_MS
      const elapsed = Date.now() - startTime;
      if (elapsed < MIN_DISPLAY_MS) {
        await new Promise((resolve) =>
          setTimeout(resolve, MIN_DISPLAY_MS - elapsed)
        );
      }
      // Mark as handled for this session
      sessionStorage.setItem("ue5_recovery_handled", "true");

      setShowRecoveryPrompt(false);
      setRecoveryData(null);
    } catch (error) {
      console.error("Recovery failed:", error);
      showMessage(
        "Γ¥î Recovery failed. Please try loading from Database View.",
        5000
      );
    } finally {
      setIsRecovering(false);
    }
  }, [recoveryData, localQuestions, addQuestionsToState, showMessage]);

  const dismissRecovery = useCallback(() => {
    setShowRecoveryPrompt(false);
    setRecoveryData(null);
    // Mark that user dismissed, don't prompt again this session
    sessionStorage.setItem("ue5_recovery_handled", "true");
    localStorage.setItem("ue5_recovery_dismissed", "true");
  }, []);

  return {
    showRecoveryPrompt,
    recoveryData,
    isRecovering,
    handleRecover,
    dismissRecovery,
  };
};

import { useCallback } from 'react';
import { saveQuestionToFirestore } from '../services/firebase';

/**
 * Hook for managing database view actions.
 * Handles updating database questions and kicking questions back to review.
 * 
 * @param {Object} params - Hook parameters
 * @param {Function} params.setDatabaseQuestions - Setter for database questions state
 * @param {Function} params.setHistoricalQuestions - Setter for historical questions state
 * @param {Function} params.showMessage - Function to display toast messages
 * @returns {Object} Database action handlers
 */
export const useDatabaseActions = ({
  setDatabaseQuestions,
  setHistoricalQuestions,
  showMessage,
  handleLoadFromFirestore,
}) => {
  /**
   * Update a single question in the database view (local only).
   * User must sync to Firestore manually.
   *
   * @param {string|number} id - Question ID
   * @param {Object|Function} update - Update data or updater function
   */
  const handleUpdateDatabaseQuestion = useCallback(
    (id, update) => {
      setDatabaseQuestions((prev) =>
        prev.map((q) => {
          if (q.id !== id) return q;
          const newData = typeof update === "function" ? update(q) : update;
          return { ...q, ...newData };
        })
      );
      showMessage(
        "Question updated locally. Click 'Sync to Firestore' to save changes.",
        3000
      );
    },
    [setDatabaseQuestions, showMessage]
  );

  /**
   * Remove question from database and send it back to Review Mode.
   * Deletes from Firestore and adds to historical questions as pending.
   *
   * @param {Object} question - Question to kick back
   */
  const handleKickBackToReview = useCallback(
    async (question) => {
      try {
        // Update status to pending in Firestore (preserve the question)
        const updatedQuestion = {
          ...question,
          status: "pending",
          kickedBackAt: new Date().toISOString(),
          kickedBackBy: "user",
          kickedBackReason: "Moved from Database to Review",
        };

        console.log(
          "≡ƒöä [Kick Back] Saving to Firestore:",
          updatedQuestion.uniqueId
        );
        await saveQuestionToFirestore(updatedQuestion);

        // Remove from database view (so it no longer shows)
        console.log("≡ƒöä [Kick Back] Removing from databaseQuestions");
        setDatabaseQuestions((prev) =>
          prev.filter((q) => q.uniqueId !== question.uniqueId)
        );

        // Add to historical questions with 'pending' status so it appears in Review Mode
        console.log("≡ƒöä [Kick Back] Adding to historicalQuestions");
        setHistoricalQuestions((prev) => {
          // Check if already exists to prevent duplicates
          if (prev.some((q) => q.uniqueId === question.uniqueId)) {
            console.log(
              "≡ƒöä [Kick Back] Updating existing in historicalQuestions"
            );
            return prev.map((q) =>
              q.uniqueId === question.uniqueId ? updatedQuestion : q
            );
          }
          console.log(
            `≡ƒöä [Kick Back] Historical: ${prev.length} -> ${prev.length + 1}`
          );
          return [...prev, updatedQuestion];
        });

        showMessage("Question kicked back to Review. Refreshing...", 3000);

        // Force refresh to ensure counts are updated
        if (handleLoadFromFirestore) {
          console.log("≡ƒöä [Kick Back] Triggering Firestore refresh");
          await handleLoadFromFirestore();
        }
      } catch (error) {
        console.error("Error kicking back question:", error);
        showMessage("Failed to kick back question. Please try again.", 3000);
      }
    },
    [
      setDatabaseQuestions,
      setHistoricalQuestions,
      showMessage,
      handleLoadFromFirestore,
    ]
  );

  return {
    handleUpdateDatabaseQuestion,
    handleKickBackToReview,
  };
};

/**
 * useEditLock Hook
 *
 * Manages edit locks for concurrent editing protection.
 *
 * Features:
 * - Acquire lock on edit start (or after 1s viewing)
 * - Automatic heartbeat renewal every 30 seconds
 * - Release lock on save/cancel/unmount
 * - Track lock status and ownership
 * - Re-attempt lock acquisition when tab regains focus (if previously blocked)
 */

import { useState, useEffect, useRef, useCallback } from "react";
import { getAgents } from "../agents";

// =========================================================================
// GLOBAL LOCK STATE - Persists across component remounts
// =========================================================================
// When components remount (e.g., due to parent re-renders), internal refs reset.
// This module-level state tracks active locks so we don't release on unmount
// and immediately re-acquire on remount.
const globalLockState = {
  activeLocks: new Map(), // questionId -> { userId, timeoutId }
};

// Mark lock as active and cancel any pending release
function markLockActive(questionId, userId) {
  const existing = globalLockState.activeLocks.get(questionId);
  if (existing?.timeoutId) {
    clearTimeout(existing.timeoutId);
  }
  globalLockState.activeLocks.set(questionId, { userId, timeoutId: null });
}

// Schedule delayed release - allows time for remount to cancel it
function scheduleLockRelease(questionId, releaseCallback) {
  const existing = globalLockState.activeLocks.get(questionId);
  if (existing?.timeoutId) {
    clearTimeout(existing.timeoutId);
  }
  
  const timeoutId = setTimeout(() => {
    console.log(`[useEditLock] Executing delayed release for: ${questionId}`);
    globalLockState.activeLocks.delete(questionId);
    releaseCallback();
  }, 2000); // 2 second delay allows component to remount and cancel
  
  globalLockState.activeLocks.set(questionId, { 
    ...existing, 
    timeoutId 
  });
}

// Check if user already has an active lock
function hasActiveLock(questionId, userId) {
  const lock = globalLockState.activeLocks.get(questionId);
  return lock && lock.userId === userId;
}

// Clear lock state (on explicit release or navigation)
function _clearLockState(questionId) {
  const existing = globalLockState.activeLocks.get(questionId);
  if (existing?.timeoutId) {
    clearTimeout(existing.timeoutId);
  }
  globalLockState.activeLocks.delete(questionId);
}

/**
 * Hook for managing edit locks
 * @param {string} questionId - Question document ID
 * @param {string} userId - Firebase Auth UID
 * @param {string} userEmail - User's email
 * @param {boolean} isViewing - Whether user is currently viewing this question
 * @param {Function} onLockExpired - Callback when lock expires
 * @param {boolean} isProcessing - Guard to prevent lock release during active save
 * @returns {object} Lock state and control functions
 */
export function useEditLock(
  questionId,
  userId,
  userEmail,
  isViewing,
  onLockExpired,
  isProcessing = false
) {
  const [lockStatus, setLockStatus] = useState("none"); // 'none' | 'acquiring' | 'acquired' | 'locked_by_other' | 'expired'
  const [lockInfo, setLockInfo] = useState(null);
  const [lockedBy, setLockedBy] = useState(null);

  // Refs for interval/timer management
  const heartbeatRef = useRef(null);
  const lockAttemptedRef = useRef(false);
  const viewTimerRef = useRef(null);
  const consecutiveFailuresRef = useRef(0);

  // Refs ONLY for cleanup/unmount logic (closures can be stale)
  const lockStatusRef = useRef(lockStatus);
  const isProcessingRef = useRef(isProcessing);

  // Keep cleanup refs updated
  useEffect(() => {
    lockStatusRef.current = lockStatus;
    isProcessingRef.current = isProcessing;
  }, [lockStatus, isProcessing]);

  const agents = getAgents();

  /**
   * Acquire an edit lock
   */
  const acquireLock = useCallback(async () => {
    // Use ref to check current status (avoids stale closure)
    if (lockStatusRef.current === "acquired") {
      return { success: true };
    }

    if (!agents) {
      console.warn("[useEditLock] Agents not initialized yet");
      return { success: false, error: "Agents not initialized" };
    }

    if (!questionId || !userId || !userEmail) {
      console.warn("[useEditLock] Missing required parameters");
      return { success: false, error: "Missing required parameters" };
    }

    setLockStatus("acquiring");
    lockAttemptedRef.current = true;

    const { lockAgent, auditAgent } = agents;

    try {
      const result = await lockAgent.acquireLock(
        String(questionId),
        userId,
        userEmail
      );

      if (result.success) {
        setLockStatus("acquired");
        setLockInfo(result.lock);
        setLockedBy(null);
        
        // Mark lock active in global state to survive remounts
        markLockActive(questionId, userId);

        await auditAgent.logLockAcquired(
          String(questionId),
          userId,
          userEmail,
          result.action === "stolen"
        );
        console.log(`[useEditLock] Lock acquired for question ${questionId}`);
        return { success: true };
      } else {
        setLockStatus("locked_by_other");
        // LockAgent.acquireLock returns { lockedBy: existingLock } on rejection
        setLockedBy(result.lockedBy);
        console.warn(`[useEditLock] Lock acquisition failed:`, result.error);
        return { success: false, error: result.error };
      }
    } catch (error) {
      console.error("[useEditLock] Lock acquisition error:", error);
      setLockStatus("none");
      return { success: false, error: error.message };
    }
  }, [questionId, userId, userEmail, agents]);

  /**
   * Renew the lock (heartbeat)
   */
  const renewLock = useCallback(async () => {
    if (!agents || !questionId) return { success: false };

    const { lockAgent } = agents;

    try {
      const result = await lockAgent.renewLock(String(questionId));

      if (!result.success) {
        if (result.isNetworkError) {
          consecutiveFailuresRef.current++;
          console.warn(`[useEditLock] Lock renewal network failure (${consecutiveFailuresRef.current}):`, result.error);
          
          // Allow up to 3 consecutive network failures (approx 1.5 mins) before expiring
          if (consecutiveFailuresRef.current >= 3) {
            console.error("[useEditLock] Persistent network failure (3 attempts). Expiring lock.");
            setLockStatus("expired");
            if (onLockExpired) onLockExpired();
            return result;
          }
          
          // Return special success-like state for network retry
          return { success: true, isRetrying: true };
        }

        console.warn("[useEditLock] Lock renewal failed (logic error):", result.error);
        setLockStatus("expired");
        if (onLockExpired) onLockExpired();
      } else {
        // Reset failure counter on success
        consecutiveFailuresRef.current = 0;
      }

      return result;
    } catch (error) {
      // Uncaught errors still expire
      console.error("[useEditLock] Lock renewal unexpected error:", error);
      setLockStatus("expired");
      if (onLockExpired) onLockExpired();
      return { success: false, error: error.message };
    }
  }, [agents, questionId, onLockExpired]);

  // Keep renewLock in a ref so heartbeat effect doesn't restart when callback changes
  const renewLockRef = useRef(renewLock);
  useEffect(() => {
    renewLockRef.current = renewLock;
  }, [renewLock]);

  /**
   * Release the lock
   */
  const releaseLock = useCallback(async () => {
    if (!agents || !questionId) return { success: false };

    const { lockAgent, auditAgent } = agents;

    try {
      const result = await lockAgent.releaseLock(String(questionId));

      if (result.success) {
        setLockStatus("none");
        setLockInfo(null);
        setLockedBy(null);
        await auditAgent.logLockReleased(String(questionId), userId, userEmail);
        console.log(`[useEditLock] Lock released for question ${questionId}`);
      }

      return result;
    } catch (error) {
      console.error("[useEditLock] Lock release error:", error);
      return { success: false, error: error.message };
    }
  }, [agents, questionId, userId, userEmail]);

  /**
   * Check current lock status
   */
  const checkLockStatus = useCallback(async () => {
    if (!agents || !questionId) return { locked: false };

    const { lockAgent } = agents;

    try {
      const result = await lockAgent.checkLockStatus(String(questionId));
      if (result.locked) {
        // LockAgent.checkLockStatus returns { lock: lockData } - this IS the lockedBy info
        setLockedBy(result.lock);
        setLockStatus("locked_by_other");
      } else {
        setLockStatus("none");
        setLockedBy(null);
      }
      return result;
    } catch (error) {
      console.error("[useEditLock] Lock status check error:", error);
      return { locked: false, error: error.message };
    }
  }, [agents, questionId]);

  // Heartbeat Effect - Renew lock every 30s when acquired
  // Uses ref to avoid restarting when renewLock changes
  useEffect(() => {
    if (lockStatus !== "acquired") return;

    console.log("[useEditLock] Starting heartbeat for", questionId);
    heartbeatRef.current = setInterval(async () => {
      const result = await renewLockRef.current();
      if (!result.success) {
        if (heartbeatRef.current) {
          clearInterval(heartbeatRef.current);
          heartbeatRef.current = null;
        }
      }
    }, 30000);

    return () => {
      if (heartbeatRef.current) {
        console.log("[useEditLock] Stopping heartbeat for", questionId);
        clearInterval(heartbeatRef.current);
        heartbeatRef.current = null;
      }
    };
  }, [lockStatus, questionId]);

  // Keep releaseLock in a ref so cleanup effect doesn't restart when callback changes
  const releaseLockRef = useRef(releaseLock);
  useEffect(() => {
    releaseLockRef.current = releaseLock;
  }, [releaseLock]);

  // Keep acquireLock in a ref so auto-acquire effect doesn't restart
  const acquireLockRef = useRef(acquireLock);
  useEffect(() => {
    acquireLockRef.current = acquireLock;
  }, [acquireLock]);

  // Release lock on unmount OR when questionId changes
  // Uses delayed release to allow remounts to cancel and keep the lock
  useEffect(() => {
    const qId = String(questionId);
    
    // On mount/update: cancel any pending release for this question
    markLockActive(qId, userId);

    return () => {
      // Use refs to check latest values in cleanup (closures can be stale)
      if (lockStatusRef.current === "acquired" && !isProcessingRef.current) {
        console.log(`[useEditLock] Scheduling delayed release for: ${qId}`);
        // Use delayed release - if component remounts quickly, it will be cancelled
        scheduleLockRelease(qId, () => {
          console.log(`[useEditLock] Releasing lock on exit for: ${qId}`);
          releaseLockRef.current();
        });
      } else if (isProcessingRef.current) {
        console.log(
          `[useEditLock] Delaying lock release for ${qId} - save in progress`
        );
      }
    };
  }, [questionId, userId]); // Removed releaseLock dependency

  // Auto-acquire lock after 1s view
  // Uses ref to avoid effect restart when callback identity changes
  useEffect(() => {
    // Skip if already have active lock in global state (survived remount)
    if (hasActiveLock(questionId, userId)) {
      console.log("[useEditLock] Reusing existing lock from global state");
      setLockStatus("acquired");
      lockAttemptedRef.current = true;
      return;
    }
    
    if (
      !isViewing ||
      lockAttemptedRef.current ||
      !questionId ||
      !userId ||
      !userEmail
    ) {
      if (!isViewing && viewTimerRef.current) {
        clearTimeout(viewTimerRef.current);
        viewTimerRef.current = null;
      }
      return;
    }

    console.log("[useEditLock] Starting 1s view timer");
    viewTimerRef.current = setTimeout(() => {
      console.log("[useEditLock] Auto-acquiring lock");
      acquireLockRef.current();
    }, 1000);

    return () => {
      if (viewTimerRef.current) {
        clearTimeout(viewTimerRef.current);
        viewTimerRef.current = null;
      }
    };
  }, [isViewing, questionId, userId, userEmail]); // Removed acquireLock dependency

  // Reset lock attempt flag when questionId changes
  useEffect(() => {
    lockAttemptedRef.current = false;
  }, [questionId]);

  // Visibility-based retry: Re-attempt when tab regains focus if locked by other
  useEffect(() => {
    if (lockStatus !== "locked_by_other" || !isViewing) return;

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        console.log("[useEditLock] Tab visible - retrying lock acquisition");
        lockAttemptedRef.current = false; // Allow retry
        acquireLock();
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [lockStatus, isViewing, acquireLock]);

  return {
    lockStatus,
    lockInfo,
    lockedBy,
    isLocked: lockStatus === "locked_by_other",
    hasLock: lockStatus === "acquired",
    isAcquiring: lockStatus === "acquiring",
    isExpired: lockStatus === "expired",
    acquireLock,
    renewLock,
    releaseLock,
    checkLockStatus,
  };
}

import { useCallback } from "react";
import { getCSVContent, segmentQuestions } from "../utils/exportUtils";
import {
  saveQuestionsToSheets,
  fetchQuestionsFromSheets,
} from "../services/googleSheets";
import {
  saveQuestionToFirestore,
  getAllQuestionsFromFirestore,
} from "../services/firebase";
import { downloadFile } from "../utils/questionHelpers";
import { formatDate } from "../utils/dateHelpers";

export const useExport = (
  config,
  questions,
  historicalQuestions,
  uniqueFilteredQuestions,
  allQuestionsMap,
  showHistory,
  showMessage,
  setStatus,
  setIsProcessing,
  setDatabaseQuestions,
  setAppMode,
  setShowExportMenu,
  setShowBulkExportModal,
  setHistoricalQuestions
) => {
  const handleExportByGroup = useCallback(() => {
    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;
    const valid = sourceList.filter((q) => q.status !== "rejected");

    if (valid.length === 0) {
      setStatus("No accepted questions to export.");
      setTimeout(() => setStatus(""), 3000);
      return;
    }

    const groupedData = segmentQuestions(valid);

    let filesGenerated = 0;
    const exportDate = new Date();
    const datePart = formatDate(exportDate).replace(/-/g, "");

    Object.keys(groupedData).forEach((groupKey) => {
      const groupQuestions = groupedData[groupKey];
      const csvContent = getCSVContent(
        groupQuestions,
        config.creatorName,
        config.reviewerName
      );

      const fileNameParts = groupKey.replace(/ & /g, "_").replace(/ /g, "_");
      const filename = `${fileNameParts}_${datePart}.csv`;

      downloadFile(csvContent, filename);
      filesGenerated++;
    });

    setStatus(`Exported ${filesGenerated} segmented files.`);
    setTimeout(() => setStatus(""), 5000);
    if (setShowExportMenu) setShowExportMenu(false);
  }, [
    showHistory,
    questions,
    historicalQuestions,
    setStatus,
    config.creatorName,
    config.reviewerName,
    setShowExportMenu,
  ]);

  const handleExportCurrentTarget = useCallback(() => {
    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;

    const targetString = config.difficulty;
    const [targetDiff, targetTypeAbbrev] = targetString.split(" ");
    const targetType =
      targetTypeAbbrev === "MC" ? "Multiple Choice" : "True/False";

    const valid = sourceList.filter(
      (q) =>
        q.status !== "rejected" &&
        (q.language || "English") === config.language &&
        q.discipline === config.discipline &&
        q.difficulty === targetDiff &&
        q.type === targetType
    );

    if (valid.length === 0) {
      setStatus(
        `No accepted questions found for target: ${config.language} - ${targetString}`
      );
      setTimeout(() => setStatus(""), 3000);
      return;
    }

    const typePart = targetString.replace(/\s/g, "_");
    const disciplinePart = config.discipline.replace(/\s/g, "_");
    const datePart = new Date().toISOString().split("T")[0].replace(/-/g, "");
    const langPart = (config.language || "English").replace(/ /g, "_");

    const csvContent = getCSVContent(
      valid,
      config.creatorName,
      config.reviewerName
    );
    const filename = `${langPart}_${disciplinePart}_${typePart}_${datePart}.csv`;
    downloadFile(csvContent, filename);
    setStatus(`Exported ${valid.length} questions for target ${targetString}`);
    setTimeout(() => setStatus(""), 5000);
    if (setShowExportMenu) setShowExportMenu(false);
  }, [
    showHistory,
    questions,
    historicalQuestions,
    config.difficulty,
    config.language,
    config.discipline,
    setStatus,
    config.creatorName,
    config.reviewerName,
    setShowExportMenu,
  ]);

  const handleExportToSheets = useCallback(async () => {
    if (!config.sheetUrl) {
      showMessage("Please enter a Google Apps Script URL in settings.", 5000);
      return;
    }

    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;
    const validQuestions = sourceList.filter((q) => q.status !== "rejected");

    if (validQuestions.length === 0) {
      showMessage("No accepted questions to export.", 3000);
      return;
    }

    setIsProcessing(true);
    setStatus("Sending data to Google Sheets...");
    if (setShowExportMenu) setShowExportMenu(false);

    try {
      // Dual Write: Save to Sheets AND Firestore
      await Promise.all([
        saveQuestionsToSheets(config.sheetUrl, validQuestions),
        Promise.all(validQuestions.map((q) => saveQuestionToFirestore(q))),
      ]);

      showMessage(
        `Export launched! Data synced to Sheets and Firestore.`,
        7000
      );
    } catch (e) {
      console.error("Error pushing to Sheets endpoint:", e);
      showMessage(
        `Error connecting to endpoint. Check URL/Console: ${e.message}`,
        10000
      );
    } finally {
      setIsProcessing(false);
    }
  }, [
    config.sheetUrl,
    showMessage,
    showHistory,
    questions,
    historicalQuestions,
    setIsProcessing,
    setStatus,
    setShowExportMenu,
  ]);

  const handleLoadFromSheets = useCallback(async () => {
    if (!config.sheetUrl) {
      showMessage("Please enter a Google Apps Script URL first.", 3000);
      return;
    }

    setIsProcessing(true);
    setStatus("Loading from Google Sheets...");
    if (setShowExportMenu) setShowExportMenu(false);

    try {
      const data = await fetchQuestionsFromSheets(config.sheetUrl);
      const loadedQuestions = data.map((q, index) => ({
        id: Date.now() + index + Math.random(),
        uniqueId: q["Unique ID"] || q.uniqueId || crypto.randomUUID(),
        discipline: q.Discipline || q.discipline || "Imported",
        difficulty: q.Difficulty || q.difficulty || "Easy",
        type: q["Question Type"] || q.Type || q.type || "Multiple Choice",
        question: q.Question || q.question || "",
        options: {
          A: q["Option A"] || q.OptionA || "",
          B: q["Option B"] || q.OptionB || "",
          C: q["Option C"] || q.OptionC || "",
          D: q["Option D"] || q.OptionD || "",
        },
        correct: q.Answer || q.correct || "",
        explanation: q.Explanation || q.explanation || "",
        language: q.Language || q.language || "English",
        sourceUrl: q.SourceFile || q.sourceUrl || "",
        sourceExcerpt: q.sourceExcerpt || "",
        creatorName: q.creator || q.creatorName || "",
        reviewerName: q.reviewer || q.reviewerName || "",
        status: "accepted",
      }));

      setDatabaseQuestions(loadedQuestions);
      if (setHistoricalQuestions) setHistoricalQuestions(loadedQuestions);

      // Only switch to database view if NOT in review mode
      // Actually, user might want to see it in DB view first.
      // Let's keep behavior but ensure data is available for review.
      setAppMode("database");
      showMessage(
        `Loaded ${loadedQuestions.length} questions from Database View!`,
        3000
      );
    } catch (e) {
      console.error("Load Error:", e);
      showMessage(
        `Load Failed: ${e.message}. (Ensure Script Access is set to 'Anyone')`,
        7000
      );
    } finally {
      setIsProcessing(false);
      setStatus("");
    }
  }, [
    config.sheetUrl,
    showMessage,
    setIsProcessing,
    setStatus,
    setShowExportMenu,
    setDatabaseQuestions,
    setHistoricalQuestions,
    setAppMode,
  ]);

  const handleLoadFromFirestore = useCallback(
    async (silent = false) => {
      setIsProcessing(true);
      setStatus(silent ? "" : "Loading from Firestore...");
      if (setShowExportMenu) setShowExportMenu(false);

      try {
        // Use getAllQuestionsFromFirestore for shared database view (all authenticated users can see all questions)
        const data = await getAllQuestionsFromFirestore();

        // PERFORMANCE: Load once to prevent re-render loops
        const loadedQuestions = data.map((q, index) => ({
          ...q,
          id: q.id || Date.now() + index + Math.random(), // Ensure React key
          status: q.status || "pending", // CRITICAL: Preserve actual status
        }));

        setDatabaseQuestions(loadedQuestions);
        if (setHistoricalQuestions) setHistoricalQuestions(loadedQuestions);

        if (!silent) {
          showMessage(
            `Loaded ${loadedQuestions.length} questions from Firestore!`,
            3000
          );
        }
      } catch (e) {
        console.error("Firestore Load Error:", e);
        if (!silent) {
          showMessage(`Firestore Load Failed: ${e.message}`, 7000);
        }
      } finally {
        setIsProcessing(false);
        setStatus("");
      }
    },
    [
      setIsProcessing,
      setStatus,
      setShowExportMenu,
      setDatabaseQuestions,
      setHistoricalQuestions,
      showMessage,
    ]
  );

  const handleBulkExport = useCallback(
    async (exportOptions) => {
      const { format, includeRejected, languages, scope, segmentFiles, limit } =
        exportOptions;

      let sourceQuestions = [];
      if (scope === "filtered") {
        const visibleIds = new Set(
          uniqueFilteredQuestions.map((q) => q.uniqueId)
        );
        sourceQuestions = Array.from(allQuestionsMap.values()).flatMap(
          (variants) => variants.filter((v) => visibleIds.has(v.uniqueId))
        );
      } else {
        sourceQuestions = Array.from(allQuestionsMap.values()).flat();
      }

      let questionsToExport = sourceQuestions.filter((q) => {
        const langMatch = languages.includes(q.language || "English");
        const statusMatch = includeRejected || q.status !== "rejected";
        return langMatch && statusMatch;
      });

      if (limit && limit > 0) {
        questionsToExport = questionsToExport.slice(0, limit);
      }

      if (questionsToExport.length === 0) {
        showMessage("No questions to export with selected options.", 3000);
        return;
      }

      if (format === "sheets") {
        if (!config.sheetUrl) {
          showMessage(
            "Please enter a Google Apps Script URL in settings.",
            5000
          );
          return;
        }
        setIsProcessing(true);
        setStatus("Sending data to Google Sheets...");
        try {
          await saveQuestionsToSheets(config.sheetUrl, questionsToExport);
          showMessage(`Export launched! Check new tab for status.`, 5000);
        } catch (e) {
          console.error(e);
          showMessage(`Error: ${e.message}`, 5000);
        } finally {
          setIsProcessing(false);
        }
        return;
      }

      if (segmentFiles && format === "csv") {
        const groupedData = questionsToExport.reduce((acc, q) => {
          const typeAbbrev = q.type === "True/False" ? "T/F" : "MC";
          const key = `${q.language || "English"}_${q.discipline}_${
            q.difficulty
          }_${typeAbbrev}`;
          if (!acc[key]) acc[key] = [];
          acc[key].push(q);
          return acc;
        }, {});

        let filesGenerated = 0;
        const datePart = formatDate(new Date()).replace(/-/g, "");

        Object.keys(groupedData).forEach((groupKey) => {
          const groupQuestions = groupedData[groupKey];
          const csvContent = getCSVContent(
            groupQuestions,
            config.creatorName,
            config.reviewerName
          );
          const fileNameParts = groupKey
            .replace(/ & /g, "_")
            .replace(/ /g, "_");
          const filename = `${fileNameParts}_${datePart}.csv`;
          downloadFile(csvContent, filename);
          filesGenerated++;
        });
        showMessage(`Exported ${filesGenerated} segmented files.`, 4000);
        return;
      }

      if (format === "csv") {
        const csvContent = getCSVContent(
          questionsToExport,
          config.creatorName,
          config.reviewerName
        );
        downloadFile(csvContent, `bulk_export_${Date.now()}.csv`, "text/csv");
      } else if (format === "json") {
        downloadFile(
          JSON.stringify(questionsToExport, null, 2),
          `bulk_export_${Date.now()}.json`,
          "application/json"
        );
      } else if (format === "markdown") {
        const md = questionsToExport
          .map((q) => {
            return `## ${q.question}\n\n**Difficulty:** ${
              q.difficulty
            } | **Type:** ${q.type} | **Language:** ${
              q.language
            }\n\n**Options:**\n- A: ${q.options?.A}\n- B: ${q.options?.B}\n${
              q.options?.C ? `- C: ${q.options.C}\n` : ""
            }${q.options?.D ? `- D: ${q.options.D}\n` : ""}\n**Correct:** ${
              q.correct
            }\n\n---\n`;
          })
          .join("\n");
        downloadFile(md, `bulk_export_${Date.now()}.md`, "text/markdown");
      }

      showMessage(
        `Exported ${
          questionsToExport.length
        } questions as ${format.toUpperCase()}.`,
        4000
      );
    },
    [
      uniqueFilteredQuestions,
      allQuestionsMap,
      showMessage,
      config.sheetUrl,
      setIsProcessing,
      setStatus,
      config.creatorName,
      config.reviewerName,
    ]
  );

  return {
    handleExportByGroup,
    handleExportCurrentTarget,
    handleExportToSheets,
    handleLoadFromSheets,
    handleLoadFromFirestore,
    handleBulkExport,
  };
};

import { useState, useRef } from 'react';
import { processUploadedFile } from '../utils/fileProcessor';
import { generateContentSecure as generateContent } from '../services/geminiSecure';
import { processMultipleFiles, analyzeOptimization } from '../utils/contextOptimizer';

export const useFileHandler = (config, setConfig, addQuestionsToState, showMessage, setStatus, isApiReady, effectiveApiKey) => {
    const [files, setFiles] = useState([]);
    const fileInputRef = useRef(null);
    const [isDetecting, setIsDetecting] = useState(false);

    const removeFile = (index) => { setFiles(prev => prev.filter((_, i) => i !== index)); };

    const getFileContext = () => {
        if (files.length === 0) return "";

        // Use context optimizer for smart file processing
        const optimizedContext = processMultipleFiles(
            files.map(f => ({ name: f.name, content: f.content })),
            config.discipline
        );

        // Log optimization results
        const originalContext = files.map(f => `## ${f.name}\n${f.content}`).join('\n\n');
        const analysis = analyzeOptimization(originalContext, optimizedContext);

        if (analysis.reduction.percentage > 0) {
            // Optimization info available
        }

        return "\n\n### ATTACHED LOCAL SOURCE FILES:\n" + optimizedContext;
    };

    const handleFileChange = async (e, showHistory) => {
        const newFiles = Array.from(e.target.files);
        if (newFiles.length === 0) return;

        let importedCount = 0;
        let referenceCount = 0;
        const errors = [];

        for (const file of newFiles) {
            const result = await processUploadedFile(file, config.creatorName);

            if (result.error) {
                errors.push(`${file.name}: ${result.error}`);
                continue;
            }

            if (result.type === 'questions') {
                addQuestionsToState(result.data, showHistory);
                importedCount += result.data.length;

            } else if (result.type === 'reference') {
                setFiles(prev => [...prev, result.data]);
                referenceCount++;
            }
        }

        if (importedCount > 0) showMessage(`Successfully imported ${importedCount} questions.`, 4000);
        if (referenceCount > 0) showMessage(`Added ${referenceCount} reference files.`, 3000);
        if (errors.length > 0) {
            console.error("File processing errors:", errors);
            showMessage(`Some files failed: ${errors.slice(0, 2).join(', ')}`, 6000);
        }

        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const handleDetectTopics = async () => {
        if (files.length === 0) return;
        if (!isApiReady) { showMessage("API key is required for detection. Please enter it in the settings panel.", 5000); return; }

        setIsDetecting(true); setStatus('Scanning...');
        const prompt = `Analyze content. Identify 3 prominent technical disciplines. Return ONLY comma-separated list. ${getFileContext()}`;
        try {
            const detected = await generateContent(effectiveApiKey, "Technical Analyst", prompt, setStatus);
            setConfig(prev => ({ ...prev, discipline: detected.split(',')[0].trim() }));
            setStatus('Detected'); setTimeout(() => setStatus(''), 2000);
        } catch { setStatus('Failed'); } finally { setIsDetecting(false); }
    };

    return {
        files, setFiles,
        fileInputRef,
        isDetecting,
        handleFileChange,
        removeFile,
        getFileContext,
        handleDetectTopics
    };
};

/**
 * useFiltering Hook
 *
 * Manages all filtering and search state for the question list, including:
 * - Search term
 * - Filter mode (pending/accepted/rejected/all)
 * - Show history toggle
 * - Filter by creator
 * - Filter by tags
 * - Sort order
 * - Current review index
 * - Computed filtered question lists
 * - LocalStorage persistence
 */
import { useState, useEffect, useMemo, useRef } from "react";
import {
  createFilteredQuestions,
  createUniqueFilteredQuestions,
} from "../utils/questionFilters";

/**
 * Custom hook for managing question filtering state and logic.
 *
 * @param {Object} params - Hook parameters
 * @param {Array} params.questions - Current session questions
 * @param {Array} params.historicalQuestions - Historical questions from cloud
 * @param {Object} params.config - App configuration (creatorName, discipline, difficulty, language)
 * @param {string} params.appMode - Current app mode ('create', 'review', 'database', etc.)
 * @returns {Object} Filtering state and handlers
 */
export function useFiltering({
  questions,
  historicalQuestions,
  config,
  appMode,
  allQuestionsMap,
}) {
  // ========================================================================
  // STATE - Filter & Search
  // ========================================================================
  const [searchTerm, setSearchTerm] = useState(
    () => localStorage.getItem("ue5_pref_search") || ""
  );
