    setHistoricalQuestions((prev) =>
      prev.map((q) => (q.uniqueId === uniqueId ? updateFn(q) : q))
    );

    // CRITICAL: Also update in databaseQuestions so the Database View reflects the changes
    setDatabaseQuestions((prev) =>
      prev.map((q) => (q.uniqueId === uniqueId ? updateFn(q) : q))
    );
  }, []);

  // Status update handler - now with version control and conflict resolution
  const handleUpdateStatus = useCallback(
    async (id, newStatus, rejectionReason = null) => {
      // Find the question
      const variants = allQuestionsMap.get(id) || [];
      const currentQ =
        variants.find((v) => v.id === id) ||
        questions.find((q) => q.id === id) ||
        historicalQuestions.find((q) => q.id === id);

      if (!currentQ) {
        console.warn(`handleUpdateStatus: Question ${id} not found`);
        return;
      }

      // Validate and normalize the document ID
      // - Firestore expects string IDs
      // - Legacy questions may have numeric IDs, so convert them
      let docId = currentQ.id || currentQ.uniqueId;

      // Handle legacy numeric IDs by converting to string
      if (typeof docId === "number") {
        console.warn(`Converting numeric ID to string: ${docId}`);
        docId = String(docId);
      }

      if (!docId || typeof docId !== "string") {
        console.error("Invalid question ID:", { currentQ, id, docId });
        if (showMessage) {
          showMessage(
            "ΓÜá∩╕Å Cannot save: Question has invalid ID. Please refresh the page.",
            5000
          );
        }
        return;
      }

      // SPECIAL CASE: Hard Delete if status is 'deleted'
      if (newStatus === "deleted") {
        try {
          await deleteQuestionFromFirestore(currentQ.uniqueId || currentQ.id);
          setQuestions((prev) => prev.filter((q) => q.id !== id));
          setHistoricalQuestions((prev) => prev.filter((q) => q.id !== id));
          logQuestion({
            ...currentQ,
            status: "deleted",
            deletionReason: rejectionReason || "Status update to deleted",
            deletedAt: new Date().toISOString(),
          });
        } catch (err) {
          console.error("Failed to delete question:", err);
          if (showMessage)
            showMessage("Failed to delete question from cloud.", 3000);
        }
        return;
      }

      // Calculate new state
      let updatedQ = { ...currentQ };

      // Always complete review tracking when accepting or rejecting
      // This ensures analytics capture all reviews, even if reviewStartedAt is missing
      if (newStatus === "accepted" || newStatus === "rejected") {
        // If review wasn't started yet, retroactively set a start time
        // Use a reasonable estimate (30 seconds ago) for duration calculation
        if (!updatedQ.reviewStartedAt) {
          const estimatedStartTime = new Date(Date.now() - 30000); // 30 seconds ago
          updatedQ = {
            ...updatedQ,
            reviewStartedAt: estimatedStartTime.toISOString(),
          };
        }
        updatedQ = completeReviewTracking(updatedQ, config.creatorName);
      }

      updatedQ = {
        ...updatedQ,
        status: newStatus,
        critique: newStatus === "accepted" ? null : updatedQ.critique,
        rejectionReason: newStatus === "rejected" ? rejectionReason : null,
        rejectedAt: newStatus === "rejected" ? new Date().toISOString() : null,
        acceptedAt:
          newStatus === "accepted"
            ? new Date().toISOString()
            : updatedQ.acceptedAt,
      };

      try {
        // CRITICAL FIX: Accept/Reject operations don't acquire edit locks
        // so they can't use SaveGuardAgent (which requires locks).
        // Use direct Firestore save for status changes instead.
        await saveQuestionToFirestore(updatedQ);
        updateQuestionInState(id, () => updatedQ);

        if (
          showMessage &&
          (newStatus === "accepted" || newStatus === "rejected")
        ) {
          const statusLabel =
            newStatus === "accepted" ? "accepted" : "rejected";
          showMessage(`Γ£ô Question ${statusLabel} and saved to cloud`, 2000);
        }
      } catch (err) {
        console.error("Firestore sync failed:", err);
        // DEBUG: Log detailed error information to diagnose false positives
        console.log("[DEBUG] Error type:", typeof err);
        console.log("[DEBUG] Error message:", err.message);
        console.log("[DEBUG] Full error:", err);

        // Handle QUESTION_DELETED: Remove from local state automatically
        if (err.message?.startsWith("QUESTION_DELETED:")) {
          console.warn(
            `Question ${id} was deleted from Firestore - removing from local state`
          );
          setQuestions((prev) => prev.filter((q) => q.id !== id));
          setHistoricalQuestions((prev) => prev.filter((q) => q.id !== id));
          if (showMessage) {
            showMessage(
              "ΓÜá∩╕Å This question was deleted from the database. Removed from your queue.",
              4000
            );
          }
          return; // Exit early - question is now removed
        }

        // For other errors, show generic error and save locally
        if (showMessage) {
          showMessage(
            `ΓÜá∩╕Å Failed to save to cloud: ${err.message}. Question saved locally only.`,
            5000
          );
        }
        updateQuestionInState(id, () => updatedQ);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      updateQuestionInState,
      config.creatorName,
      config.userId,
      config.userEmail,
      allQuestionsMap,
      questions,
      historicalQuestions,
      agents,
      questionVersions,
      showMessage,
    ]
  );

  // Generic persisted update handler - now with version control
  const handleUpdateQuestion = useCallback(
    async (id, updates) => {
      // Find the question
      const variants = allQuestionsMap.get(id) || [];
      const currentQ =
        variants.find((v) => v.id === id) ||
        questions.find((q) => q.id === id) ||
        historicalQuestions.find((q) => q.id === id);

      if (!currentQ) {
        console.warn(`handleUpdateQuestion: Question ${id} not found`);
        return;
      }

      // Validate and normalize the document ID
      // - Firestore expects string IDs
      // - Legacy questions may have numeric IDs, so convert them
      let docId = currentQ.id || currentQ.uniqueId;

      // Handle legacy numeric IDs by converting to string
      if (typeof docId === "number") {
        console.warn(`Converting numeric ID to string: ${docId}`);
        docId = String(docId);
      }

      if (!docId || typeof docId !== "string") {
        console.error("Invalid question ID:", { currentQ, id, docId });
        if (showMessage) {
          showMessage(
            "ΓÜá∩╕Å Cannot save: Question has invalid ID. Please refresh the page.",
            5000
          );
        }
        return;
      }

      const updatedQ = { ...currentQ, ...updates };

      try {
        // Use SaveGuard Agent if available
        if (agents?.saveGuardAgent) {
          const baseVersion = questionVersions.get(id) || currentQ.version || 1;
          const result = await agents.saveGuardAgent.saveQuestion(
            docId, // Use validated document ID
            updates,
            baseVersion,
            config.userId || "unknown",
            config.userEmail || "unknown@example.com"
          );

          if (!result.success) {
            if (result.errorType === "VERSION_CONFLICT") {
              console.warn("Version conflict detected during question update");
              setConflictData({
                serverQuestion: result.serverQuestion,
                serverVersion: result.serverVersion,
                localChanges: updates,
                expectedVersion: baseVersion,
              });
              setShowConflictModal(true);
              return;
            }
            throw new Error(result.error || "Save failed");
          }

          // Update version tracking
          setQuestionVersions((prev) =>
            new Map(prev).set(id, result.newVersion)
          );

          // Update local state with new version
          updateQuestionInState(id, () => ({
            ...updatedQ,
            version: result.newVersion,
          }));
        } else {
          // Fallback: Direct save
          await saveQuestionToFirestore(updatedQ);
          updateQuestionInState(id, () => updatedQ);
        }
      } catch (err) {
        console.error("Firestore sync failed:", err);

        // Handle QUESTION_DELETED: Remove from local state automatically
        if (err.message?.startsWith("QUESTION_DELETED:")) {
          console.warn(
            `Question ${id} was deleted from Firestore - removing from local state`
          );
          setQuestions((prev) => prev.filter((q) => q.id !== id));
          setHistoricalQuestions((prev) => prev.filter((q) => q.id !== id));
          if (showMessage) {
            showMessage(
              "ΓÜá∩╕Å This question was deleted from the database. Removed from your queue.",
              4000
            );
          }
          return; // Exit early - question is now removed
        }

        // For other errors, show generic error and save locally
        if (showMessage) {
          showMessage(
            `ΓÜá∩╕Å Failed to save changes to cloud: ${err.message}`,
            4000
          );
        }
        updateQuestionInState(id, () => updatedQ);
      }
    },
    [
      updateQuestionInState,
      allQuestionsMap,
      questions,
      historicalQuestions,
      config.userId,
      config.userEmail,
      agents,
      questionVersions,
      showMessage,
    ]
  );

  // Statistics - count both pending and accepted questions for generation target
  const approvedCounts = useMemo(() => {
    const counts = CATEGORY_KEYS.reduce(
      (acc, key) => ({ ...acc, [key]: 0 }),
      {}
    );
    const countedIds = new Set();

    Array.from(allQuestionsMap.values()).forEach((variants) => {
      const baseQ =
        variants.find((v) => (v.language || "English") === "English") ||
        variants[0];

      // Count both pending and accepted questions for generation targets
      // This ensures newly generated questions update the counter immediately
      const isCountable =
        baseQ &&
        (baseQ.status === "accepted" ||
          baseQ.status === "pending" ||
          !baseQ.status) &&
        !countedIds.has(baseQ.uniqueId) &&
        baseQ.discipline === config.discipline;

      if (isCountable) {
        const typeAbbrev = baseQ.type === "True/False" ? "T/F" : "MC";
        const key = `${baseQ.difficulty} ${typeAbbrev}`;
        if (Object.prototype.hasOwnProperty.call(counts, key)) {
          counts[key]++;
          countedIds.add(baseQ.uniqueId);
        }
      }
    });
    return counts;
  }, [allQuestionsMap, config.discipline]);

  // Unified List (Source of Truth for Counts)
  const unifiedQuestions = useMemo(() => {
    const all = [];

    // FIX: Sort uniqueIds to ensure stable iteration order
    // Map.forEach() can have unstable order when Map is mutated
    const sortedUniqueIds = Array.from(allQuestionsMap.keys()).sort();

    sortedUniqueIds.forEach((uniqueId) => {
      const variants = allQuestionsMap.get(uniqueId);
      // Use the first variant or English version as the canonical entry
      const canonical =
        variants.find((v) => (v.language || "English") === "English") ||
        variants[0];
      if (canonical) all.push(canonical);
    });

    // Sort by date (newest first), with uniqueId as tiebreaker for stability
    return all.sort((a, b) => {
      const dateA = new Date(a.created || a.dateAdded || 0).getTime();
      const dateB = new Date(b.created || b.dateAdded || 0).getTime();

      // Primary sort: date (newest first)
      if (dateB !== dateA) {
        return dateB - dateA;
      }

      // Tiebreaker: uniqueId (alphabetical) for fully stable sort
      return (a.uniqueId || "").localeCompare(b.uniqueId || "");
    });
  }, [allQuestionsMap]);

  const approvedCount = useMemo(
    () => unifiedQuestions.filter((q) => q.status === "accepted").length,
    [unifiedQuestions]
  );
  const rejectedCount = useMemo(
    () => unifiedQuestions.filter((q) => q.status === "rejected").length,
    [unifiedQuestions]
  );
  const pendingCount = useMemo(
    () =>
      unifiedQuestions.filter((q) => !q.status || q.status === "pending")
        .length,
    [unifiedQuestions]
  );
  const otherCount = useMemo(
    () =>
      unifiedQuestions.filter(
        (q) =>
          q.status &&
          q.status !== "pending" &&
          q.status !== "accepted" &&
          q.status !== "rejected"
      ).length,
    [unifiedQuestions]
  );

  const totalApproved = useMemo(() => {
    return CATEGORY_KEYS.reduce((sum, key) => sum + approvedCounts[key], 0);
  }, [approvedCounts]);

  const overallPercentage = useMemo(() => {
    return Math.min(100, (totalApproved / TARGET_TOTAL) * 100);
  }, [totalApproved]);

  // Check if global quota is reached (kept for informational purposes)
  const _isGlobalQuotaMet = useMemo(() => {
    return totalApproved >= TARGET_TOTAL;
  }, [totalApproved]);

  // Calculate per-difficulty totals (combining MC and T/F)
  const _difficultyTotals = useMemo(() => {
    return {
      Beginner:
        (approvedCounts["Beginner MC"] || 0) +
        (approvedCounts["Beginner T/F"] || 0),
      Intermediate:
        (approvedCounts["Intermediate MC"] || 0) +
        (approvedCounts["Intermediate T/F"] || 0),
      Expert:
        (approvedCounts["Expert MC"] || 0) +
        (approvedCounts["Expert T/F"] || 0),
    };
  }, [approvedCounts]);

  // Target per difficulty level (2 categories * TARGET_PER_CATEGORY = 66 per difficulty)
  const _TARGET_PER_DIFFICULTY = TARGET_PER_CATEGORY * 2; // 66

  const isTargetMet = useMemo(() => {
    // Only block if the selected type for this difficulty is full
    // Global quota blocking is handled by validateGeneration() which
    // checks individual category limits properly
    const typeKey = config.type === "True/False" ? "T/F" : "MC";
    const categoryKey = `${config.difficulty} ${typeKey}`;
    const currentCount = approvedCounts[categoryKey] || 0;
    return currentCount >= TARGET_PER_CATEGORY;
  }, [config.difficulty, config.type, approvedCounts]);

  const maxBatchSize = useMemo(() => {
    // Calculate remaining for this specific type only
    // validateGeneration() handles cross-category logic
    const typeKey = config.type === "True/False" ? "T/F" : "MC";
    const categoryKey = `${config.difficulty} ${typeKey}`;
    const currentCount = approvedCounts[categoryKey] || 0;
    const remaining = TARGET_PER_CATEGORY - currentCount;
    return Math.min(30, Math.max(0, remaining));
  }, [config.difficulty, config.type, approvedCounts]);

  // Delete Handlers
  // Delete Handlers
  const handleDelete = useCallback((id) => setDeleteConfirmId(id), []);

  const confirmDelete = useCallback(
    async (reason = "Unknown") => {
      if (deleteConfirmId) {
        // Find the question before deleting to log it
        const questionToDelete =
          allQuestionsMap.get(deleteConfirmId)?.[0] ||
          questions.find((q) => q.id === deleteConfirmId) ||
          historicalQuestions.find((q) => q.id === deleteConfirmId);

        if (questionToDelete) {
          logQuestion({
            ...questionToDelete,
            status: "deleted",
            deletionReason: reason,
            deletedAt: new Date().toISOString(),
          });

          // Perform Hard Delete from Firestore
          try {
            await deleteQuestionFromFirestore(
              questionToDelete.uniqueId || questionToDelete.id
            );
          } catch (err) {
            // Safe to ignore re-renders here as it's an async error handling
            console.error(
              "Failed to delete from Firestore during confirmDelete:",
              err
            );
          }
        }

        console.log(`Deleting question ${deleteConfirmId}. Reason: ${reason}`);
        setQuestions((prev) => prev.filter((q) => q.id !== deleteConfirmId));
        setHistoricalQuestions((prev) =>
          prev.filter((q) => q.id !== deleteConfirmId)
        );
        if (showMessage) showMessage(`Question deleted: ${reason}`, 2000);
        setDeleteConfirmId(null);
      }
    },
    [
      deleteConfirmId,
      allQuestionsMap,
      questions,
      historicalQuestions,
      showMessage,
    ]
  );

  const handleDeleteAllQuestions = useCallback(() => {
    setShowClearModal(false);
    setQuestions([]);
    setHistoricalQuestions([]);
    if (showMessage) showMessage("Local session cleared.", 3000);
  }, [showMessage]);

  const checkAndStoreQuestions = useCallback(async (newQuestions) => {
    return newQuestions;
  }, []);

  // PERFORMANCE: Load more questions
  const _loadMoreQuestions = useCallback(
    async (userId) => {
      if (!hasMore || isLoadingMore) return;

      setIsLoadingMore(true);
      try {
        const {
          questions: moreQuestions,
          lastDoc: newLastDoc,
          hasMore: moreAvailable,
        } = await getQuestionsPaginated(userId, 20, lastDoc);

        setDatabaseQuestions((prev) => [...prev, ...moreQuestions]);
        setLastDoc(newLastDoc);
        setHasMore(moreAvailable);
      } catch (error) {
        console.error("Failed to load more questions:", error);
      } finally {
        setIsLoadingMore(false);
      }
    },
    [hasMore, isLoadingMore, lastDoc]
  );

  return {
    questions,
    setQuestions,
    historicalQuestions,
    setHistoricalQuestions,
    databaseQuestions,
    setDatabaseQuestions,
    allQuestionsMap,
    translationMap,
    addQuestionsToState,
    updateQuestionInState,
    updateAllVariantsInState,
    handleUpdateStatus,
    approvedCounts,
    approvedCount,
    rejectedCount,
    pendingCount,
    otherCount,
    totalApproved,
    overallPercentage,
    isTargetMet,
    maxBatchSize,
    deleteConfirmId,
    setDeleteConfirmId,
    showClearModal,
    setShowClearModal,
    handleDelete,
    confirmDelete,
    handleDeleteAllQuestions,
    checkAndStoreQuestions,
    unifiedQuestions,
    handleUpdateQuestion, // Added persistent update handler
    // Concurrent editing conflict resolution
    conflictData,
    showConflictModal,
    setShowConflictModal,
  };
};

import { useEffect, useState, useCallback, useRef } from "react";
import { subscribeToAllQuestions } from "../services/firebase";

/**
 * Custom hook for real-time Firestore synchronization.
 * Replaces cache-based approach with live listeners.
 *
 * MULTI-USER SUPPORT:
 * - When User A accepts a question, User B sees it disappear instantly
 * - When User A is reviewing question #5, User B can review #6 simultaneously
 * - Prevents duplicate work and ensures data consistency
 *
 * @param {boolean} enabled - Whether to enable real-time sync
 * @returns {Object} { questions, isLoading, error, refresh, syncStatus }
 */
export const useRealtimeQuestions = (enabled = true) => {
  const [questions, setQuestions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [syncStatus, setSyncStatus] = useState("disconnected"); // disconnected | connecting | synced

  // Track previous question count for change detection
  const prevCountRef = useRef(0);

  // Manual refresh function (forces re-subscription)
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const refresh = useCallback(() => {
    setRefreshTrigger((prev) => prev + 1);
  }, []);

  useEffect(() => {
    if (!enabled) {
      setIsLoading(false);
      setSyncStatus("disconnected");
      return;
    }

    console.log("≡ƒöä Setting up real-time question sync...");
    setIsLoading(true);
    setError(null);
    setSyncStatus("connecting");

    // Subscribe to real-time updates
    const unsubscribe = subscribeToAllQuestions(
      (updatedQuestions) => {
        const prevCount = prevCountRef.current;
        const newCount = updatedQuestions.length;

        // Detect changes from other users
        if (prevCount > 0 && newCount !== prevCount) {
          const diff = newCount - prevCount;
          if (diff > 0) {
            console.log(`≡ƒôÑ ${diff} new question(s) added by another user`);
          } else {
            console.log(
              `≡ƒôñ ${Math.abs(
                diff
              )} question(s) removed/accepted by another user`
            );
          }
        }

        prevCountRef.current = newCount;
        setQuestions(updatedQuestions);
        setIsLoading(false);
        setError(null);
        setSyncStatus("synced");
      },
      5000 // Max 5000 questions
    );

    // Cleanup on unmount or when refreshTrigger changes
    return () => {
      console.log("≡ƒ¢æ Cleaning up real-time listener");
      setSyncStatus("disconnected");
      unsubscribe();
    };
  }, [enabled, refreshTrigger]);

  return {
    questions,
    isLoading,
    error,
    refresh,
    syncStatus, // "disconnected" | "connecting" | "synced"
  };
};

import { useCallback } from "react";
import {
  QUALITY_PASS_THRESHOLD,
  TOAST_DURATION,
  TARGET_PER_CATEGORY,
} from "../utils/constants";

/**
 * Hook for managing review mode bulk actions.
 * Handles clearing pending, bulk accepting, and bulk critiquing.
 *
 * @param {Object} params - Hook parameters
 * @param {Array} params.uniqueFilteredQuestions - Filtered questions list
 * @param {Function} params.setQuestions - Setter for questions state
 * @param {Function} params.handleUpdateStatus - Function to update question status
 * @param {Function} params.handleCritique - Function to critique a question
 * @param {Function} params.showMessage - Function to display toast messages
 * @returns {Object} Review action handlers
 */
export const useReviewActions = ({
  uniqueFilteredQuestions,
  allQuestions, // Added: Full dataset for global operations
  setQuestions,
  handleUpdateStatus,
  handleCritique,
  showMessage,
}) => {
  /**
   * Clear all pending questions after confirmation.
   */
  const handleClearPending = useCallback(() => {
    if (
      window.confirm(
        "Are you sure you want to delete ALL pending questions? This cannot be undone."
      )
    ) {
      setQuestions((prev) =>
        prev.filter((q) => q.status === "accepted" || q.status === "rejected")
      );
      showMessage("All pending questions cleared.", 3000);
    }
  }, [setQuestions, showMessage]);

  /**
   * Bulk accept all questions with critique score >= threshold that are human verified.
   */
  const handleBulkAcceptHighScores = useCallback(() => {
    const highScoreQuestions = uniqueFilteredQuestions.filter(
      (q) =>
        q.critiqueScore >= QUALITY_PASS_THRESHOLD &&
        q.status !== "accepted" &&
        q.humanVerified
    );

    if (highScoreQuestions.length === 0) {
      showMessage(
        `No verified questions with score ΓëÑ ${QUALITY_PASS_THRESHOLD} to accept.`,
        TOAST_DURATION.MEDIUM
      );
      return;
    }

    highScoreQuestions.forEach((q) => handleUpdateStatus(q.id, "accepted"));
    showMessage(
      `Γ£ô Accepted ${highScoreQuestions.length} high-scoring questions!`,
      4000
    );
  }, [uniqueFilteredQuestions, handleUpdateStatus, showMessage]);

  /**
   * Bulk critique all questions without critique scores.
   * Processes sequentially to avoid rate limits.
   */
  const handleBulkCritiqueAll = useCallback(async () => {
    const uncritiquedQuestions = uniqueFilteredQuestions.filter(
      (q) => q.critiqueScore === undefined || q.critiqueScore === null
    );

    if (uncritiquedQuestions.length === 0) {
      showMessage("All questions already have critique scores.", 3000);
      return;
    }

    showMessage(
      `Running critique on ${uncritiquedQuestions.length} questions...`,
      3000
    );

    // Process sequentially to avoid rate limits
    for (const q of uncritiquedQuestions) {
      await handleCritique(q);
    }

    showMessage(
      `Γ£ô Critique complete for ${uncritiquedQuestions.length} questions!`,
      4000
    );
  }, [uniqueFilteredQuestions, handleCritique, showMessage]);

  /**
   * Trim excess pending questions to ensure equal distribution across categories.
   * Finds the category with the LEAST questions and trims all others to match.
   */
  const handleTrimExcess = useCallback(
    async (discipline) => {
      // 1. Group questions by category key (e.g., "Beginner MC")
      const groups = {};
      const pendingToDelete = [];

      // Initialize groups using ALL questions (not just filtered/visible ones)
      const sourceQuestions =
        allQuestions && allQuestions.length > 0
          ? allQuestions
          : uniqueFilteredQuestions;

      sourceQuestions.forEach((q) => {
        if (q.discipline !== discipline) return;

        const typeAbbrev = q.type === "True/False" ? "T/F" : "MC";
        const key = `${q.difficulty} ${typeAbbrev}`;

        if (!groups[key]) {
          groups[key] = {
            accepted: [],
            pending: [],
            rejected: [],
            total: 0,
          };
        }

        if (q.status === "accepted") groups[key].accepted.push(q);
        else if (q.status === "rejected") groups[key].rejected.push(q);
        else groups[key].pending.push(q);

        // Only count Accepted + Pending for the target (Rejected don't count towards "quota")
        if (q.status !== "rejected") {
          groups[key].total++;
        }
      });

      // 2. Use the standard target (40) instead of finding the minimum
      const target = TARGET_PER_CATEGORY;

      // 3. Determine which pending questions to delete
      let deleteCount = 0;
      Object.entries(groups).forEach(([_key, group]) => {
        const currentValid = group.accepted.length + group.pending.length;

        if (currentValid > target) {
          const surplus = currentValid - target;
          // We can only delete Pending questions. We cannot delete Accepted ones to reach target.
          const deletableCount = Math.min(surplus, group.pending.length);

          if (deletableCount > 0) {
            // Remove newest pending questions first
            const toRemove = group.pending.slice(0, deletableCount);
            toRemove.forEach((q) => pendingToDelete.push(q));
            deleteCount += toRemove.length;
          }
        }
      });

      if (deleteCount === 0) {
        showMessage(
          `Balanced! All sections already have ${target} (or fewer) questions.`,
          3000
        );
        return;
      }

      if (
        window.confirm(
          `Trimming to Common Count: ${target}\n\n` +
            `Found ${deleteCount} excess pending questions in ${discipline} that exceed the lowest section count (${target}).\n\n` +
            `Proceed to delete them?`
        )
      ) {
        // Get IDs of questions to delete
        const idsToDelete = new Set(pendingToDelete.map((q) => q.id));

        // Actually remove questions from the array
        setQuestions((prevQuestions) =>
          prevQuestions.filter((q) => !idsToDelete.has(q.id))
        );

        showMessage(
          `Γ£à Trimmed ${pendingToDelete.length} questions successfully!`,
          TOAST_DURATION.LONG
        );
      }
    },
    [uniqueFilteredQuestions, allQuestions, showMessage, setQuestions]
  );

  return {
    handleClearPending,
    handleBulkAcceptHighScores,
    handleBulkCritiqueAll,
    handleTrimExcess,
  };
};

/**
 * useToast Hook - Enhanced Version
 * 
 * Features:
 * - Smart message replacement (similar messages update instead of stack)
 * - Priority levels (high=sticky, medium=normal, low=replaceable)
 * - Progress toast support
 * - Deduplication
 */
import { useState, useCallback, useRef } from 'react';

// Patterns for messages that should replace (not stack)
const REPLACEABLE_PATTERNS = [
    /Score:\s*\d+\/100/i,           // Score updates
    /Critiquing\s+\d+/i,            // Critique progress
    /Translating.*\d+/i,            // Translation progress
    /Generated\s+\d+/i,             // Generation counts
    /Processing\s+\d+/i,            // Processing progress
    /Loading/i,                      // Loading states
    /Saving/i,                       // Saving states
    /\d+\s*of\s*\d+/i,              // X of Y progress
    /\(\d+\/\d+\)/,                  // (X/Y) progress
];

// Priority durations
const PRIORITY_CONFIG = {
    high: { duration: 0, sticky: true },      // Stays until manually dismissed
    medium: { duration: 6000, sticky: false }, // 6 seconds
    low: { duration: 3000, sticky: false },    // 3 seconds
    progress: { duration: 0, sticky: true },   // Progress toasts persist
};

/**
 * Check if a message matches any replaceable pattern
 */
const getMessagePattern = (message) => {
    for (const pattern of REPLACEABLE_PATTERNS) {
        if (pattern.test(message)) {
            return pattern;
        }
    }
    return null;
};

/**
 * Custom hook for managing toast notifications.
 * 
 * @returns {Object} Toast state and handlers
 */
export function useToast() {
    const [toasts, setToasts] = useState([]);
    const toastIdCounter = useRef(0);

    /**
     * Add or update a toast notification.
     * Smart replacement: If message matches a pattern, update existing toast.
     * 
     * @param {string} message - Toast message
     * @param {Object} options - Toast options
     * @param {string} options.type - Toast type ('info', 'success', 'error', 'warning', 'progress')
     * @param {string} options.priority - Priority level ('high', 'medium', 'low')
     * @param {number} options.duration - Custom duration in ms (overrides priority default)
     * @param {number} options.progress - Progress value 0-100 (for progress type)
     * @param {string} options.id - Custom ID for updating specific toasts
     */
    const addToast = useCallback((message, options = {}) => {
        const {
            type = 'info',
            priority = 'medium',
            duration,
            progress,
            id: customId
        } = options;

        const config = PRIORITY_CONFIG[priority] || PRIORITY_CONFIG.medium;
        const finalDuration = duration ?? config.duration;
        const pattern = getMessagePattern(message);

        setToasts(prev => {
            // Check for exact duplicate
            if (prev.some(t => t.message === message)) {
                return prev;
            }

            // Smart replacement: Find existing toast with matching pattern
            if (pattern || customId) {
                const existingIndex = prev.findIndex(t => 
                    (customId && t.id === customId) || 
                    (pattern && pattern.test(t.message))
                );

                if (existingIndex !== -1) {
                    // Update existing toast instead of adding new one
                    const updated = [...prev];
                    updated[existingIndex] = {
                        ...updated[existingIndex],
                        message,
                        type,
                        progress,
                        duration: finalDuration,
                        updatedAt: Date.now()
                    };
                    return updated;
                }
            }

            // Create new toast
            const id = customId || `toast-${++toastIdCounter.current}`;
            const newToast = {
                id,
                message,
                type,
                priority,
                duration: finalDuration,
                sticky: config.sticky,
                progress,
                createdAt: Date.now()
            };

            // Add new toast, keeping max 3 (but never remove high priority)
            const newToasts = [...prev, newToast];
            
            // If over limit, remove oldest low-priority toast
            if (newToasts.length > 3) {
                const lowPriorityIndex = newToasts.findIndex(t => t.priority === 'low' && !t.sticky);
                if (lowPriorityIndex !== -1) {
                    newToasts.splice(lowPriorityIndex, 1);
                } else {
                    // If no low priority, remove oldest non-sticky
                    const removableIndex = newToasts.findIndex(t => !t.sticky);
                    if (removableIndex !== -1) {
                        newToasts.splice(removableIndex, 1);
                    }
                }
            }

            return newToasts;
        });
    }, []);

    /**
     * Remove a toast by ID.
     */
    const removeToast = useCallback((id) => {
        setToasts(prev => prev.filter(t => t.id !== id));
    }, []);

    /**
     * Update a progress toast
     */
    const updateProgress = useCallback((id, progress, message) => {
        setToasts(prev => prev.map(t => 
            t.id === id 
                ? { ...t, progress, message: message || t.message, updatedAt: Date.now() }
                : t
        ));
    }, []);

    /**
     * Complete and auto-dismiss a progress toast
     */
    const completeProgress = useCallback((id, message, duration = 2000) => {
        setToasts(prev => prev.map(t => 
            t.id === id 
                ? { ...t, progress: 100, message: message || t.message, sticky: false, duration, type: 'success' }
                : t
        ));
    }, []);

    /**
     * Legacy showMessage for backward compatibility
     * @param {string} msg - Message to display
     * @param {string|number} typeOrDuration - Toast type OR duration (backward compat)
     * @param {number} duration - Duration in ms
     */
    const showMessage = useCallback((msg, typeOrDuration = 'info', duration) => {
        let type = 'info';
        let finalDuration = duration;

        // Backward compatibility: if second arg is number, treat as duration
        if (typeof typeOrDuration === 'number') {
            finalDuration = typeOrDuration;
            type = 'info';
        } else {
            type = typeOrDuration;
        }

        // Auto-detect priority based on message content
        let priority = 'medium';
        if (msg.includes('Error') || msg.includes('Failed') || msg.includes('Γ¥î') || msg.includes('Γ¢ö')) {
            priority = 'high';
            type = 'error';
        } else if (msg.includes('ΓÜá∩╕Å') || msg.includes('Warning')) {
            priority = 'medium';
            type = 'warning';
        } else if (msg.includes('Γ£ô') || msg.includes('Γ£à') || msg.includes('Success') || msg.includes('complete')) {
            type = 'success';
        } else if (msg.includes('...') || msg.includes('Loading') || msg.includes('Saving')) {
            priority = 'low';
        }

        addToast(msg, { type, priority, duration: finalDuration });
    }, [addToast]);

    return {
        toasts,
        addToast,
        removeToast,
        updateProgress,
        completeProgress,
        showMessage
    };
}

import { useState } from "react";
import { TUTORIAL_SCENARIOS } from "../utils/tutorialSteps";
import { validateScenario } from "../utils/tutorial/tutorialValidation";
import {
  setScenarioCompleted,
  isScenarioCompleted,
} from "../utils/tutorial/tutorialHelpers";
import { logTutorialEvent, TUTORIAL_EVENTS } from "../utils/tutorialAnalytics";

// State machine states
const TUTORIAL_STATES = {
  IDLE: "idle",
  ACTIVE: "active",
  COMPLETED: "completed",
  ERROR: "error",
};

/**
 * Hook for managing the interactive tutorial system with multiple scenarios.
 * Implements a state machine for robust tutorial flow control.
 *
 * @param {Function} showMessage - Function to display toast messages
 * @param {Function} [onError] - Optional error callback
 * @param {Object} [appContext] - App context with setters for modals/panels/tabs
 * @param {Function} [appContext.setShowGenSettings] - Setter for generation settings panel
 * @param {Function} [appContext.setShowAdvancedConfig] - Setter for advanced config panel
 * @param {Function} [appContext.setShowCritiqueModal] - Setter for critique modal
 * @param {Function} [appContext.setActiveAnalyticsTab] - Setter for analytics tab
 * @returns {Object} Tutorial state and handlers
 */
export const useTutorial = (showMessage, onError, appContext = {}) => {
  const [tutorialState, setTutorialState] = useState(TUTORIAL_STATES.IDLE);
  const [currentStep, setCurrentStep] = useState(0);
  const [activeScenario, setActiveScenario] = useState(null);
  const [errorMessage, setErrorMessage] = useState(null);

  // Get current steps based on active scenario
  const scenario = activeScenario ? TUTORIAL_SCENARIOS[activeScenario] : null;
  const tutorialSteps = scenario?.steps || [];
  const tutorialActive = tutorialState === TUTORIAL_STATES.ACTIVE;

  /**
   * Execute side effects for tutorial step actions
   * @param {import('../utils/tutorial/tutorialTypes').TutorialStep} step - Tutorial step with optional action
   */
  const executeStepAction = (step) => {
    if (!step?.action) return;

    const { type, payload } = step.action;

    console.log(`[Tutorial] Executing action: ${type}`, payload);

    try {
      switch (type) {
        case "OPEN_PANEL":
          if (
            payload === "advanced-settings" &&
            appContext.setShowAdvancedConfig
          ) {
            appContext.setShowAdvancedConfig(true);
          } else if (
            payload === "gen-settings" &&
            appContext.setShowGenSettings
          ) {
            appContext.setShowGenSettings(true);
          }
          break;

        case "OPEN_MODAL":
          if (payload === "critique" && appContext.setShowCritiqueModal) {
            appContext.setShowCritiqueModal(true);
          }
          break;

        case "SWITCH_TAB":
          if (appContext.setActiveAnalyticsTab) {
            appContext.setActiveAnalyticsTab(payload);
          }
          break;

        case "EXPAND_ELEMENT": {
          // Find element and trigger click/expand
          const element = document.querySelector(`[data-tour="${payload}"]`);
          if (element && element.click) {
            element.click();
          }
          break;
        }

        case "CLOSE_PANEL":
          if (
            payload === "advanced-settings" &&
            appContext.setShowAdvancedConfig
          ) {
            appContext.setShowAdvancedConfig(false);
          } else if (
            payload === "gen-settings" &&
            appContext.setShowGenSettings
          ) {
            appContext.setShowGenSettings(false);
          }
          break;

        case "CLOSE_MODAL":
          if (payload === "critique" && appContext.setShowCritiqueModal) {
            appContext.setShowCritiqueModal(false);
          }
          break;

        default:
          console.warn(`[Tutorial] Unknown action type: ${type}`);
      }
    } catch (error) {
      console.error("[Tutorial] Error executing step action:", error);
      logTutorialEvent(TUTORIAL_EVENTS.ERROR, {
        scenarioId: activeScenario,
        stepId: step.id,
        error: "action_execution_failed",
        actionType: type,
      });
    }
  };

  /**
   * Starts a specific tutorial scenario with validation
   * @param {string} scenarioId - The key from TUTORIAL_SCENARIOS (e.g., 'create', 'review')
   */
  const handleStartTutorial = (scenarioId = "welcome") => {
    const targetScenario = TUTORIAL_SCENARIOS[scenarioId];

    if (!targetScenario) {
      const error = `Tutorial scenario '${scenarioId}' not found`;
      console.error(error);
      setTutorialState(TUTORIAL_STATES.ERROR);
      setErrorMessage(error);
      onError?.(error);

      logTutorialEvent(TUTORIAL_EVENTS.ERROR, {
        scenarioId,
        error: "scenario_not_found",
      });
      return;
    }

    // Validate scenario
    const errors = validateScenario(targetScenario, scenarioId);
    if (errors.length > 0) {
      console.warn("Tutorial validation warnings:", errors);
      // Don't block tutorial, just warn
    }

    // Log start event
    logTutorialEvent(TUTORIAL_EVENTS.STARTED, {
      scenarioId,
      stepCount: targetScenario.steps.length,
    });

    setActiveScenario(scenarioId);
    setCurrentStep(0);
    setTutorialState(TUTORIAL_STATES.ACTIVE);
    setErrorMessage(null);

    // Execute action for first step after a brief delay
    setTimeout(() => {
      executeStepAction(targetScenario.steps[0]);
    }, 100);
  };

  /**
   * Navigate to next step (with state guard)
   */
  const handleTutorialNext = () => {
    if (tutorialState !== TUTORIAL_STATES.ACTIVE) {
      console.warn("Cannot navigate: tutorial not active");
      return;
    }

    const newStep = Math.min(currentStep + 1, tutorialSteps.length - 1);

    logTutorialEvent(TUTORIAL_EVENTS.STEP_CHANGED, {
      scenarioId: activeScenario,
      fromStep: currentStep,
      toStep: newStep,
      stepId: tutorialSteps[newStep]?.id,
    });

    setCurrentStep(newStep);

    // Execute step action after a brief delay to allow state to update
    setTimeout(() => {
      executeStepAction(tutorialSteps[newStep]);
    }, 100);
  };

  /**
   * Navigate to previous step (with state guard)
   */
  const handleTutorialPrev = () => {
    if (tutorialState !== TUTORIAL_STATES.ACTIVE) {
      console.warn("Cannot navigate: tutorial not active");
      return;
    }

    const newStep = Math.max(currentStep - 1, 0);

    logTutorialEvent(TUTORIAL_EVENTS.STEP_CHANGED, {
      scenarioId: activeScenario,
      fromStep: currentStep,
      toStep: newStep,
      stepId: tutorialSteps[newStep]?.id,
    });

    setCurrentStep(newStep);
  };

  /**
   * Skip/cancel the tutorial
   * Also marks as completed so it doesn't re-trigger on next visit
   */
  const handleTutorialSkip = () => {
    if (tutorialState !== TUTORIAL_STATES.ACTIVE) {
      return;
    }

    logTutorialEvent(TUTORIAL_EVENTS.SKIPPED, {
      scenarioId: activeScenario,
      atStep: currentStep,
      stepId: tutorialSteps[currentStep]?.id,
    });

    // Mark as completed so it doesn't auto-trigger again
    // Users can restart manually from the tutorial button if needed
    if (activeScenario) {
      setScenarioCompleted(activeScenario);
    }

    setTutorialState(TUTORIAL_STATES.IDLE);
    setActiveScenario(null);
    setCurrentStep(0);
  };

  /**
   * Complete the tutorial
   */
  const handleTutorialComplete = () => {
    if (tutorialState !== TUTORIAL_STATES.ACTIVE) {
      return;
    }

    logTutorialEvent(TUTORIAL_EVENTS.COMPLETED, {
      scenarioId: activeScenario,
      totalSteps: tutorialSteps.length,
    });

    // Mark as completed with timestamp
    setScenarioCompleted(activeScenario);

    setTutorialState(TUTORIAL_STATES.COMPLETED);

    // Show success message
    if (showMessage) {
      showMessage(`Γ£à Tutorial completed!`, 2000);
    }

    // Reset to idle after a brief delay
    setTimeout(() => {
      setTutorialState(TUTORIAL_STATES.IDLE);
      setActiveScenario(null);
      setCurrentStep(0);
    }, 500);
  };

  /**
   * Restart the current tutorial scenario
   */
  const handleRestartTutorial = () => {
    if (!activeScenario) {
      console.warn("Cannot restart: no active scenario");
      return;
    }

    const scenarioToRestart = activeScenario;
    handleStartTutorial(scenarioToRestart);

    if (showMessage) {
      showMessage(`Restarting ${scenarioToRestart} tutorial!`, 2000);
    }
  };

  return {
    // State
    tutorialActive,
    currentStep,
    tutorialSteps,
    activeScenario,
    tutorialState,
    errorMessage,

    // Handlers
    handleTutorialNext,
    handleTutorialPrev,
    handleTutorialSkip,
    handleTutorialComplete,
    handleRestartTutorial,
    handleStartTutorial,

    // Helper
    isScenarioCompleted,
  };
};

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
