  }
} catch (e) {
  console.warn("Failed to load offline queue:", e);
}

// Save queue to localStorage
const persistQueue = () => {
  try {
    localStorage.setItem("ue5_offline_queue", JSON.stringify(offlineQueue));
  } catch (e) {
    console.warn("Failed to persist offline queue:", e);
  }
