// Connection status listeners
if (typeof window !== "undefined") {
  window.addEventListener("online", () => {
    console.log("≡ƒîÉ Connection restored");
    isOnline = true;
    processOfflineQueue();
  });

  window.addEventListener("offline", () => {
    console.log("≡ƒô┤ Connection lost");
    isOnline = false;
  });
}

// Process queued items when back online
const processOfflineQueue = async () => {
  if (syncInProgress || offlineQueue.length === 0) return;

  syncInProgress = true;
  console.log(`≡ƒöä Processing ${offlineQueue.length} queued items...`);

  const itemsToProcess = [...offlineQueue];
  offlineQueue = [];

  for (const item of itemsToProcess) {
    try {
      await saveQuestionToFirestoreInternal(item.question);
      console.log(`Γ£ô Synced queued item: ${item.question.uniqueId}`);
    } catch (err) {
      console.warn(
        `Failed to sync ${item.question.uniqueId}, re-queuing:`,
        err
      );
      offlineQueue.push(item);
    }
  }

  persistQueue();
  syncInProgress = false;

  if (offlineQueue.length > 0) {
    console.log(`ΓÜá∩╕Å ${offlineQueue.length} items still queued`);
  }
};

// Get connection and sync status (for UI)
