/**
 * Apply scores to Firestore in batches of 500 (Firestore limit)
 */
export async function applyScoresToFirestore(onProgress) {
  console.log(`≡ƒöÑ Starting score import for ${allBatches.length} questions...`);

  let updated = 0;
  let errors = 0;
  const BATCH_SIZE = 500;

  // Process in chunks
  for (let i = 0; i < allBatches.length; i += BATCH_SIZE) {
    const chunk = allBatches.slice(i, i + BATCH_SIZE);
    const batch = writeBatch(db);

    for (const entry of chunk) {
      const questionId = String(entry.id);
      const score = entry.originalScore;

      try {
        const docRef = doc(db, "questions", questionId);
        batch.update(docRef, {
          aiScore: score,
          scoredAt: new Date(),
          scoreSource: "Strict_AI_Batch_Import",
        });
        updated++;
      } catch (error) {
        console.error(`Γ¥î Error preparing update for ${questionId}:`, error);
        errors++;
      }
    }

    // Commit batch
    try {
      await batch.commit();
      console.log(
        `Γ£à Batch ${Math.floor(i / BATCH_SIZE) + 1} committed (${
          chunk.length
        } questions)`
      );
      if (onProgress) {
        onProgress({
          current: i + chunk.length,
          total: allBatches.length,
          updated,
          errors,
        });
      }
    } catch (error) {
      console.error(`Γ¥î Failed to commit batch:`, error);
      errors += chunk.length;
    }
  }

  console.log(`\nΓ£à Score import complete!`);
  console.log(`   Updated: ${updated}`);
  console.log(`   Errors: ${errors}`);

  return { updated, errors };
}

